INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '58259457502', 'Tirolez Mussarela Queijo Fatiado', 'O Queijo Mussarela Fatiado Tirolez é a escolha perfeita para quem busca praticidade e sabor no dia a dia. Produzido com leite de alta qualidade, oferece um sabor suave, textura macia e ótimo derretimento. Ideal para pizzas, sanduíches, lasanhas e diversas outras receitas. Já vem fatiado, pronto para usar! Sem glúten, é uma opção segura para pessoas com restrições alimentares. Com a confiança da marca Tirolez, esse queijo une cremosidade e praticidade em cada pedaço.', 11.49, 11.49, NULL, 'Food & Beverages > Dairy & Eggs > Cheese & Cheese Powder', 'https://cf.shopee.com.br/file/sg-11134201-8259z-mqneli7kritc90', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1676555024%2F58259457502', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
