INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '19899318897', 'Pacote 50 Lampada Pingão T10 12V W2,1 X 9,5D Halogena Carros', 'Melhore a visibilidade e a segurança do seu veículo com a Lâmpada Pingão T10 12V W2,1 x 9,5D Halógena. Ideal para diversas aplicações automotivas, essa lâmpada oferece uma iluminação eficiente e duradoura. Seja para luz de posição, sinalização ou painel, a lâmpada T10 é a escolha perfeita para garantir uma iluminação clara e precisa. Especificações Técnicas: Tensão de Operação: 12V Tipo: Halógena Modelo: T10 W2,1 x 9,5D Aplicação: Luz de posição, sinalização, painel automotivo e outras Conteúdo da Embalagem: 50 Lâmpada Pingão T10 12V W2,1 x 9,5D Halógena 12 Volts Unidade 50NTV209', 24.9, 24.9, NULL, 'Spare Parts and Accessories for Vehicles > Spare Parts for Motorcycles > Lighting', 'https://cf.shopee.com.br/file/sg-11134201-7rd3l-lwfsotqxf5rme6', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F278256920%2F19899318897', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
