INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '22897541068', 'Camisa Vasco Retrô Goleiro 1960 Masculina Oficial', 'Camisa retrô licenciada do Vasco, usada pelo lendário goleiro Andrada. Reprodução Oficial da marca Athleta, que fabrica os uniformes da seleção brasileira entre 1950 e 1977, além dos principais clubes do Brasil. Uso casual, indicado para momentos de lazer e ir ao estádio. Matéria 100% algodão. — Característica: • Algodão da época, mais pesado que os tradicionais. • Escudo bordado em alta definição. • Todos os produtos a pronta entrega. • Produto Oficial Licenciado pelo Vasco — Os títulos da década de 1960: • Campeão do Torneio de Santiago - Chile (invicto) • Campeão do Torneio Pentagonal do México • Primeiro Campeão da Taça Guanabara • Campeão do Torneio IV Centenário da cidade do Rio de Janeiro • Campeão do Torneio Rio - São Paulo Medidas Aproximadas: Largura x Altura • P (BR): 53 x 63 • M (BR): 55 x 70 • G (BR): 57 x 72 • GG (BR): 61 x 74 • EGG (BR): 63 x 75 • EEGG (BR): 65 x 79 Informações Adicionais: • Envio imediato. • Todos os produtos a pronta entrega. • Garantia: Contra defeito de fabricação.', 329.9, 296.91, NULL, 'Sports & Outdoors > Sports & Outdoor Apparels > Jerseys', 'https://cf.shopee.com.br/file/br-11134207-820lk-mnlxdbtblvy8d1', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F698219490%2F22897541068', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
