INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '24442941371', 'Bíblia Anote Espiral Céu Azul | NVI | Letra Normal | Com Espaço para Anotações', 'Bíblia Anote Espiral Céu Azul | NVI | Letra Normal | Com Espaço para Anotações Bíblia Sagrada, com a linguagem na versão NVI (Nova Versão Internacional). Dentre as versões da bíblia ela se torna uma das mais modernas e preservando a clareza do texto, permanecendo fiel aos Escritos originais. A bíblia anote com espaço para anotações, é desenvolvido seguindo o gosto de pessoas que tem um hábito e amam desenhar, escrever tudo que o que Deus tem falado com você, popularmente procurada como "journaling". Altura: 24,5 cm Largura: 20,5 cm Profundidade: 3,5 cm', 122.1, 122.1, NULL, 'Books & Magazines > Books > Religion & Philosophy', 'https://cf.shopee.com.br/file/sg-11134201-7rd4c-m7l6lelw62x992', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F400905650%2F24442941371', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '47452089921', 'Manual Cristão da Cultura POP | Richarde Guerra e Sinval Filho', 'Livro Manual Cristão da Cultura POP | Richarde Guerra e Sinval Filho Richarde Guerra e Sinval FilhoA cultura pop dissemina, de forma crescente, uma cosmovisão pós-moderna que frequentemente entra em conflito com os valores cristãos. Diariamente, somos impactados por uma grande quantidade de conteúdo — seja em quadrinhos, séries, filmes, jogos e muitas outras mídias. Neste contexto, surgem perguntas urgentes: como identificar essas influências e usá-las a favor do Evangelho? Como manter a identidade cristã ao consumir entretenimento geek? E, acima de tudo, como se tornar um agente transformador da cultura, produzindo uma cultura pop cristã com relevância e impacto social? Este livro oferece respostas e insights valiosos, abordando conceitos fundamentais sobre cultura, arte e sua relação com a fé cristã. Com uma abordagem clara e aprofundada, "Manual Cristão da Cultura POP" é um guia essencial para quem deseja navegar criticamente nesse universo e contribuir para sua renovação a partir de uma perspectiva bíblica. Sobre os autores: Richarde Guerra é químico, mestre em teologia e pastor da Igreja Batista da Lagoinha, em Belo Horizonte. Nerd assumido e autor de mais de 40 livros, foi finalista do Troféu HQ Mix com a obra "Eclesiástico Mangá". É criador de sucessos como a série "Devocional Turma da Mônica" e o jogo "Aprendendo a Bíblia com a Turma da Mônica". Sinval Filho é jornalista, teólogo e bacharel em Comunicação Social, com MBA em Gestão de Empresas pela FGV. Fundador da Editora 100% Cristão, pioneira no segmento geek cristão, une expertise ministerial e visão empreendedora para conectar fé e cultura pop. Ideal para leitores, criadores de conteúdo, gamers, fãs de HQs e líderes cristãos que buscam engajamento cultural com fundamento e propósito.', 35.81, 35.81, NULL, 'Books & Magazines > Books > Religion & Philosophy', 'https://cf.shopee.com.br/file/sg-11134201-82269-mhhl740lrsw50f', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F400905650%2F47452089921', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '49101131310', 'Pelúcia Hug-A-Lumps Pequena 0,75kg - Lagosta Lenny', 'A Pelúcia Hug-A-Lumps Pequena 0,75kg é perfeita para quem busca conforto com um toque de diversão. Com peso suave e acolhedor, ela proporciona a sensação de um abraço de verdade, ajudando a aliviar o estresse e trazendo bem-estar em qualquer momento do dia. Feita com pelúcia supermacia, é ideal para relaxar, dormir melhor ou simplesmente curtir o carinho de um amigo fofinho. São 7 personagens encantadores para conhecer: Lagosta Lenny, Vaca Marrom Holly, Vaca Clover, Urso Marinho Sage, Peixe-Bolha Bob, Capivara Connie e Axolote Ally — cada um com seu próprio estilo, cores vibrantes e muita personalidade. Compacta e fácil de levar para onde quiser, a Hug-A-Lumps Pequena é a companhia perfeita para todas as idades. Mais do que uma pelúcia, é um abraço que reconforta, acalma e encanta.', 199.99, 199.99, NULL, 'Mom & Baby > Toys > Dolls & Stuffed Toys', 'https://cf.shopee.com.br/file/sg-11134201-821di-mgw7tblv1lvuf9', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F689242394%2F49101131310', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '23196487765', 'Lançador X-shot Skins Griefer com 12 Dardos - Game Over', 'Lançador de Brinquedo XShot SKINS GRIEFER com Dardos de Espuma - Divirta-se com Ação e Precisão! Explore a emoção das batalhas de brincadeira com o incrível lançador de dardos XSHOT! Este brinquedo emocionante oferece horas de diversão e aventura para crianças e até mesmo adultos que adoram ação e precisão. O Lançador XSHOT é projetado para oferecer uma performance excepcional, permitindo que os dardos de espuma alcancem distâncias impressionantes e precisas, proporcionando lançamentos potentes e cheios de emoção. Acompanha 12 dardos.', 142.99, 142.99, NULL, 'Mom & Baby > Toys > Sports & Outdoor Play', 'https://cf.shopee.com.br/file/sg-11134201-7qve3-ljztugfm9wqy61', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F689242394%2F23196487765', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
