INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '22494300074', 'Lubrificante V-lub Vonixx Para Clay Bar 500ml C/ Borrifador', 'V-Lub é um lubrificante de pintura especialmente desenvolvido para uso com a V-Bar Vonixx ou barras descontaminantes em geral. Contém agentes lubrificantes de última geração que reduzem o atrito da barra descontaminante, permitindo um deslizamento suave da V-Bar na pintura e diminuindo as chances de arranhões, além de facilitar o trabalho realizado. O produto contém polímeros de alta tecnologia que proporcionam brilho e ajudam na proteção da pintura.V-Lub pode ser utilizado durante o processo de lixamento.FACILITA A DESCONTAMINAÇÃOREDUZ O ATRITOPROMOVE BRILHO.', 30.16, 30.16, NULL, 'Spare Parts and Accessories for Vehicles > Spare Parts for Automobiles > Suspension and Steering', 'https://cf.shopee.com.br/file/sg-11134201-7rdyg-md3pdb6hygtzed', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1151751638%2F22494300074', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
