INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '20698716717', 'Darrow Actine Oil Control Gel de Limpeza Facial 60g', 'Sabonete Líquido de Limpeza Facial para peles mistas e oleosas. Darrow Actine Control remove as impurezas, reduzindo a secreção de acne e cravos. Sabonete Líquido Facial Darrow Actine Control é ideal para prevenir espinhas, devido aos ativos de com ação de controle bacteriano em sua fórmula. Sua textura líquida proporciona sensação de frescor na pele logo após o uso, enquanto o Complexo de Ativos Dermoenergizantes - com Zinco e Aloe Vera - garante resultados antiacne e antioleosidade. Hipoalergênico. É indicado para a higiene diária e controla a oleosidade por até 9 horas. Actine é a linha Nº1 em prescrição dermatológica para peles oleosas. Fórmula hipoalergênica, não comedogênica e sem corantes. Experimente também a Máscara Esfoliante Darrow Actine com ativos que agem diretamente nos poros para remover a oleosidade e impurezas. * RESULTADO: Pele limpa, oleosidade controlada e combate a acne. * SUGESTÕES DE USO: Massagear o sabonete suavemente na pele umedecida, fazendo espuma; 2. Enxaguar abundantemente. * OBSERVAÇÕES: Imagem Meramente Ilustrativa * ITENS INCLUSOS: 1 Darrow Actine Oil Control Gel de Limpeza Facial 60g', 35.99, 35.99, NULL, 'Beauty > Skincare > Facial Cleanser', 'https://cf.shopee.com.br/file/sg-11134201-7qvew-lj49ll6bynzre4', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F681570887%2F20698716717', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
