INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '23194290855', 'Strike Removedor Piche Asfalto Cola Adesivo Vonixx 500ml', 'STRIKE 500MLITENS INCLUSOS:01 STRIKE 500MLMARCA: VONIXXCÓDIGO: 2018010APLICAÇÃO:STRIKE É UM PRODUTO DE FÓRMULA BALANCEADA QUE AGE NA REMOÇÃO DE PICHE E DA MAIORIA DE RESÍDUOS DE COLAS DE ADESIVOS E ETIQUETAS AUTOCOLANTES EM GERAL.DILUIÇÃO:PRONTO USO.INFORMAÇÕES ADICIONAIS:STRIKE PODE SER USADO PARA REMOÇÃO DE SUJEIRAS INCRUSTADAS;NÃO RECOMENDAMOS O USO DO PRODUTO EM FARÓIS OU SUPERFÍCIES DE POLICARBONATO;-NÃO PREJUDICA O VERNIZ;-NÃO CAUSA MANCHA;-REMOVE A MAIORIA DAS COLAS DE ADESIVOS.MODO DE USAR:1. PULVERIZE UMA PEQUENA QUANTIDADE DO PRODUTO NA ÁREA A SER LIMPA;2. AGUARDE 1 MINUTO E ESFREGUE O PRODUTO COM AJUDA DE UM PINCEL OU PANO DE MICROFIBRA ATÉ SENTIR O DESPRENDIMENTO DA CONTAMINAÇÃO;3. PULVERIZE ÁGUA EM ABUNDÂNCIA E CONTINUE ESFREGANDO PARA A REMOÇÃO TOTAL DO RESÍDUO;4. SEQUE A PEÇA EM SEGUIDA COM UMA MICROFIBRA LIMPA E SECA.OBS: SE NECESSÁRIO REPITA A OPERAÇÃO; O PRODUTO TEM AFINIDADE COM A MAIORIA DE TIPOS DE COLAS DE ADESIVOS, PORÉM É NECESSÁRIO UM PEQUENO TESTE ANTES PARA TER A CERTEZA DA COMPATIBILIDADE DO PRODUTO COM A CONTAMINAÇÃO.*PRODUTO ORIGINAL*COM NOTA FISCAL', 54.62, 54.62, NULL, 'Spare Parts and Accessories for Vehicles > Vehicular Care > Others', 'https://cf.shopee.com.br/file/sg-11134201-7rdyq-md3kn8l5o5q111', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1151751638%2F23194290855', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
