INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '23397918591', 'Modulo Banda Electra 10k2 10000w rms 2 Ohms Cor Preto', 'MÓDULO AMPLIFICADOR ELECTRA 10K 2 Ohms A linha ELECTRA foi desenvolvida especialmente para quem busca um grave incomparável. Possui uma resposta de frequência de 22Hz a 1000Hz. Devido à isto, o ELECTRA irá tocar apenas Subwoofers, Graves e Woofers. O recurso BASS BOOST variável 30 - 80hz em até 12dB é um diferencial, reforçando ainda mais os graves do seu sistema. Projetado em um chassi arrojado em 100% em alumínio, trabalha com potência de 10000 WRMS com 1 canal de entrada para ligação e impedância de 2 Ohms. Possui baixíssima distorção harmônica e indicador de Clipping, ventilação forçada e proteção contra curto circuito. ESPECIFICAÇÕES TÉCNICAS - Potência Máxima 12,6v @ 2 Ohms: 10000 WRMS - Potência Máxima 12,6v @ 4 Ohms: 8000 WRMS - Eficiência Impedância Nominal: 76% - Tensão de Entrada: 9 - 15V - Impedância de Entrada: 100K Ohms - THD Máxima Potência: <1,5% - Sensibilidade de Entrada: 300mV a 8V - Relação Sinal Ruído: 80dBs - Resposta em Frequência: 22 a 1000Hz (-3dBs) - HPF (Subsônico): 22 - 65Hz - LPF (Crossover): 80 - 250Hz - Bass Boost Variável: 30 - 80hz em até 12dB - Fusível Recomendado: 600A - Corrente de Repouso: ~2,5A - Corrente Máxima (sinal musical): 500A - Corrente Máxima (sinal senoidal): 1000A - Cabos de Alimentação (mín. recomendado): 70mm / 0 AWG - Peso (Kg): 9,2 - Altura (mm): 73 - Largura (mm): 256 - Profundidade (mm): 452', 2859.99, 2314.9, NULL, 'Spare Parts and Accessories for Vehicles > Internal Accessories for Automobiles > Car Audio System', 'https://cf.shopee.com.br/file/br-11134207-7r98o-m1ctiflja37k3a', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F411060907%2F23397918591', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '23994803340', 'Headset com Fio HF250 P3 + USB 150cm Multi - PH467', 'Headset com Fio HF250 P3 + USB 150cm Multi - PH467 O Headset com Fio HF250 Multi PH467 foi projetado para oferecer versatilidade, conforto e clareza sonora em todas as suas atividades. Ideal para trabalho, estudo, reuniões online, videoaulas e chamadas, ele combina praticidade e desempenho em um único acessório. Com conexões P3 (3,5 mm) e USB, o HF250 garante compatibilidade com uma ampla variedade de dispositivos - notebooks, PCs, tablets e outros equipamentos modernos. Seus drivers de 40mm entregam áudio limpo, equilibrado e mais detalhado, proporcionando uma experiência mais nítida tanto para voz quanto para multimídia. O microfone giratório oferece posicionamento preciso e comunicação clara, facilitando o uso em chamadas, videoconferências e ambientes profissionais. Para maior conforto, o headset conta com hastes ajustáveis, earpads macios e um cabo de 1,5 metro, que permite liberdade de movimento e uso prolongado sem incômodos. Leve, confortável e versátil, o HF250 PH467 é a solução perfeita para quem busca um headset eficiente e acessível para o dia a dia. Características Principais - Conexões P3 + USB para compatibilidade total - Drivers de 40mm que garantem som mais limpo e detalhado - Microfone giratório para ajuste ideal e comunicação clara - Hastes ajustáveis para conforto prolongado - Cabo de 1,5m para liberdade de movimento - Earpads macios e confortáveis - Ideal para reuniões, estudos e uso profissional Ficha Técnica Marca: Multi Modelo: Headset com Fio HF250 P3 + USB 150cm Multi - PH467 Tipo: Headset com fio Drivers: 40 mm Conexões: P3 (3.5mm) + USB Comprimento do cabo: 1,5 m Microfone: Giratório Hastes: Ajustáveis Earpads: Macios e confortáveis Compatibilidade: Notebooks, PCs, tablets e dispositivos com P3 ou USB Uso indicado: Trabalho, estudo, reuniões online, videochamadas Conteúdo da embalagem: 1 Headset HF250 Multi, 1 Adaptador USB, Manual do usuário Garantia: 3 Anos Imagens meramente ilustrativas.', 87.89, 79.9, NULL, 'Audio > Earphones, Headphones & Headsets', 'https://cf.shopee.com.br/file/sg-11134201-82602-mjr0xihv5ybm17', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F750964153%2F23994803340', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
