INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '23597144739', 'Kit 2 Glucerna SR Pó Sabor Baunilha 400g', 'SUPLEMENTO NUTRICIONAL GLUCERNA PÓ SABOR BAUNILHA Glucerna é um alimento para suplementação nutricional com exclusivo carboidrato de lenta absorção, diminuindo os picos de glicose no sangue para quem busca manter energia no seu dia-a-dia. Possui baixos teores de açúcares, sem sacarose, lactose e não contém glúten. Usar sob orientação de nutricionista e/ou médico. Uso exclusivo para nutrição enteral ou oral. Proibido o uso por via parenteral. Usar dentro do prazo de validade impresso na embalagem. Não utilizar em galactosemia.', 243.98, 243.98, NULL, 'Health > Food Supplement > Well Being', 'https://cf.shopee.com.br/file/sg-11134201-823q6-mol8v3kytb7k7b', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F893869193%2F23597144739', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
