INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '23798355378', 'Car 80 Descarbonizante Car80 Limpa Bico Tbi Carburadores', 'DESCARBONIZANTE CAR80 LIMPA BICOS CARBURADORES TBI Descarbonizante de motores (automóveis e motos). Alta tecnologia em uma só fórmula. O CAR 80 foi desenvolvido e formulado para proporcionar o máximo desempenho em motores a etanol, gasolina, flex ou gás natural veicular (GNV). CAR 80 limpa completamente, externa e internamente os componentes do sistema de alimentação do motor, removendo óxidos e dissolvendo gomas e vernizes que, com o tempo, obstruem os canais e furos de passagem do sistema. APLICAÇÃO: Limpeza de componentes carbonizados. Limpeza de bicos injetores. Limpeza do sistema de admissão (corpo de borboleta, motor de passo, coletor de admissão e válvulas de admissão). Limpeza de carburador. ATENÇÃO - A MOVE AUTOPARTS não se responsabiliza pelo mau uso ou instalação indevida do produto, sempre recomendamos que a instalação seja feita por um profissional especializado. - Imagens meramente ilustrativas.', 38.5, 38.5, NULL, 'Spare Parts and Accessories for Vehicles > Spare Parts for Automobiles > Others', 'https://cf.shopee.com.br/file/br-11134275-7r98o-m7wbqzrhmyoh9c', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1463823458%2F23798355378', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
