INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '22594855003', 'Panqueca de Cobre 5/8 pol Termomecânica Pancake PK122O60023477 15 Metros', 'Panqueca de Cobre 5/8 pol Termomecânica Pancake PK122O60023477 15 MetrosÉ a escolha ideal para quem busca eficiência, durabilidade e facilidade de instalação em sistemas de refrigeração e ar-condicionado. Fabricada com cobre de alta pureza, oferece excelente condutividade térmica e resistência à corrosão, garantindo desempenho superior e longa vida útil. Seu formato em rolo de 15 metros facilita o transporte e o manuseio, permitindo cortes precisos conforme a necessidade do projeto. Com diâmetro externo de 5/8 pol (15,87 mm), a tubulação proporciona o dimensionamento perfeito para instalações de médias e grandes capacidades, assegurando a passagem ideal do fluido refrigerante com mínima perda de pressão. A espessura de parede 1/32F é outro destaque, representando a espessura ideal que alia resistência e flexibilidade, possibilitando curvaturas suaves durante a instalação sem a necessidade de conexões adicionais — o que reduz o risco de vazamentos e melhora a eficiência do sistema. A Panqueca de Cobre Termomecânica é sinônimo de confiabilidade e praticidade para técnicos e instaladores. Sua estrutura flexível e uniforme garante vedação perfeita e compatibilidade com diversos tipos de gases refrigerantes, incluindo os mais modernos e ecológicos. Com 15 metros de comprimento, atende diferentes demandas de instalação, oferecendo ótimo custo-benefício e desempenho técnico superior em refrigeração residencial, comercial e industrial.', 749.9, 749.9, NULL, 'Home & Living > Tools & Home Improvement > Industrial Adhesives & Tapes', 'https://cf.shopee.com.br/file/sg-11134201-8261z-mkctdpj2ccg8a8', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1398462025%2F22594855003', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
