INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '22297738143', 'Cepacol Menta Fusion Com 500Ml', 'Cepacol Menta Fusion 500ml: Antisséptico Bucal com Flúor e Frescor Intenso (Econômico) O Enxaguante Bucal Cepacol Menta Fusion de 500ml é ideal para a higiene bucal diária, combatendo os germes que causam placa, mau hálito e gengivite. Sua fórmula potente alcança toda a boca, complementando a escovação. Com Flúor, fortalece o esmalte dos dentes e previne cáries. O sabor Menta Fusion proporciona um hálito fresco e uma sensação de limpeza intensa e prolongada. O frasco de 500ml é econômico e ideal para uso familiar contínuo. Contém álcool (verificar embalagem). Uso regular seguro. Proteção com Flúor e Economia: Com Flúor: Proteção ativa contra cáries e fortalecimento do esmalte.Menta Fusion: Hálito fresco duradouro e intenso. 500ml Econômico: Alto rendimento para uso familiar. Antisséptico: Combate germes, placa e mau hálito. Use após a escovação. Bocheche 20ml por 30 segundos. Não engolir. A proteção bucal completa com o frescor potente e eficaz de Cepacol Menta Fusion.', 39.26, 39.26, NULL, 'Health > Personal Care > Oral Care', 'https://cf.shopee.com.br/file/sg-11134201-7rdx9-lz82s8fpzd139a', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1251200960%2F22297738143', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
