INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '12611904703', 'Filtro de Ar Cg 125 Titan / Cg 125 Fan Valflex', 'Filtro de Ar A finalidade desse componente é filtrar o ar, impedindo que partículas de poeiras e impurezas penetrem no sistema do motor durante a captação de oxigênio, utilizado para ocorrer a combustão. O filtro de ar impede que partículas de sujeira cheguem à câmara de combustão. Além disso, a peça ajuda a manter o ar do ambiente interno livre da poluição, ou seja, outra boa razão para conservarmos esse componente sempre em boas condições. Compatível com: TITAN 125 KS ES ESD 2000 A 2008 FAN 125 KS ES ESD 2005 A 2008 Especificações Técnicas: - Qualidade em elementos filtrantes, desenvolvido para motores de alto desempenho; - Possui Selo Iso 26000 - Proporciona Melhor Queima de Combustível e Ajuda a Diminuir a Emissão de Gases Poluentes - Oferece Menor Desgaste dos Componentes Internos do Motor - Maior Durabilidade e Qualidade de Filtração - Filtro de alto padrão desenvolvido com elementos filtrantes que equivalem as características técnicas exigidas pelos fabricantes de motocicletas - Fluxo de ar: Compatível com a especificação do fabricante - Não Lavável Importante: - Recomendamos que a instalação seja feita por profissional especializado e não nos responsabilizamos pelo mau uso do produto.', 39.9, 35.91, NULL, 'Spare Parts and Accessories for Vehicles > Spare Parts for Motorcycles > Filters', 'https://cf.shopee.com.br/file/8f45ce5fc846616b08a72ad40a51ca0b', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F316500472%2F12611904703', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
