INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '23492890538', 'Tanque de Combustível Plástico 11 Litros Dt 180 De 85 a 97 Azul / Branco / Preto / Vermelho', 'EMPRESA: J&J MOTORCYCLES Veja Algumas das Vantagens de Comprar Conosco: • Rapidez no Envio • Ótimo Atendimento • Compra Totalmente Segura ......................................................................................................................................................... PRODUTO: Tanque de Combustível Plástico 11 Litros Dt 180 De 85 a 97 ......................................................................................................................................................... DESCRIÇÃO: • 1 Tanque De Combustível • 1 Tampa do Tanque Com Rosca • 1 Par de Adesivos já Aplicado • Capacidade: 11 Litros • Peso: 2,30 Kg • Material: Polímero Injetado Reforçado • Parade Do Galão: 5mm • Altura: 30cm • Comprimento: 51cm • Largura: 27cm • Aplicação: - Marca: Yamaha - Modelo: Dt 180 - Versão: Todos - Ano: De 1985 a 1997 • Fabricante: X-Cell • Cores: Azul / Branco / Preto / Vermelho • Produto com Excelente Qualidade e Acabamento ......................................................................................................................................................... INFORMAÇÃO ADICIONAIS: • O tanque X-cell Replica da DT 180 é para substituir a o tanque de fábrica da motocicleta deixando a moto mais leve e tendo um melhor custo benefício, já acompanha aplicado os adesivos do tanque • Seguindo mesmo formato do modelo de fábrica, o tanque não aceita a pintura automotiva, o tanque já vai ponto para a utilização. • A tampa do tanque que acompanha é de plástico e de rosquear, (não é possível utilizara tampa de fábrica com chave). • A torneira do tanque pode ser utilizada a do modelo de fábrica. • Fabricado em plástico flexível garante uma peça leve e resistente a queda. • Lave o seu tanque por dentro com água antes de utilizar e SEMPRE utilize filtro na sua torneira de combustível. • Pequenos resíduos plásticos decorrentes do processo de fabricação e sujidades presentes no combustível podem danificar o veículo.', 529.91, 529.91, NULL, 'Spare Parts and Accessories for Vehicles > Spare Parts for Motorcycles > Chassis', 'https://cf.shopee.com.br/file/br-11134207-7r98o-lstxaxd3sffoe5', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F307813655%2F23492890538', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '23794279761', 'Tênis Infantil Bibi Fisioflex 5.0 Azul Marinho com Rosa', 'Conheça a nova linha Fisioflex 5.0, criada para acompanhar os primeiros passos das crianças com máxima segurança e conforto. Desenvolvido em parceria com médicos e especialistas, este tênis une inovação fisiológica e estilo em um só produto. Destaques do tênis Fisioflex 5.0: Solado Flexível: Facilita os movimentos naturais dos pés, ideal para o crescimento saudável. Biqueira Super Resistente: Protege os dedinhos e aumenta a durabilidade do calçado. Palmilha Fisioflex: Simula a sensação de andar descalço, estimulando a percepção sensorial e as terminações nervosas. Materiais Não Tóxicos: Garantem a segurança e a saúde das pequenas. Respirabilidade: Mantém os pés livres de transpiração, priorizando conforto e bem-estar. Aposte na qualidade e inovação do tênis Fisioflex 5.0 e proporcione o melhor para a sua filha. Adquira agora e veja a sua pequena dar cada passo com segurança e conforto!', 189.9, 189.9, NULL, 'Baby & Kids Fashion > Girl Shoes > Sneakers', 'https://cf.shopee.com.br/file/sg-11134201-7rdye-mcwhajby9ohsa2', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1325759944%2F23794279761', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
