INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '23192407543', 'Kit Sabonete Em Barra Dove Karite 90g - 36 Unidades', 'O Sabonete Dove Karité desenvolvido para hidratar a pele ao mesmo tempo que ajuda a remover as impurezas prejudiciais a saúde. Enriquecido com emolientes que ajudam a controlar os nutrientes necessários para manter a pele macia e livre do ressecamento precoce. Além de deixar sensação de bem estar prolongado. O Sabonete Dove Karité forma uma espuma suave e perfumada que não agride o PH natural da pele, tornando o banho ainda seguro e de qualidade para você e sua família. Modo de usar: Aplique o Sabonete sobre uma esponja de banho, e esfregue suavemente sobre a pele do até a formação de uma espuma cremosa. Espalhe a espuma pelo corpo delicadamente de forma uniforme. Enxágue logo em seguida.', 210.52, 143.94, NULL, 'Beauty > Bath & Body Care > Body Wash & Soap', 'https://cf.shopee.com.br/file/sg-11134201-7rdwj-mcm4r0bfkspg04', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F683941545%2F23192407543', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
