INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '14794741541', 'Rack Madesa Metz e Painel para TV até 55 Polegadas - Rustic/Branco', 'O Kit Rack Metz e Painel de TV é ideal para uma sala aconchegante, funcional e prática. O Rack Metz está disponível em duas versões, que combinam os tons branco e amadeirado Rustic e dispõe de 2 portas grandes e nichos abertos que acomodam os aparelhos eletrônicos de maneira prática. É um móvel robusto e com bastante espaço. Nesta versão, combinado com o Painel de TV branco para televisores de até 55 polegadas, possibilita um ganho extra de espaço. O acabamento dos produtos é em Pintura Poliéster de 7 camadas de alta resistência, detalhe que confere mais qualidade e durabilidade aos móveis. Itens inclusos: - Um (1) Rack com 48 cm de altura x 180 cm de largura x 39 cm de profundidade. - Um (1) Painel de TV com 72 cm de altura x 136 cm de largura. Código do produto: MDES0200026E Obs.: A Madesa não disponibiliza serviço de montagem. A Madesa possui compromisso com a sustentabilidade. Geramos energia limpa em nossa própria usina, priorizamos fornecedores responsáveis e utilizamos plástico reciclado em nossa produção. Além disso, reinserimos sobras no ciclo de reciclagem e investimos no desenvolvimento de nossos colaboradores e da comunidade. Garantia: Este produto conta com 1 ano de garantia total, sendo 3 meses de garantia legal e 9 meses de garantia contratual. A garantia cobre exclusivamente defeitos de fabricação e vícios ocultos. Não estão cobertos: problemas decorrentes de montagem incorreta, uso inadequado, exposição à umidade, calor ou luz solar direta, modificações no produto ou desgaste natural.', 689.99, 586.95, NULL, 'Home & Living > Furniture > Shelves & Racks', 'https://cf.shopee.com.br/file/sg-11134201-22110-rfafwa9gxljv60', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F872473112%2F14794741541', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '23593141720', 'Cesta Cestinha de Plástico para Bicicleta Bike Aro 20 e 26 Grande Preta Resistente Reforçada', 'Essa cesta para bicicleta é perfeita para transportar seus objetos com segurança, praticidade e estilo. Um produto de excelente qualidade e ótimo custo-benefício, ideal para quem precisa de mais funcionalidade no dia a dia. Ideal para levar bolsas, sacolas, itens de feira ou mercado, facilitando o transporte durante seus deslocamentos urbanos ou até mesmo um passeio na praia. Especificações Técnicas: - Material: Plástico resistente - Cor: Preta - Tamanho aproximado: 33 cm (largura) x 25 cm (altura) - Peso: 410g (vazia) - Capacidade máxima: 8 Kg - Acompanha kit de instalação (haste e parafusos) - Instalação fácil e rápida na dianteira da bicicleta - Ideal para uso urbano, compras e transporte leve - Compatível com bicicletas aro 24, 26, 27.5 e 29 ✓ Com garantia e nota fiscal ✓ Envio no mesmo dia para pedidos com pagamento aprovado até as 11h ✓ Envio Imediato para todo Brasil Produto Novo | Garantia | Estoque disponível | Pronta Entrega | Envio Imediato Para Todo Brasil | Nota Fiscal', 49.9, 26.95, NULL, 'Sports & Outdoors > Sports & Outdoor Recreation Equipments > Cycling', 'https://cf.shopee.com.br/file/br-11134207-7r98o-lxu2lg760q7zf8', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F801784100%2F23593141720', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
