INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '23993927405', 'H''maston HM-TF128 Pen Drive 2 Em 1 Tipo C pen drive Memória Vara 8 /16/32/64/128GB cle flash memoria', 'Design de rotação de 360° Projetado para as necessidades de armazenamento em constante mudança de hoje, este pen drive possui conectores USB e Tipo C para transferências de dados fáceis. O pen drive USBC com o inovador design giratório de 360° para proteger os conectores e o design de ponto preso de 90° evita que o drive gire aleatoriamente. Design conveniente de furo de chaveiro, você pode pendurar o pen drive USB em um chaveiro. A unidade flash USB de 128GB é a solução perfeita para armazenar todos os seus arquivos de forma segura e conveniente. Com seu design resistente à água, você pode ter certeza de que seus dados estarão protegidos o tempo todo. Compatível com Windows, Linux e macOS, é ideal para qualquer tipo de usuário. Com dois tipos de conectores USB-A e USB-C, essa memória USB é versátil e se adapta às suas necessidades de conexão. Sua capacidade de armazenamento de 128GB permite salvar uma grande quantidade de arquivos de documentos importantes em fotos e vídeos de alta resolução. Possui a versão mais recente da porta USB 3.0 compatível com as versões anteriores, o que garante uma transferência de dados rápida e eficiente. Seja para uso pessoal ou profissional, esta unidade flash USB é a ferramenta perfeita para levar seus arquivos aonde quer que você vá.', 80.0, 45.99, NULL, 'Computers & Accessories > Data Storage > Flash Drives & OTG', 'https://cf.shopee.com.br/file/br-11134207-7r98o-m92nzeld3wahbe', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1155571749%2F23993927405', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '26592430882', 'Capa Anti Impacto AZ Defender Magnetic P/ iPhone 17 Pro Max', 'Capa Anti Impacto AZ Defender Magnetic Para iPhone 17 Pro Max A AZ Defender é a escolha ideal para quem busca máxima proteção sem abrir mão da praticidade. Projetada para absorver impactos, essa capa possui bordas reforçadas com tecnologia antichoque, garantindo maior resistência contra quedas e batidas do dia a dia. • Compatível com MagSafe – Ímãs embutidos que garantem fixação segura e eficiente para carregadores e acessórios MagSafe. • Proteção reforçada – Feita de TPU de alta resistência, com bordas elevadas para proteger a tela e a câmera. • Design robusto e funcional – Estilo moderno e imponente, perfeito para quem valoriza durabilidade e segurança. • Aderência confortável – Textura antiderrapante para melhor pegada e segurança no uso diário. Garanta já a sua AZ Defender e mantenha seu dispositivo protegido com o melhor da tecnologia e do design!', 109.9, 109.9, NULL, 'Mobile & Gadgets > Accessories > Cases, Covers, & Skins', 'https://cf.shopee.com.br/file/br-11134207-81z1k-mfb419idaj2e32', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F442913304%2F26592430882', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
