INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '23398153547', 'Lâmpada Pisca 12V 10W Base Metálica Laranja Tronik', 'Lâmpada Pisca 12V 10W Base Metálica Laranja Tronik – Qualidade e Visibilidade para a Sua Moto A Lâmpada Pisca 12V 10W com Base Metálica Laranja da Tronik oferece alto desempenho e durabilidade para sinalização eficiente em motocicletas e outros veículos. Projetada para fornecer iluminação intensa e consistente, ela garante que suas intenções de direção sejam claramente percebidas, aumentando a segurança no trânsito. Características: Marca: Tronik Modelo: Lâmpada para pisca Voltagem: 12V Potência: 10W Cor da Luz: Laranja Base: Metálica, com excelente resistência e encaixe firme Benefícios: Maior Segurança: Iluminação forte e vibrante para sinalização eficaz. Durabilidade Superior: Base metálica robusta e construção resistente a vibrações. Instalação Fácil: Compatível com encaixes padrão de lâmpadas de pisca em diversas motocicletas e veículos. Confiabilidade Tronik: Marca reconhecida pela qualidade e desempenho de seus produtos automotivos. Ideal para substituir lâmpadas piscas desgastadas ou com pouca luminosidade, a lâmpada Tronik oferece excelente custo-benefício com qualidade premium.', 19.9, 19.9, NULL, 'Spare Parts and Accessories for Vehicles > Spare Parts for Motorcycles > Lighting', 'https://cf.shopee.com.br/file/sg-11134201-7ra3p-m58xbpjjzykqcc', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F813601541%2F23398153547', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
