INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '23397448765', 'BIGENS KIT 2X BIO SYNERGY D3+K2 MK-7 20ML', 'Bio Synergy D3 + K2 MK7: Potência e Saúde em Cada Gota Apresentamos o Bio Synergy D3 + K2 MK7, uma solução inovadora para suas necessidades diárias de vitaminas. Este suplemento único oferece uma combinação poderosa de vitaminas lipossolúveis, entregues em uma base nutritiva de óleo de abacate. Características principais: Alta Concentração: Cada gota contém 2000ui de Vitamina D3 e 20mcg de Vitamina K2 MK7, garantindo sua dose diária de bem-estar. Óleo de Abacate: A formulação em óleo de abacate não só melhora a absorção das vitaminas mas também adiciona benefícios à saúde do coração e pele. Vitaminas Adicionais: Enriquecido com Vitamina A e E, essenciais para a saúde ocular, imunológica e da pele. Sabor Agradável: O delicioso sabor de limão torna a suplementação uma experiência agradável. Rendimento Excepcional: Com até 500 porções por frasco, este suplemento oferece um excelente custo-benefício. Perfeito para quem busca uma maneira fácil e eficaz de complementar sua dieta com vitaminas essenciais. Experimente o Bio Synergy D3 + K2 MK7 e sinta a diferença na sua saúde! Recomendação de uso: Aplicar 1 via oral, esperar um tempo e engolir. Usar 1 vez ao dia ou conforme a recomendação profissional. A BIOGENS AGORA É BIGENS ! UM NOVO NOME, A MESMA QUALIDADE !', 153.18, 153.18, NULL, 'Health > Food Supplement > Well Being', 'https://cf.shopee.com.br/file/br-11134207-81z1k-mgxu8937mnlxc9', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1059419518%2F23397448765', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '12767095588', 'Carenagem Acessórios Para Moto Cb 300 2010 á 2012 3 Peças Pro Tork', 'O Kit Carenagem 3 Peças CB 300 Pro Tork é fabricado com materiais de alta qualidade, garantindo máxima resistência. Produto com o melhor custo/benefício do mercado, compatível com os modelos de cada montadora. Especificações: - Fabricado em ABS 100% Virgem; - Resistente aos raios UV; - Encaixe perfeito sem necessidade de adaptações; - Não acompanha adesivos; - Não acompanha parafusos; - Marca: Pro Tork. Aplicação: - Prata Force: CB 300 2010; - Amarelo: CB 300 2010 a 2011; - Preto: CB 300 2010 a 2011; - Vermelho Maceió: CB 300 2010 a 2012; - Azul: CB 300 2011; - Amarelo: CB 300 2012; - Azul: CB 300 2012; - Branco: CB 300 2012. Conteúdo da Embalagem: - Rabeta; - Rabeta Central; - Rabeta Lateral. Instalação: - Antes de finalizar a compra, certifique-se de que sua moto seja compatível com algum dos modelos acima. Pois o produto é pronto para instalação e não necessita de nenhum tipo de adaptação; - Para realizar a instalação, leve sua moto à uma oficina especializada; - A Sportbay não se responsabiliza pela má instalação do produto. OBS: - Pode haver diferença de tonalidade entre a imagem e o produto real por conta do tratamento de imagens e a calibração de cores da tela de seu monitor ou aparelho. Sportbay - Seu Esporte, Nossa Paixão.', 168.32, 124.9, NULL, 'Spare Parts and Accessories for Vehicles > Spare Parts for Motorcycles > Chassis', 'https://cf.shopee.com.br/file/br-11134207-7r98o-lqbxw5gaeae768', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F436682589%2F12767095588', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '8155816351', 'Cavalete Lateral Pro Tork Titan 150 Sport Preto ( Sem Borracha )', 'O Cavalete Lateral Pro Tork é confeccionado em aço tubular com espessura semelhante aos modelos originais. O ponto de fixação do parafuso é cortado e furado a laser, garantindo assim a centralização exata com o suporte do chassis da motocicleta. Especificações: - Fabricado em Aço; - Modelo: Lateral; - Cor: Preto; - Imagem ilustrativa; - Marca: Pro Tork. Aplicação: - Titan 150 Sport. - Antes de finalizar a compra, certifique-se de que sua moto seja compatível com algum dos modelos acima. Pois o produto é pronto para instalação e não necessita de nenhum tipo de adaptação. - Para realizar a instalação, leve sua moto à uma oficina especializada. Nós não nos responsabilizamos por danos causados pela má instalação do produto.', 84.11, 43.9, NULL, 'Spare Parts and Accessories for Vehicles > Spare Parts for Motorcycles > Others', 'https://cf.shopee.com.br/file/a24e7883cd6b18f5d988068249af10aa', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F436682589%2F8155816351', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
