INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '23294252519', 'Par de Subwoofer Alto Falantes 8 pol Bomber One 200 Watts RMS 4 Ohms', 'Par Subwoofer 8 pol Bomber One 200 Watts RMS - 4 Ohms Essa linha de Subwoofers, que agora está com novo design, é totalmente desenvolvida para quem procura ótima qualidade sem que seja preciso um altíssimo investimento. Com alta qualidade e excelente tecnologia e desempenho, com uma bobina simples de 4 Ohms de impedância e potência de 200W RMS. Sua sensibilidade é de 86 dB SPL, possui um subcone de celulose, com montagem de calota integral que é feita em IMPP. Especificações Técnicas: • Marca: Bomber • Modelo: SW8BONE-200-4 • Código Ref.: 1.04.140 • Tamanho: 8 pol • Potência RMS: 200 WATTS RMS • Impedância nominal: 4 Ohms • Resposta em frequência (–10 dB)* : 35 Hz - 600 Hz • Resposta em frequência (–3 dB) * : 53 Hz - 1800 Hz • Sensibilidade (Banda efetiva) * : 86 dB SPL • Diâmetro da bobina: 38,9 mm • Altura do enrolamento / Camadas: 18 mm / 2 • Material do corpo da bobina: Alumínio • Material do fio da bobina: Cobre • Altura do gap: 4 mm • Xmax (deslocamento máx. pico): 7 mm • Xlimite (antes do dano): 11 mm • Dimensional do imã: 134 x 16 mm • Material do cone: Celulose • Material suspenção: Espuma • Material da centragem: Algodão • Material da carcaça: Aço • Peso líquido: 2,45 kg • Dimensões do produto (L x A x P): 207 x 207 x 108 mm Parâmetros Thiele/Small • Fs (frequência de ressonância): 44 Hz • Vas (volume equivalente do falante): 14,06 L • Qts (fator de qualidade): 0,92 • Qes (fator de qualidade elétrico): 1,11 • Qms (fator de qualidade mecânico): 5,40 • No (eficiência de referência): 0,10 % • Sd (área efetiva do cone): 214 cm² • BL (densidade de fluxo bobina): 7,3 T.m • Sensibilidade: 82,41 dB SPL • Re (resistência elétrica): 3,64 Ohms • Zmin (impedância mínima): 4,15 Ohms • Mms (massa móvel): 58,77 g • Cms (compliância mecânica): 0,22 mm/N • Le @ 1 kHz (indutância da bobina): 1,62 mH • Le @ 10 kHz (indutância da bobina): 0,65 mH Conteúdo da Embalagem: • 02 Subwoofer 8 pol Bomber One - 200 Watts RMS • Manual Importante: • Garantia de 273 Dias. • Valor do Par.', 461.8, 434.09, NULL, 'Spare Parts and Accessories for Vehicles > Internal Accessories for Automobiles > Car Audio System', 'https://cf.shopee.com.br/file/sg-11134201-7rdyh-mcko1hawij4k34', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F463375702%2F23294252519', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '22596734457', 'Kit 2 Morcegol Repelente para Morcegos - 250 mL', 'Morcegol Repelente para Morcegos - 250 mL - Eficaz contra morcegos; - Produto natural; - Manter fora de alcance de crianças e animais domésticos. Detalhes O Morcegol Repelente para Morcegos - 250 mL é um produto obtido através da técnica japonesa da extração liquida da madeira de eucalipto selecionada, sua composição principal é o Extrato Pirolenhoso. A ação do produto se deve ao odor característico de fumaça, caracterizando fogo no local, causando insegurança para o morcego e sua família, provocando assim o desalojamento, pois por instinto os animais procuram fugir de áreas de incêndio. Dicas Especiais Modo de Uso: Diluir o produto em água limpa e pulverizar em locais que os morcegos se encontram na proporção de 50ml por litro de água. Indicação: Repelentes Composição: Extrato Pirolenhoso 95%; Extrato de Pimenta Espanhola 4%; Fixador 1% Apresentação: Pote 250 mL', 87.64, 77.55, NULL, 'Pets > Pet Grooming > Hair Care', 'https://cf.shopee.com.br/file/sg-11134201-7rbk0-lky14d0cvt0i1b', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F290073877%2F22596734457', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
