INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '48150907653', 'Avemil Complexo Vitamínico 20ml Suplemento Para Pássaros', 'DESCRIÇÃO: AVEMIL COMP VITAMINICO 20ML Avemil Complexo Vitamínico é indicado em todas as fases da vida das aves, incluindo: crescimento, cruzamento, postura, choco, muda de penas e bico. Indicado para estimular o apetite, garantindo o melhor aproveitamento da alimentação. Modo de usar: -Aves e pássaros pequenos (curió, canário, bicudo, trinca ferro e outros) -Diluir 5 gotas no bebedouro de 50ml de água ou 50g de ração, semente ou farinhada. Trocar á água e alimento diariamente. -Aves e pássaros maiores (papagaio, calopsita e outros) -Diluir 10 gotas no bebedouro de 50ml de água ou 50g de ração, semente ou farinhada. Trocar a água e alimento diariamente. Em casos mais severos de avitaminoses, utilizar o produto por um período mínimo de 30 dias. Composição básica: Vitamina A, Vitamina D3, Vitamina E, Vitamina B1, Vitamina B3 (nicotinamida), Vitamina B5, (pantotenato de cálcio), Vitamina B6 e excipientes. Níveis de garantia: Vitamina A (min) 1.200.000 UI/kg Vitamina D3 (min) 800.000 UI/kg Vitamina E (min) 5.000 UI/kg Vitamina B1 (min) 5.000 mg/kg Vitamina B3 (min) 8.000 mg/kg Vitamina B5 (min) 2.000 mg/kg Vitamina B6 (min) 2.000 mg/kg ------------------------------------------------------------------------------------------------------------------ A MANADA ANIMAL é um marketplace de produtos veterinários. É a escolha certa para tutores que prezam pela qualidade dos produtos que seu animal necessita. Tudo com o suporte de uma equipe de veterinários e gestores com mais de 10 anos de experiência no mercado. Fique tranquilo, todos os nossos produtos são originais, adquiridos através de distribuidores credenciados! Ah, e todas as vendas acompanham nota fiscal! MANADA ANIMAL, Tranquilidade pra você, cuidado para ele!', 16.65, 8.06, NULL, 'Pets > Pet Food > Bird Feed', 'https://cf.shopee.com.br/file/sg-11134201-821dw-mgphrjd86ney8e', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F450664666%2F48150907653', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
