INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '58252071396', 'Boina Espuma Azul Suave Lustro Hyper 5 Polegadas Kers', 'A Boina de Espuma de Lustro Hyper Kers é um produto de alta qualidade, caracterizado por um design exclusivo e um brilho ideal para o final do processo de polimento e remoção de marcas circulares na superfície. Este produto é da marca Kers, conhecida por sua excelência e confiabilidade. A boina tem um tipo de corte leve, o que a torna perfeita para um polimento suave e eficaz. Apesar de não ser reutilizável, sua construção em espuma proporciona alto rendimento na etapa de polimento, tornando o processo mais rápido e eficiente. O produto é novo e vem em um kit com uma unidade. O modelo da boina é especificamente projetado para polimento automotivo, com uma densidade leve que permite um acabamento perfeito. A boina tem um diâmetro e profundidade de 0 cm, tornando-a compacta e fácil de manusear. É ideal para uso com uma politriz, garantindo um acabamento profissional em todas as vezes. A quantidade de pads é de 00, o que significa que você tem tudo o que precisa para começar a polir imediatamente.', 55.9, 53.11, NULL, 'Spare Parts and Accessories for Vehicles > Vehicular Care > Pads', 'https://cf.shopee.com.br/file/br-11134207-81z1k-micbwlmtsm4m88', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1687591180%2F58252071396', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '57907324446', 'Bota Feminina Lumiss Cano Médio Salto Anabela Confortável Bico Fino Caramelo', 'Bota feminina de cano médio em material sintético com acabamento liso e sofisticado. O modelo conta com salto anabela baixo que proporciona maior conforto e estabilidade, além do bico levemente fino que valoriza e alonga a silhueta. Versátil e elegante, é ideal para compor produções modernas no dia a dia ou looks mais alinhados para ocasiões especiais, combinando facilmente com calças, saias e vestidos. ..:::.. ESPECIFICAÇÕES DO PRODUTO ..:::.. *Material Externo - Napa Sintética *Material Interno - Helanca, Material Têxtil Super Confortável *Altura do salto - 5,5 cm. *Solado - PVC, Emborrachado, Antiderrapante, Não Faz Barulho, Não Escorrega. *Palmilha - Confortável com aplique da logo. Medida aproximada dos pés para cada numeração: Tamanho 34 --- 25,0 cm Tamanho 35 --- 25,5 cm Tamanho 36 --- 26,0 cm Tamanho 37 --- 27,0 cm Tamanho 38 --- 27,5 cm Tamanho 39 --- 28,5 cm Tamanho 40 --- 29,0 cm SOBRE A LUMISS: Desde 2018, brilha no coração da Lumiss a inovação para calçados femininos. Nascida como Amorelle, a marca é fruto do sonho de um visionário que sempre acreditou na possibilidade de fabricar calçados que surpreendessem o mercado, tanto pela variedade quanto por seus preços acessíveis. Com muito trabalho em família, essa ideia foi levada adiante, fortalecendo uma marca que hoje é referência nacional em calçados femininos, com presença marcante nos marketplaces e mais de dois milhões de pares já entregues em todo o Brasil. Comprometida com cada cliente, a Lumiss oferece as maiores tendências do mundo da moda a partir de materiais que garantem conforto, qualidade, sofisticação e estilo aos pés da mulher brasileira, encantando até mesmo os perfis mais exigentes. Além disso, a empresa se preocupa em oferecer a melhor experiência de compra, com total segurança e praticidade. Lumiss é mais que uma marca. É uma ideia que chegou para mostrar que todas as mulheres podem brilhar e ser ainda mais lindas e confiantes com calçados que as valorizam em todos os aspectos.', 229.9, 119.9, NULL, 'Women Shoes > Boots > Fashion Boots', 'https://cf.shopee.com.br/file/br-11134207-820mb-mlxp2v8j4x6v0c', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F323760756%2F57907324446', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
