INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '15193951598', 'Relogio Masculino Champion Dourado Analógico A Prova D''Água Original Presente Barato CN27670U', 'O Champion CN27670U é um relógio analógico elegante e sofisticado, ideal para homens que buscam um acessório refinado para o dia a dia. Seu design dourado clássico com mostrador preto combina perfeitamente com qualquer ocasião, seja no trabalho ou eventos sociais. Dimensões e Peso ✔ Diâmetro da Caixa: 4,2 cm (MÉDIO) ✔ Espessura: 1,0 cm ✔ Largura da Pulseira: 2,0 cm ✔ Circunferência Máxima: 20 cm ✔ Peso: 101 gramas Materiais de Alta Qualidade ✔ Vidro: Cristal Mineral – resistência contra riscos ✔ Caixa: Metal resistente – acabamento premium ✔ Pulseira: Aço Inoxidável – durabilidade e sofisticação ✔ Tampa do Fundo: Rosqueada – maior vedação Recursos Especiais ✔ Resistência à água 5 ATM – suporta lavagem das mãos e respingos ✔ Mecanismo Quartz – precisão e confiabilidade ✔ Fecho Dobrável com Botão – segurança e conforto Cores e Estilo ✔ Mostrador: Preto – contraste elegante com os detalhes dourados ✔ Caixa e Pulseira: Dourado – visual sofisticado e refinado O Que Vai na Embalagem? ✔ Relógio Original Champion CN27670U ✔ Caixa Original Champion, Manual de Instrução em Português e Certificado de Garantia (1 ano com o fabricante) ✔ Nota Fiscal – autenticidade e segurança garantidas Por que Comprar na RBM WEBSHOP? ✅ Produtos 100% originais, com nota fiscal e garantia oficial ✅ Envio imediato e seguro para todo o Brasil ✅ Atendimento de qualidade – suporte rápido para suas dúvidas Garanta já o seu! Estoque limitado!', 399.0, 269.0, NULL, 'Watches > Men Watches', 'https://cf.shopee.com.br/file/br-11134207-7r98o-lxwtyi093ukyc9', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F356201012%2F15193951598', NULL, NULL, '2026-07-28T02:11:31.708458+00:0