INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '19074748211', 'TERMORETRÁTIL CUSTOMIZADO NTV PARA TERMINAIS DE 35 A 50MM', 'TERMORETRÁTIL CUSTOMIZADO NTV PARA TERMINAIS DE 35 A 50MM O termoretrátil personalizado NTV é ideal para aplicação em terminais e cabos de 35 mm² a 50 mm², proporcionando isolamento, acabamento profissional e identificação personalizada. Ao ser aquecido, o material retrai ajustando-se perfeitamente ao terminal, garantindo proteção contra umidade, abrasão e curto-circuito, além de melhorar a organização do sistema elétrico. Indicado para uso em automotivo, som automotivo, instalações elétricas e projetos profissionais. ESPECIFICAÇÕES TÉCNICAS Tipo: Tubo termoretrátil Marca: NTV Aplicação: Terminais e cabos Bitola compatível: 35 mm² a 50 mm² Função: Isolação e acabamento Produto: Novo COMPATIBILIDADE Compatível com: • cabos de 35 mm² a 50 mm² • terminais elétricos diversos Uso em: • automotivo • som automotivo • instalações elétricas • projetos personalizados CONTEÚDO DA EMBALAGEM 01 Termoretrátil Customizado NTV NTV951', 14.9, 14.9, NULL, 'Spare Parts and Accessories for Vehicles > Vehicular Tools > Others', 'https://cf.shopee.com.br/file/sg-11134201-23030-q1s7mvkr86nvda', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F278256920%2F19074748211', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '51409768151', 'Bonecos DC Batman 30cm Articulados Capuz Vermelho Asa Noturna - Sunny Brinquedos', 'Junte-se ao seus Super heróis favoritos e crie suas próprias aventuras! Os bonecos de ação são cheios de detalhes, articulados, e idênticos aos quadrinhos! Use sua imaginação para criar suas próprias aventuras épicas com os bonecos de ação da linha Batman da DC Comics. Leve a emoção e a aventura deste incrível universo para casa. CARACTERÍSTICAS: - Marca: Sunny Brinquedos - Material: Plástico Resistente - Possui 11 Pontos de Articulação! - Dimensões da Embalagem (L x C x A): 5cm x 10cm x 31cm - Dimensões do Boneco (L x C x A): 4cm x 10cm x 30cm - Peso: 250g - Idade Recomendada: +3 anos - INMETRO: 006748/2021', 99.0, 99.0, NULL, 'Mom & Baby > Toys > Dolls & Stuffed Toys', 'https://cf.shopee.com.br/file/br-11134207-820lc-mnu44y2lem0w55', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F406894684%2F51409768151', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '22493505359', 'Carrinho Azul Marinho de Fricção do Stitch - Stitch', 'Descrição: O alien mais fofo de toda a galáxia chegou para te levar em uma aventura, as novas figuras com veículos são rica em detalhes e totalmente personalizadas para que você possa escolher a sua favorita! Crie memorias e se divirta escolhendo o seu Stitch piloto favorito para ter uma experiencia especial e única. Stitch vem em diversas versões diferentes para você escolher o seu favorito, cada veiculo é inspirado em uma aparição icônica do personagem e único de sua própria maneira, acelere com Stitch e ganhe todas as corridas com ele! Características: Marca: Sunny Brinquedos Referência: 4391 Idade recomendada: A partir de 3 anos Pilhas Inclusas? Tipo de Pilha/Bateria Não necessita de pilhas Possui Luzes: Não Possui Sons: Não Dimensões aproximadas da embalagem: 11 x 9,1 x 6,4cm (A x L x C) Garantia: 3 meses a contar da emissão da Nota Fiscal Embalagem: Conteúdo da embalagem: 1 Carrinho Certificado Inmetro: REGISTRO 009896/2024 Produtos de decoração não inclusos. Imagens meramente ilustrativas. As cores dos objetos podem sofrer alterações devido a luminosidade, configurações do monitor e até mesmo a percepção do usuário.', 69.99, 65.79, NULL, 'Hobbies & Collections > Collectible Items > Action Figurines', 'https://cf.shopee.com.br/file/sg-11134201-7repz-m1ypny9f9qtca9', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F341622697%2F22493505359', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '10608918871', 'Alarme Automotivo Moto Positron Duoblock Pro 350 G8 Universal Presenca', 'Alarme com aplicação universal, compatível com 99% das motocicletas disponíveis no mercado brasileiro. Quando o controle remoto não for utilizado por mais de 25 minutos o mesmo entrará em modo “Econômico”. Ou seja, ele deixará de se comunicar automaticamente com o módulo do alarme, o que permite o prolongamento da vida útil de sua bateria. Para que o controle volte a se comunicar com o alarme, basta movimenta-lo Especificação Técnica: • Compatibilidade Universal • Acompanha 2 Controles DPN58 • Controle Inteligente com Sensor de Movimento • Módulo com Sensor de Movimento Integrado • Chave Master no Módulo: Programação de Forma Simples • Sistema Anticlonagem New Flex-Code • Tecnologia ASIC: Circuito Integrado que Torna o Módulo Mais Resistente às Interferências Eletromagnéticas e Evita Disparos Falsos • Controle por Presença: ao Afastar o Controle da Motocicleta, o Alarme é Acionado • Instalação Segura e Inteligente • Senha Secreta para Habilitar ou Desabilitar o Alarme na Ignição em Caso de Perda do Controle • Função Modo Assalto por Presença: Ao se Afastar, o Alarme Entra em Processo de Bloqueio Progressivo • Grava Até 4 Controles na Memória • Habilitar ou Desabilitar o Alarme com a Senha de Ignição • Beep Personalizado ao Ativar e Desativar o Alarme (6 Opções Diferentes) • Controles Remotos, Módulos e Sirene Selados e Resistentes à Água • Módulo do Alarme com Tensão de Operação de 9 a 16VDC • Corrente Máxima das Conexões de Setas: 5A • Corrente Máxima da Conexão de Bloqueio: 10A • Frequência do Controle Remoto: 433,92MHz • Baixo Consumo da Bateria da Motocicleta', 364.0, 269.9, NULL, 'Spare Parts and Accessories for Vehicles > Vehicular Safety > Alarms and Accessories', 'https://cf.shopee.com.br/file/br-11134207-820lt-moy2yhr5mhoj76', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F411060907%2F10608918871', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '23105411458', 'Alto Falante Subwoofer 12 Polegadas Bomber Upgrade 400w Rms 4 Ohms', 'Upgrade é a linha de Subs da Bomber que é líder de mercado à mais de 15 anos. Ideal para quem busca qualidade sonora, os graves macios e profundos do Upgrade são reflexo de um projeto único. Possui cone em celulose semi prensada impregnado com resina, o que garante linearidade, resistência e durabilidade. CONTEÚDO DA EMBALAGEM • 01 - Alto Falante Subwoofer Bomber Upgrade 350Wrms 4 Ohms 12 Polegadas ESPECIFICAÇÕES TÉCNICAS • Tamanho: 12'''' • Bobina: Bobina Simples • Impedância Bobina: 4 ohms • Material da Carcaça: Metal • Potência Nominal: 400W RMS • Sensibilidade: 87,7 dB • FS (Frequência de Ressonância): 25 Hz • VAS (Volume Equivalente): 156 litros • QTS (Fator de Qualidade Total): 0,5 • QES (Fator de Qualidade Elétrico): 0,62 • QMS (Fator de Qualidade Mecânico): 4,85 • SD (Área Efetiva do Cone): 543 Cm Quadrado • XMax (Deslocamento Máximo do Cone): 9,5 mm • Peso 5700 g', 340.0, 311.99, NULL, 'Spare Parts and Accessories for Vehicles > Internal Accessories for Automobiles > Car Audio System', 'https://cf.shopee.com.br/file/sg-11134201-22110-fdjy9ebx9vjv47', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F411060907%2F23105411458', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '10048756218', 'Antisséptico Bucal Oral-B Complete Menta Leve 500mL e Pague 300mL', 'O Anti-Séptico Bucal Oral-B Complete é gentil com sua boca pois não contém álcool em sua formulação. Contém Cloreto de Cetilpiridínio Monohidratado, um agente de forte ação anti-séptica, clinicamente comprovado que ajuda a combater a formação da placa bacteriana muito mais do que o uso isolado apenas de uma escova dental manual. Além disso, contém Flúor para uma prevenção mais eficaz contra as cáries.', 26.99, 26.99, NULL, 'Health > Personal Care > Oral Care', 'https://cf.shopee.com.br/file/862c76d34f1d0aef3d80c2be1e4364e4', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F528273775%2F10048756218', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '22593951265', 'Isofort Plant 450g Cacau- Vitafor', 'Isofort Plant 450g Cacau- Vitafor Descrição ISOFORT® PLANT é um suplemento alimentar composto por um blend de proteínas vegetais: proteína isolada de ervilha e proteína de arroz. Apresentação Pote com 450g, sabor Cacau Benefícios Vegano; Alternativa para compor o consumo diário proteico de pessoas veganas, vegetarianas e para quem possuí restrições ao consumo de leite; Blend de proteínas vegetais: proteína isolada de ervilha e proteína de arroz; 80% de concentração proteica (24 g) por porção; Com adição de 2423 mg de L-leucina, aminoácido essencial, por porção; 4,1 g de BCAA por porção; Com adição de vitamina B12 de origem vegetal; Variedade em sabores: múltiplas opções de combinações; Selo de Qualidade VLabor Advertência Este produto não é medicamento. Não exceda a dose indicada. Mantenha fora do alcance de crianças. Gestantes, nutrizes e crianças até 3 anos devem consultar o médico antes do uso. Conservar longe de luz, calor e umidade. Indicado para maiores de 19 anos Importante Decoração não inclusa. Imagens ilustrativas. Cores podem variar por luminosidade, monitor ou percepção. Dados fornecidos pelo fabricante/fornecedor.', 171.99, 171.99, NULL, 'Health > Food Supplement > Well Being', 'https://cf.shopee.com.br/file/sg-11134201-7rfh1-m97hjypgmlp5f0', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F341217898%2F22593951265', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '23498538015', 'Adaptador Receptor Bluetooth 5.4 Ugreen Usb A/p2 Preto', 'Adaptador Receptor Bluetooth 5.4 Ugreen Usb A/p2 para Carro Preto, Áudio de Alta Fidelidade, Conexão Estável, Cabo Nylon Trançado, Plug and Play - 35002 1. O adaptador receptor Bluetooth Ugreen utiliza a avançada tecnologia Bluetooth 5.4, garantindo conexão rápida, estável e com menor atraso na transmissão. Ideal para streaming de áudio em alta fidelidade, ele supera os modelos Bluetooth 5.0, oferecendo som claro e sem perdas. 2. Equipado com botões multifuncionais para controle de volume, atendimento de chamadas e retorno de chamadas, o dispositivo oferece praticidade e segurança durante o uso. A luz LED indica o status da bateria, facilitando o monitoramento e o uso em ambientes com pouca luz. 3. Com instalação Plug and Play, basta conectar o adaptador na entrada P2 de 3,5 mm e na porta USB para energia. Compatível para uso em carros, ele se conecta automaticamente ao smartphone e permite o pareamento simultâneo de dois dispositivos para música e chamadas hands-free. 4. O microfone aprimorado filtra ruídos externos, proporcionando chamadas nítidas e cristalinas, mesmo em ambientes barulhentos como o trânsito. O alcance de até 10 metros garante liberdade de movimento sem interrupções no áudio, ideal para viagens e uso diário. Distância de transmissão até 10m, conector 3,5mm, USB-A. 5. Construído com cabo trançado de náilon resistente e várias camadas de blindagem, o adaptador oferece durabilidade, resistência à corrosão e mínima interferência de sinal. Essa qualidade garante longa vida útil e desempenho consistente. Garantia 90 dias.', 184.06, 184.06, NULL, 'Mobile & Gadgets > Accessories > Cables, Chargers & Converters', 'https://cf.shopee.com.br/file/br-11134275-7r98o-ma43kdrvpvcq82', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1163157664%2F23498538015', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '23598516185', 'Cabo de Dados Ugreen Us290 Usb 2.0 p Micro Usb 2m', 'Cabo de Dados Ugreen Us290 Usb 2.0 p Micro Usb 2 Metros de Comprimento Velocidade de Até 480Mbs para Carregamento Sincronização de Dados / No Brasil O cabo de dados US290 da Ugreen suporta a tecnologia de carregamento rápido, o que permite otimizar seu tempo de espera, sendo que apresenta excelente desempenho para garantir que seus dispositivos sejam sincronizados e carregados simultaneamente com velocidade de transferência de até 480Mbs. É uma ótima escolha como cabo sobressalente ou substituto, quer você esteja em casa, no escritório, no carro ou durante uma viagem. Marca: Ugreen Cor do produto: Preto Nome do modelo: Us290 Referência do modelo: 60148 Protocolo de interface: USB 2.0 Carregamento rápido: 5V / 2,4A Dados em alta velocidade: 480 Mbps Comprimento do cabo: 2 Metros Tipo de cabo: Trançado em nylon Dimensões: 1 x 13,4 x 19,4 cm Peso: 0,048 Itens Inclusos: 1x Cabo Us290 Garantia: 90 dias Venda condicionada a existência de produto em estoque.', 71.56, 71.56, NULL, 'Mobile & Gadgets > Accessories > Cables, Chargers & Converters', 'https://cf.shopee.com.br/file/br-11134275-7r98o-m9yrwqsvz2nt29', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1163157664%2F23598516185', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '23897457731', 'Par Bieleta Dianteira Ford Ecosport Fiesta Ka 2012 Á 2020', 'Este anúncio contém os seguintes produtos: 01 (uma) Bieleta de Suspensão Dianteiro Direito Novo e Original Nakata; 01 (uma) Bieleta de Suspensão Dianteiro Esquerda Novo e Original Nakata; Atenção: Produtos Novos e Originais, com 3 meses de garantia total, a pronta entrega. Código do produto: N92030. Aplicação dos Veículos: Marca: Ford; Veículo: Ecosport; Motor: 1.5 12v, 1.6 16v, 2.0 16v; Ano Inicial: 2013, 2014, 2015, 2016, 2017, 2018, 2019, 2020; Obs: Direção Hidráulica; Marca: Ford; Veículo: Fiesta; Motor: 1.0 12v, 1.5 16v, 1.6 16v; Ano Inicial: 2012, 2013, 2014, 2015, 2016, 2017, 2018, 2019, 2020; Marca: Ford; Veículo: Fiesta Sedan; Motor: 1.0 12v, 1.5 16v, 1.6 16v; Ano Inicial: 2012, 2013, 2014, 2015, 2016, 2017, 2018, 2019, 2020; Marca: Ford; Veículo: Ka; Motor: 1.0 12v, 1.5 12v, 1.5 16v; Ano Inicial: 2014, 2015, 2016, 2017, 2018, 2019, 2020; Marca: Ford; Veículo: Ka+; Motor: 1.0 12v, 1.5 16v; Ano Inicial: 2014, 2015, 2016, 2017, 2018, 2019, 2020; Dúvidas frequentes: - O Produto é novo? Sim, nós trabalhamos apenas com produtos novos e originais com garantia. - O Produto é original? Sim, nós só trabalhamos com distribuidores representados pelos fabricante, ou compramos diretamente dos fabricantes, gerando confiança da originalidade do produto. - Tem garantia? Sim, todos nossos produtos têm 3 Meses (90 dias) de garantia contra defeitos de fabricação, exceto os amortecedores que possuem 2 anos de garantia total. - O produto é igual ao da foto? Sim. Todas as fotos são fiéis ao que você irá receber, e para facilitar a sua compra ilustramos também o veículo em que se aplica o produto. - Em quanto tempo recebo minha compra? É muito simples, basta colocar seu CEP no calculador de frete do anuncio. - Envia ainda hoje? Sim, comprando até as 12h postamos no mesmo dia, compras depois das 12h a postagem é feita no dia seguinte. Os envios são realizado de segunda a sexta-feira. - Como faço para saber se o produto deste anúncio se aplica ao meu veículo? Você pode conferir se o produto se aplica no seu carro através da descrição do anúncio no item: Aplicação dos Veículos. Caso tenha alguma dúvida, entre em contato com nossa equipe e os profissionais qualificados irão te orientar em qualquer dúvida, estamos sempre a disposição. - Tem alguma dúvida sobre o produto ou sobre a compra? Deixe sua pergunta abaixo, que responderemos prontamente. O que é: A Bieleta é uma peça que faz parte do sistema de suspensão. Ela é posicionada na barra estabilizadora, transmitindo os movimentos compensatórios para o sistema de suspensão. Só para exemplificar, ela é uma haste metálica que liga a barra estabilizadora ao sistema de suspensão. Para garantir um melhor desempenho de sua função, ela é fixada nas extremidades do sistema através de pinos ou buchas. Dessa forma, a peça é uma das principais responsáveis pelo bom funcionamento de todo o sistema de suspensão. Porém, sua função vai bem além disso. Sobre o Fabricante: Há mais de 65 anos, a Nakata Automotiva, fabricante de autopeças para o mercado de reposição para veículos leves, pesados e motocicletas, recentemente adquirida pela Frasle, líder global em materiais de fricção e componentes para sistemas de freios, pertencente às Empresas Randon, vem construindo sua história de sucesso no Brasil, com liderança em componentes de suspensão e amplo portfólio em direção, transmissão, freios e moto peças. Com pioneirismo, qualidade e compromisso com o mercado, a Nakata Automotiva se tornou reconhecida no Aftermarket pela alta performance de seus produtos e elevado padrão de serviços. Oferecer e garantir soluções competitivas para a reparação de veículos com retorno adequado para os acionistas. Ser reconhecida como uma das melhores empresas do Aftermarket de autopeças por superar as expectativas dos clientes, colaboradores, parceiros de negócios e acionistas.', 132.26, 119.04, NULL, 'Spare Parts and Accessories for Vehicles > Spare Parts for Automobiles > Suspension and Steering', 'https://cf.shopee.com.br/file/br-11134207-7r98o-m22ptymj28v303', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F670503124%2F23897457731', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '23098469315', 'Cereal Infantil Mucilon 5 Cereais e Quinoa 180g', 'Cereal Infantil Mucilon 5 Cereais e Quinoa - Nutrição Completa para o Seu Bebê Mucilon 5 Cereais com Quinoa faz parte da linha Seleção da Natureza e é um cereal infantil zero adição de açúcares, composto por um mix exclusivo de arroz, milho, cevada, aveia e a quinoa, conhecida como “super grão”. É um complemento alimentar para bebês a partir do 6º mês e uma ótima opção para lanches intermediários. Com Probiótico B.lactis pode contribuir para a saúde do intestino e Rico em nutrientes que contribuem para a Imunidade² e Desenvolvimento Cerebral. Nossos grãos são cuidadosamente selecionados de fazendas ao redor do mundo e passam por diversos testes de qualidade. Garantindo Nutrição de qualidade do grão à cumbuquinha. Os cereais estão na base da pirâmide alimentar. Quando você oferece Mucilon para bebês a partir de 6 meses, está dando uma importante fonte de energia e nutrientes que contribuem para o seu crescimento e desenvolvimento. Contém açúcares dos próprios ingredientes. Este não é um alimento baixo ou reduzido em valor energético. Vitaminas A, C, D, E, B6, B9 (ácido fólico), ferro e zinco. O Ferro e o Zinco ajudam nos processos responsáveis pelo desenvolvimento adequado do cérebro. Sobre a Marca A Mucilon é uma marca confiável e renomada no Brasil, com mais de 60 anos de experiência em oferecer alimentos nutritivos e saborosos para bebês e crianças. Comprometida com a saúde e o crescimento dos pequenos, a Mucilon garante produtos de alta qualidade, pensados para atender as necessidades nutricionais durante as fases iniciais de alimentação. Benefícios -Probiótico B.lactis pode contribuir para a saúde do intestino -Rico em nutrientes que contribuem para a Imunidade e Desenvolvimento Cerebral -Proporciona uma alimentação equilibrada; - Rico em Vitamina A, C, D, E, B6, B9, ferro e zinco; -13 Vitaminas e Minerais. -Vitaminas A, C, D, E, B6, B9 (ácido fólico), ferro e zinco. O Ferro e o Zinco ajudam nos processos responsáveis pelo desenvolvimento adequado do cérebro Como Preparar o Cereal Infantil Mucilon 5 Cereais e Quinoa? Modo de Preparo 1. Lave e seque as mãos antes de preparar os alimentos. Use somente utensílios higienizados e alimente apenas a criança sentada e supervisionada. 2. Em uma tigela ou prato fundo, coloque 170 ml de leite líquido morno. 3. Misture, aos poucos. Principais Fontes de Vitaminas - Vitamina A: Essencial para o desenvolvimento da visão e para fortalecer o sistema imunológico. - Vitamina C: Auxilia na proteção da pele e no fortalecimento da imunidade. - Vitaminas do Complexo B: Importantes para o desenvolvimento cerebral e energético. - Ferro: Fundamental para o transporte de oxigênio e prevenção de anemia. Quais são os Benefícios Nutricionais do Cereal para o Bebê? - Vitaminas e Minerais: A combinação dos 5 cereais com quinoa fornece vitaminas e minerais importantes para o desenvolvimento saudável. - Proteínas e Fibras: A quinoa é uma excelente fonte de proteínas vegetais e fibras, essenciais para o crescimento e o bom funcionamento digestivo. - Energia: Os cereais oferecem carboidratos de fácil digestão, garantindo energia para o bebê. - Crescimento e Desenvolvimento: O cereal proporciona a nutrição necessária para o crescimento físico e cerebral saudável da criança. Perguntas Frequentes 1.O Cereal Infantil Mucilon 5 Cereais e Quinoa 180g pode ser consumido por bebês com menos de 6 meses? O produto é recomendado para bebês a partir de 6 meses, quando a introdução alimentar já foi iniciada. Consulte o pediatra para orientações específicas. 2.O Cereal Infantil Mucilon 5 Cereais e Quinoa contém açúcar? Não. O Cereal Infantil Mucilon é feito com ingredientes naturais, como os cereais e quinoa, sem adição de açúcar. O sabor vem dos próprios ingredientes. 3.O Cereal Infantil Mucilon 5 Cereais e Quinoa contém glúten? Não. Este cereal é livre de glúten, sendo ideal para bebês com intolerância ou sensibilidade ao glúten.', 19.63, 19.63, NULL, 'Mom & Baby > Milk Formula & Baby Food > Baby Porridge, Puree & Cereal', 'https://cf.shopee.com.br/file/sg-11134201-7rfey-m9kjwoa5ntau90', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1467864110%2F23098469315', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '22398966543', 'Fórmula Infantil de Primeira Infancia Ninho Fases 1 a 3 Anos 400g', 'Fórmula Infantil Ninho Fases 1+ (1 a 3 Anos) 400g – Nutrição Completa para o Crescimento Saudável ! A fase de 1 a 3 anos é um estágio importante de autodescoberta, evolução intelectual, emocional, social e requer uma nutrição adequada. Ninho Fases 1+ contém nutrientes importantes para essa fase de desenvolvimento. -Tamanho: 400g -Sabor: leite O produto não contém glúten. -Ninho Fases 1+ é uma fórmula infantil de seguimento para crianças de primeira infância desenvolvida especialmente para crianças de 1 a 3 anos, com prebióticos e nutrientes importantes para essa fase de desenvolvimento. Benefícios Contém Prebióticos: Auxiliam na saúde intestinal e digestão saudável; Rico em Ferro e Zinco: Essenciais para o desenvolvimento cognitivo e imunológico; Com Vitaminas A, C e D: Fortalecem as defesas naturais do organismo; Fonte de Cálcio: Contribui para ossos e dentes fortes; Com DHA: Um importante nutriente para o desenvolvimento do cérebro e da visão. Como preparar a Fórmula Infantil Ninho Fases 1+? Modo de Preparo 1 e 2. Lave bem as mãos, o copo de transição e higienize a superfície de preparo. 3. Ferva o copo de transição durante 5 minutos ou use esterilizador adequado. 4. Ferva a água potável durante 5 minutos. Aguarde aproximadamente 15 minutos, até que a água atinja a temperatura de 70°C, e despeje dentro do copo de transição. 5. Adicione o número de colheres-medida conforme instruções de uso, nivelando-as, e agite bem o copo de transição. 7. Aguarde o copo de transição esfriar e verifique a temperatura da fórmula no punho antes de oferecer à criança (aproximadamente 40°C). 8. Feche bem a lata após o uso. Por que escolher o Ninho Fases 1+ 400g? Fórmula específica para crianças de 1 a 3 anos: Adaptada às necessidades dessa fase da vida; Auxilia no crescimento e na imunidade: Rico em vitaminas e minerais essenciais; Sabor agradável: Aprovado pelos pequenos, facilitando a introdução na rotina alimentar; Praticidade: Fácil de preparar e armazenar, garantindo sempre a melhor nutrição para seu filho. Perguntas Frequentes 1.Crianças acima de 3 anos podem consumir esse produto? O Ninho Fases 1+ foi formulado especialmente para crianças de 1 a 3 anos. Para crianças maiores, recomenda-se o Ninho Fases 3+. 2.O produto pode ser misturado a outras bebidas ou alimentos? Sim, pode ser adicionado a vitaminas, mingaus e outras preparações, sempre respeitando a quantidade recomendada. 3.Como armazenar o Ninho Fases 1+ depois de aberto? Após abrir, mantenha a lata bem fechada, em local seco e fresco. Consuma o produto dentro do prazo indicado na embalagem. 4.O Ninho Fases 1+ substitui o leite materno? Não. O leite materno é essencial nos primeiros anos de vida e deve ser mantido sempre que possível. O Ninho Fases 1+ é um complemento para a alimentação infantil.', 43.04, 43.04, NULL, 'Mom & Baby > Milk Formula & Baby Food > Milk Formula', 'https://cf.shopee.com.br/file/sg-11134201-824jf-mfe9bhc823v16e', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1467864110%2F22398966543', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '23198326361', 'Kit Tresemmé Reconstrução e Força Shampoo 350ml + Condicionador 175ml', 'O Kit Tresemmé Reconstrução e Força foi especialmente desenvolvido para cabelos fracos e danificados. Sua composição promove a redução de 99% da quebra capilar, fortalecendo os fios e tornando-os mais saudáveis.', 47.02, 47.02, NULL, 'Beauty > Hair Care > Shampoo', 'https://cf.shopee.com.br/file/sg-11134201-7rd3m-m79mshu0xc6b59', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1467864110%2F23198326361', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '10862010571', 'Desodorante Antitranspirante Aerossol Dove Invisible Care 150ml', '• O Desodorante Antitranspirante Aerosol Dove Invisible Dry não deixa manchas brancas nas roupas, testado em 100 cores** de tecidos • Com tecnologia superior, o antitranspirante Dove garante proteção contra o suor e mau odor por até 72h, dando uma sensação de limpeza e frescor • Dove Invisible Dry é um desodorante antitranspirante sem álcool*** em sua fórmula, que cuida das suas axilas e das suas roupas • Este desodorante aerosol de rápida absorção e delicado para suas axilas é o número 1 em cuidado* para a sua pele • Contém 1/4 de creme hidratante e vitamina E, além de uma agradável fragrância de violeta e frésia branca • Dove não realiza testes em animais, sendo certificada como Cruelty-Free pela PETA. Este aerosol é vegano, não danifica a camada de ozônio e nossas latas são feitas de metal reciclável O Desodorante Antitranspirante Aerosol Dove Invisible Dry foi desenvolvido para não deixar manchas brancas em até 100 cores** de tecido. Feito com tecnologia superior que cuida e protege as axilas por 72 horas contra suor e mau odor, mantendo as axilas secas o dia todo. Este desodorante foi eleito o número 1 em cuidado* da pele das axilas pelas nossas consumidoras. Formulado com 1/4 de creme hidratante e vitamina E, ajuda a manter a hidratação da pele das axilas, e as deixa suaves e macias. O desodorante Dove sem álcool*** é gentil com sua pele e, além de proteger contra suor e mau odor, possui uma deliciosa fragrância floral de violeta e frésia branca, dando uma sensação de limpeza e frescor. Dove proporciona proteção eficaz e cuidado para a pele das axilas, para que você possa se libertar de qualquer desconforto e se sentir confiante o dia todo. Para uma melhor proteção contra marcas de suor e irritação da pele, siga estas dicas: após o banho, garanta que as axilas estão bem secas; para obter o máximo do seu Desodorante Antitranspirante Aerosol Dove Invisible Dry, agite a embalagem para ativar os ingredientes; segure-a voltada para cima a 15 cm das suas axilas e aplique um jato de dois segundos em cada uma. Dove é certificada Cruelty-Free pela PETA, sendo assim, não realizamos e nem realizaremos testes em animais em nenhum lugar do mundo. Além disso, nosso antitranspirante é vegano, fabricado com energia elétrica 100% renovável, nossa lata é feita de metal reciclável e o produto não danifica a camada de ozônio. *Antitranspirante Aerosol mais vendido do mercado de desodorantes no Brasil (Nielsen Retail Index INA+INFC, Novembro 2021 a Outubro 2022). **Comprovado contra manchas brancas em 100 cores. ***Não contém álcool etílico.', 27.97, 27.97, NULL, 'Beauty > Bath & Body Care > Body Deodorants', 'https://cf.shopee.com.br/file/sg-11134201-81zwn-mikub70ufdhj7f', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F546513063%2F10862010571', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '22498946469', 'Adoçante Líquido Zero-Cal Stevia 80ml', 'Adoçante Líquido Zero-Cal Stevia  Sem Calorias, Sabor Natural e Sem Açúcar De origem natural, a stévia é retirada de uma planta nativa do Brasil e do Paraguai, a Stevia Rebaudiana. Indicado para adoçar bebidas e alimentos, a fórmula de Zero-Cal Stévia possui sucralose em sua composição para proporcionar um gostinho mais doce e pode ser aquecida. Benefícios: - Zero Calorias: Perfeito para quem está em dieta ou quer evitar o excesso de calorias. - Sem Açúcar: Não eleva os níveis de glicose no sangue, tornando-se seguro para diabéticos. - 100% Natural: Feito com Stevia, um adoçante natural que não causa os efeitos adversos dos adoçantes artificiais. - Sabor Doce Natural: Adoça suas bebidas e receitas com um sabor agradável e sem amargor. - Versatilidade: Ideal para ser utilizado em chás, cafés, sucos, bolos, sobremesas e muito mais. Como usar? 5 gotas equivale a uma colher de chá de açúcar.', 27.12, 27.12, NULL, 'Food & Beverages > Cooking Essentials > Sweetener', 'https://cf.shopee.com.br/file/sg-11134201-824iv-mf4atx3dhq8e1f', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1467864110%2F22498946469', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '19899602158', 'Carabina de Pressão 5.5 Naja Nitro Tag + Capa + 2x.Chumbinho', 'Produto de uso exclusivo em práticas esportivas (airsoft, carabina de pressão,brinquedos de bolinha) Produzida pela TAG, a Espingarda Naja nitro possui um lindo design moderno com coronha ambidestra confeccionada inteiramente em polímero, um plástico de alta resistência e durabilidade. Uma característica super interessante é que a Molas Gás Ram de 60kg é carregada com gás nitrogênio, um gás inerte que preserva as vedações e metais do sistema interno da Carabina de Pressão, aumentando assim a vida útil da mesma em aproximadamente 400.000 tiros. Utiliza Chumbinho calibre 5.5mm como munição e o engatilhamento é feito através de basculamento do cano, onde se faz o movimento de "quebra" do mesmo. Pensando em evitar possíveis disparos acidentais a Carabina de Chumbinho Naja Nitro Tag possui trava de segurança no gatilho, que é feito manualmente. Possui uma velocidade com cerca de 274 Metros por Segundo ( 900 FPS ) o que a torna ainda mais potente. Conta também com Massa de mira da cor Vermelha e Alça de mira em fibra óptica da cor Verde, sendo que a Alça possui regulagem na horizontal e vertical. Você acabou de conhecer mais uma das Carabinas de Pressão da Naja, na qual sempre traz inovações e tecnologias diferenciadas para o mercado do tiro esportivo Brasileiro e internacional, e lembre-se, custo benefício e qualidade você só encontra aqui, na Ar15 SPORT! ESPECIFICAÇÕES TÉCNICAS: - Marca: Tag - Modelo: Naja Nitro Tag - Procedência: Brasileira - Calibre: 5.5mm (.22) - Ação: Mola Gás Ram 60kg (De Fábrica) - 26 Joules de Energia - Empunhadura: Ambidestra - Cor da coronha: Preta - Acabamento: Oxidado - Material da coronha: Polímero - Cano em Aço com alma raiada - Capacidade: 01 Chumbinho por vez - Modo de disparo: Monotiro - um por vez - Engatilhamento: Basculamento do cano - Velocidade média: 275 metros por segundo, 900 fps - Trava de segurança Manual - Soleira emborrachada - Massa de mira em fibra óptica vermelha - Alça de mira em fibra óptica com regulagem na horizontal e vertical - Trilho tipo ranhura 11mm - Comprimento total: 115 cm - Peso total: 2,753 Kg ITENS INCLUSOS: - 01 Carabina de Pressão Naja Nitro Calibre 5.5mm - 01 Mola Gás Ram 60kg ( instalada de fábrica ) - 01 Manual de Instrução - 02 Chumbinhos Ar15 Sport Diabolo 10,80gr 5.5mm 100un. (cada) - 01 Capa Ar15 Sport Simples Preta 120cm - 100 Alvos de Papel Ar15 Sport 14cm x 14cm Garantia de 6 meses dada pelo fabricante. Observação: A velocidade pode variar conforme munição utilizada.', 1226.61, 1226.61, NULL, 'Sports & Outdoors > Sports & Outdoor Recreation Equipments > Shooting & Survival Games', 'https://cf.shopee.com.br/file/sg-11134201-824iz-mpnzda68im19f9', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F404617501%2F19899602158', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '9551172887', 'Vedante do Cano Quickshot Carabinas SPA B3-3/ Fixxar Spring/ T-Rex e ML Classica', 'Produto de uso exclusivo em práticas esportivas. O uso do produto exige treinamento e equilíbrio emocional. Deverá ser guardado em lugar seguro e fora do alcance de terceiros. Os produtos aqui listados servem apenas para uso recreativo, ou seja ***NÃO*** letal. A Quickshot é uma marca nacional reconhecida por ser símbolo de qualidade e excelência. Esse produto em específico se trata do Vedante do cano para as Carabinas de Pressão modelos: - SPA B3-3 - FIXXAR SPRING - NAUTIKA T-REX - QGK ML CLÁSSICA ESPECIFICAÇÕES TÉCNICAS: - Marca: Quickshot - Referência: RET.SPA02 - Material: Polímero - Tonalidade de cor amarela - Diâmetro menor interno: 5,6mm - Diâmetro maior externo: 14,0mm - Peso total: 1 gramatura ITENS INCLUSOS: - 01 Vedante do Cano Quickshot Carabinas SPA B3-3 Fixxar Spring T-Rex e QGK INFORMAÇÃO: Os equipamentos, peças e acessórios aqui listados são de uso exclusivo em armas de pressão (gás comprimido ou mola), airsoft, paintball, esferas plásticas (BBS) e estão em conformidade com a legislação brasileira de USO PERMITIDO "É permitido o uso de armas de pressão por ação de gás comprimido ou por ação de mola, com calibre igual ou inferior a seis milímetros (6mm ou 6.0mm), e das que lançam esferas de plástico com tinta, como os lançadores de paintball." Conforme parágrafo único do Art. 11 do DECRETO Nº 11.615, DE 21 DE JULHO DE 2023. A venda desses itens é feita somente para maiores de 18 anos mediante a comprovação de maior idade. Atenção: O envio de Armas de pressão e Airsoft é realizado somente por transportadora. Caso tenham dúvidas entrar em contato.', 32.97, 32.97, NULL, 'Sports & Outdoors > Sports & Outdoor Recreation Equipments > Shooting & Survival Games', 'https://cf.shopee.com.br/file/sg-11134201-7rbk2-llkoyuu50ddb7c', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F404617501%2F9551172887', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '19204525918', 'Paralama Dianteiro Preto Yamaha Crypton 115 2009 2010 2011 2012 2013 2014 2015 2016', 'PARALAMA DIANTEIRO PRETO YAMAHA CRYPTON T115 ED E K Paralama dianteiro preto indicado para reposição na Yamaha Crypton T115. A peça auxilia na proteção da motocicleta contra respingos de água, lama, pedras e sujeiras projetadas pela roda dianteira durante o uso. Ideal para substituir paralamas quebrados, trincados, riscados ou danificados, contribuindo para a proteção e a recuperação do visual da motocicleta. Produto novo da marca Trilha, compatível com a aplicação informada. CONTEÚDO DA EMBALAGEM • 01 Paralama dianteiro preto COMPATIBILIDADE YAMAHA CRYPTON T115 ED • 2010 • 2011 • 2012 • 2013 • 2014 • 2015 • 2016 YAMAHA CRYPTON T115 K • 2010 • 2011 • 2012 • 2013 • 2014 • 2015 • 2016 ESPECIFICAÇÕES • Marca: Trilha • Número da peça: 49P-F1511-00-33P • Produto: Paralama dianteiro • Cor: Preto • Posição: Dianteira • Condição: Produto novo • Padrão: Compatível com o original • Garantia: 03 meses pelo fabricante PRINCIPAIS CARACTERÍSTICAS • Desenvolvido para reposição do paralama dianteiro • Auxilia na proteção contra água, lama e sujeira • Encaixe compatível com os modelos informados • Contribui para a recuperação estética da motocicleta • Indicado para manutenção preventiva ou corretiva • Produto pronto para instalação IMPORTANTE Antes de realizar a compra, compare o formato, os pontos de fixação, a cor e o código da peça com o paralama instalado na motocicleta. O código informado serve como referência de aplicação. O produto anunciado é da marca Trilha e não se trata de uma peça genuína Yamaha. A tonalidade do preto pode apresentar pequenas variações conforme a iluminação, a tela utilizada ou o lote de fabricação. Recomendamos que a instalação seja realizada por um profissional qualificado.', 209.98, 209.98, NULL, 'Spare Parts and Accessories for Vehicles > Spare Parts for Motorcycles > Others', 'https://cf.shopee.com.br/file/21554d5403f048d1a4d10f52f0139fbd', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F316897929%2F19204525918', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '22798711275', 'Teclado para Notebook Positivo Premium XS8320 Com Moldura', 'Teclado compatível com Positivo Premium XS8320 O teclado compatível com Positivo Premium XS8320 foi aprovado em rigorosos testes de qualidade e atende todas as exigências do seu equipamento, apresenta encaixe perfeito com o notebook, possui a mesma fixação da peça original. Além de 12 meses de garantia contra defeitos de fabricação. Atenção! Esse é um teclado bringIT, portanto não é um produto original da fabricante Positivo. Caso seja necessário, todo o suporte e garantia do produto serão oferecidos pela nossa equipe. Marca: bringIT Modelo: XS8320 Moldura: Com Moldura Idioma/Layout: ABNT2 Backlight: Sem Iluminação Pointing Stick: Sem Pointingstick Cor: Preto Referência: TC576-PO-0002 Atenção: Para que esse teclado seja compatível com seu notebook, deverá ter as mesmas especificações de encaixe, layout e moldura. Esse produto é compatível com os notebooks: MP-12R78PA-43022, XS3210, XS7210, XS7010-XS8320, 6-80-W9400-331-1P, XS7010, XS7005, XS4210, XS8320, XS4200, 11098645, XS7325, XS4205, XS4005, XS8210 Ficou na dúvida da compatibilidade ou precisa de mais informações? Deixe sua pergunta que nosso time técnico especializado está preparado para auxiliar! A bringIT é líder de mercado com o maior mix de produtos e peças para notebook: Baterias, telas, teclados e carregadores compatíveis com notebooks Dell, Lenovo, Acer, HP, Asus e muito mais!', 183.21, 126.0, NULL, 'Computers & Accessories > Desktop Computers > Others', 'https://cf.shopee.com.br/file/sg-11134201-8259c-mqszdjnx03ri26', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F801641954%2F22798711275', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '23798233741', 'Pneu 225/40R18 92W TL XL Aplus Aro 18', 'DESCRIÇÃO DO PRODUTO O Kit 2 Pneus 225/40R18 92W TL Aplus A610-5 XL foi desenvolvido para oferecer alta performance, segurança e conforto em veículos esportivos e sedãs de alta performance. Sua construção reforçada XL (Extra Load) garante maior capacidade de carga e resistência, enquanto o desenho da banda de rodagem proporciona excelente aderência em piso seco e molhado, com estabilidade em curvas e frenagens precisas. Ideal para quem busca dirigibilidade esportiva com conforto e durabilidade no uso diário e em viagens. ESPECIFICAÇÕES TÉCNICAS - Marca: Aplus - Modelo: A610-5 XL - Medida: 225/40R18 - Largura: 225 mm - Perfil: 40 - Aro: 18 polegadas - Índice de carga: 92 (até 630 kg por pneu) - Índice de velocidade: W (até 270 km/h) - Construção: Radial - Tipo: Sem câmara (TL – Tubeless) - Reforçado: XL (Extra Load) - Aplicação: Veículos de passeio / esportivos PRINCIPAIS BENEFÍCIOS - Excelente estabilidade em altas velocidades - Ótima aderência em piso seco e molhado - Frenagens mais seguras e precisas - Maior controle em curvas - Rodagem confortável e silenciosa - Maior durabilidade e resistência ao desgaste - Boa eficiência no consumo de combustível - Desenho esportivo moderno - Desempenho consistente em uso urbano e rodoviário COMPATIBILIDADE Compatível com veículos que utilizam a medida 225/40R18, como: Volkswagen Golf Volkswagen Jetta Audi A3 - Audi A4 (algumas versões) - BMW Série 1 - BMW Série 3 (algumas versões) - Mercedes-Benz Classe A - Honda Civic (versões esportivas/modificadas) - Toyota Corolla (algumas versões modificadas) - Peugeot 308 - Fiat Bravo - Volvo S40 (A compatibilidade pode variar conforme versão, ano e motorização. Consulte sempre o manual do veículo ou a medida do pneu atualmente instalado.) FAQ – PERGUNTAS FREQUENTES SÃO PNEUS NOVOS? Sim. Trabalhamos apenas com pneus novos. O VALOR É REFERENTE A QUANTOS PNEUS? Este anúncio refere-se a um kit com 2 pneus. VEM COM RODA? Não. O anúncio refere-se apenas aos pneus. PRECISA DE CÂMARA? Não. O modelo é TL (Tubeless), sem câmara. É INDICADO PARA USO ESPORTIVO? Sim. O perfil baixo e a estrutura reforçada proporcionam excelente desempenho em condução esportiva. QUAL A CAPACIDADE DE CARGA? O índice 92 suporta até 630 kg por pneu em condições ideais. QUAL A VELOCIDADE MÁXIMA? O índice W permite até 270 km/h em condições ideais. INFORMAÇÕES IMPORTANTES - Produto novo e original - Produto com nota fiscal - Garantia contra defeitos de fabricação - Imagens meramente ilustrativas - Não acompanha roda - Recomendamos instalação por profissional especializado - Recomendamos alinhamento e balanceamento após a instalação - Utilize sempre a calibragem recomendada pelo fabricante do veículo ANTES DE EFETUAR A COMPRA, TIRE SUAS DÚVIDAS NO CAMPO DE PERGUNTAS. A Confinit agradece sua preferência!', 661.22, 559.9, NULL, 'Spare Parts and Accessories for Vehicles > Tires and Wheels > Automobile Tires', 'https://cf.shopee.com.br/file/sg-11134201-7rd65-m6oedoo510yxd0', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1311743114%2F23798233741', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '18799196994', 'Balança Digital Portátil Com Gancho Multiuso Peixeira Cozinha Feira Peso Máximo 40kg Western', 'Olá, Bem vindo a Distribuidora Brester. Trabalhamos com uma grande variedade de ferramentas elétricas e manuais, descartáveis, eletroeletrônicos, artigos para casa, artigos de petshop e outros. Aqui você encontrará Produtos Originais, Nota Fiscal, Pronta Entrega e Envio Imediato! Informações do Produto: Balança Peixeira Digital 40kg Western A Balança Digital da Western é indispensável para o uso no dia-a-dia. É leve e resistente, ideal para pescas, camping, caça e até se necessário, pesar bagagens e outros. Esta balança simplifica a pesagem, proporciona rapidez, eficiência e resultados precisos. Características: > Graduação: 10kg; > Capacidade Máxima: 40kg; > Possui gancho para pesagem; > Alimentação: 2 pilhas AAA (não inclusas). - Marca: Western - Garantia: 90 dias contra defeitos de fabricação Vantagens de comprar na Brester: - Nota fiscal para Pessoa Física e Pessoa Jurídica; - Produto novo, com garantia de fábrica; - Produto a pronta entrega; - Envio em até 24hs em dias úteis após confirmação do pagamento. Obrigado por escolher a Brester Máquinas.', 40.34, 24.29, NULL, 'Home & Living > Kitchenware > Kitchen Weighing Scales', 'https://cf.shopee.com.br/file/sg-11134201-7rccq-lret44e85a1q04', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F442506479%2F18799196994', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '23697142558', 'Limpador Sintra Pro 1,5L Multiuso Estofados Carpetes Portas Automotivas Bancos Couro Plastico Painel Limpa Tudo Universal Vonixx Vonix Estofado Couros Banco Assento Carro Moto Multi-uso', 'Sintra Pro Vonixx Full Detail Multilimpador Limpeza de Interiores 1:60 (1,5 Litro) limpador multiuso flotador de pH balanceado, desenvolvido principalmente para a limpeza das superfícies internas do veículo. Sintra Pro Vonixx é um excelente multilimpador flotador de pH balanceado ultra concentrado, desenvolvido principalmente para a limpeza das superfícies internas do veículo. Sendo desenvolvido para limpar com excelência, assim ao aplicar o produto você terá uma excelente ação limpadora, que dispensa esforço para resultados de grande eficiência. Vonixx Sintra Pro é categorizado como um Multilimpador de Alta Performance (MAP), sendo esta uma nova tecnologia inovadora que reúne um blend perfeito entre solventes, surfactantes, alcalinizantes e agentes anti-oxidantes. Sintra Pro possui formulação balanceada e biodegradável, fornecendo ao produto alto poder de remoção de manchas de gordura e sujeiras diversas, possuindo um alto rendimento através de suas diluições. Sendo indicado para limpeza de painéis, laterais e cantos de portas, bancadas de couro, carpetes e estofados. Para partes internas do veículo, o uso seguro do produto é voltado para as seguintes superfícies: couro, plásticos, courvin, vinil e tecido. Vonixx Sintra Pro possui também ação fungicida e bactericida, ajudando na eliminação de maus odores no interior do veículo, tornando-o mais saudável e livre de impurezas. Sem que com isso deixe de ser ecologicamente correto, ou seja, sem gerar danos ao meio ambiente. Diluição: Limpeza de laterais de portas, plásticos e couro muito encardido: Diluir em até 1:5; Limpeza de carpetes, estofados e limpeza de teto: Diluir em até 1:10; Limpeza de Manutenção interna em painéis, laterais de portas e bancos de couro: Diluir em até 1:50; Uso em Tornadores: Diluir em até 1:10; Uso em Extratoras: Diluir em até 1:60. Características: Limpador Concentrado; Multilimpador de Alta Performance (MAP); Possui pH Alcalino; Alto poder bactericida; Alto poder de limpeza; Limpador com formulação balanceada e biodegradável; Limpa sem agredir; Uso indicado em: painéis, couro, carpetes, estofados; Embalagem de 1,5 Litro. Modo de Uso: - Limpeza de Painéis, Laterais e Cantos de Portas, e Bancos de Couro: Diluir o produto em água de acordo com o tipo de limpeza a ser feita; Aplicar o produto na superfície a ser limpa com auxílio de um borrifador; Faça a limpeza com auxílio de pincéis, escovas, luvas e afins até observar o desprendimento total da sujeira; Remova o excesso com um pano de microfibra úmido. - Limpeza de Carpetes, Estofados e Tecidos: Diluir o produto em água de acordo com o tipo de limpeza a ser feita; Aplicar o produto na superfície a ser limpa com auxílio de um borrifador; Faça a limpeza com auxílio de pincéis macios, escovas macias e afins até observar o desprendimento da sujeira; Utilize um aspirador específico ou extratora para remoção de água e aspire toda a sujeira; Aguarde a secagem por completo da superfície. * Sempre utilizar EPI''s ao manusear e trabalhar com o Sintra. * Caso utilize uma extratora ou tornador, realize a diluição conforme o recomendado.', 43.9, 43.9, NULL, 'Spare Parts and Accessories for Vehicles > Vehicular Care > Treatments', 'https://cf.shopee.com.br/file/br-11134207-7r98o-lo63f6scaeoc13', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F319801107%2F23697142558', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '19799549829', 'Persiana de PVC Horizontal 140x130cm - Preto', 'Persiana de PVC Preta 1,40x1,30cm: Seu Refúgio de Tranquilidade e Estilo Descubra o segredo para criar um ambiente perfeito onde a luz solar indesejada e o ruído do mundo exterior não têm lugar. Nossa persiana de PVC preta, com generosas dimensões de 1,40 x 1,30 cm, é a resposta para suas necessidades de descanso e concentração. Destaques que Encantam: Bloqueio de Luz e Ruído: Desfrute de um refúgio tranquilo com nossa persiana projetada para bloquear a luz solar e reduzir o ruído externo. Perfeita para criar um ambiente de descanso ou foco sem distrações. Design Elegante e Versátil: Seu design sofisticado se encaixa perfeitamente em qualquer estilo de decoração, adicionando um toque de classe ao seu espaço. Durabilidade Garantida: Fabricada com materiais de alta qualidade, incluindo PVC e metal, nossa persiana é construída para resistir ao teste do tempo, garantindo uma longa durabilidade. Manutenção Descomplicada: A limpeza é simples e fácil, podendo ser realizada com um pano úmido, aspirador de pó ou espanador. Esta persiana de PVC preta é a escolha ideal para quem busca conforto, elegância e funcionalidade em um único produto. Transforme seu ambiente e desfrute de um espaço que atende às suas necessidades. Não perca mais tempo. Adquira agora a nossa persiana de PVC preta e experimente o aconchego e a tranquilidade que ela oferece. Faça seu pedido hoje mesmo e eleve o nível de conforto e estilo em seu lar ou escritório. TAMANHO: 1,40 x 1,30 CM MATERIAL: PEÇAS E PARTES EM PVC E METAL CUIDADOS: LIMPAR COM PANO ÚMIDO, ASPIRADOR DE PÓ OU ESPANADOR. *FOTO MERAMENTE ILUSTRATIVA', 105.8, 105.8, NULL, 'Home & Living > Decoration > Curtains & Blinds', 'https://cf.shopee.com.br/file/sg-11134201-7rend-m1wtbpxya2raf9', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F427153374%2F19799549829', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '19499890591', 'Torquês Tramontina 13" Armador Pintura Eletrostática De Proteção Anticorrosão P/ Construção Civil', 'Torquês Armador 13" C/ Pintura Eletrostática Tramontina O Torquês Armador 12 Polegadas Tramontina MASTER é a ferramenta perfeita para quem busca durabilidade, precisão e desempenho profissional em obras, construções e trabalhos pesados. Fabricado em aço carbono especial forjado com têmpera diferenciada, garante cortes precisos, maior vida útil e resistência superior. Sua articulação suave proporciona conforto durante o uso, enquanto o acabamento em pintura eletrostática azul oferece proteção contra oxidação. Caracteristicas: > Corpo forjado em aço vanádio / aço carbono especial; > Cabeça polida e robusta para cortes precisos; > Têmpera especial no gume de corte e mandíbulas; > Acabamento em pintura eletrostática azul; > Articulação suave que facilita o uso; > Cabos longos que reduzem o esforço do operador; > Ferramenta com alta durabilidade e resistência. Especiações: > Linha: MASTER; > Modelo: Torquês Armador 12" (300 mm); > Material: Aço carbono especial forjado; > Acabamento: Pintura eletrostática azul; > Comprimento: 12 polegadas; > Uso: Profissional / Construção Civil; > Indicação: Armar ferragens, cortar arames e uso em obras. - Marca: Tramontina - Garantia: 12 meses contra defeitos de fabricação Vantagens de comprar na Brester: - Produto a pronta entrega. - Produto novo, com garantia de fábrica. - Nota fiscal para Pessoa Física e Pessoa Jurídica.', 90.74, 71.69, NULL, 'Home & Living > Tools & Home Improvement > Tools', 'https://cf.shopee.com.br/file/sg-11134201-824i0-mfaa9el58v0rd9', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F442506479%2F19499890591', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '19397736410', 'Mini Arco De Serra Manual Profissional Para Madeira Metal Aço Inox 10 Polegadas', 'Mini Arco De Serra 10" Hutz Com o Mini Arco de Serra 10" Hutz, você terá em mãos uma ferramenta que simplifica seus cortes, seja em madeira, plástico ou metal leve. Feito com materiais de alta qualidade, oferece durabilidade e resistência para acompanhar suas demandas diárias. É a escolha ideal para projetos de marcenaria e trabalhos DIY. Características: > Material: aço carbono, liga de alumínio e plástico; - Marca: Hutz - Garantia: 90 dias contra defeitos de fabricação Vantagens de comprar na Brester: - Produto a pronta entrega. - Produto novo, com garantia de fábrica. - Nota fiscal para Pessoa Física e Pessoa Jurídica.', 38.87, 30.53, NULL, 'Home & Living > Tools & Home Improvement > Tools', 'https://cf.shopee.com.br/file/sg-11134201-7rdxs-lycci9wc5gte0a', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F442506479%2F19397736410', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
