INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '18099297995', 'Curvador de cílios essence All the way up', '✨ CURVADOR DE CÍLIOS ALL THE WAY UP Cílios extraordinariamente curvados e separados em apenas alguns segundos. O curvador de cílios All The Way Up da essence é o acessório ideal para potencializar o olhar antes da aplicação da máscara. Seu design anatômico proporciona curvatura uniforme desde a raiz, ajudando a criar efeito de cílios mais abertos e definidos. Prático e fácil de usar, garante resultado rápido e profissional. Acompanha borrachinha extra para reposição, oferecendo mais durabilidade e segurança no uso. 👁️ Curvador de Cílios Realça o olhar com efeito imediato. ✨ Cílios Curvados e Separados Mais definição e aparência alongada. ⏱️ Resultado em Segundos Praticidade no dia a dia. 🔄 Borrachinha Extra Inclusa Mais durabilidade e reposição fácil. 🌿 Sobre a Marca A essence é a marca nº 1 na Europa em unidades de cosméticos*, oferecendo qualidade com preço acessível. 100% livre de crueldade animal desde o início, com forte compromisso com produtos veganos. Acreditamos em uma beleza divertida, acessível e responsável. Para a essence, cada pessoa é única — o perfeito é ser você. *Marca de cosméticos em unidades.', 26.9, 26.9, NULL, 'Beauty > Beauty Tools > Makeup Accessories', 'https://cf.shopee.com.br/file/sg-11134201-7rd51-lwfywylvmdqf04', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F816819540%2F18099297995', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '19099297814', 'Boneca Masha E O Urso 18 cm com Acessórios para Crianças a Partir de 3 Anos Cotiplas - 2569', 'AVISO DE SEGURANÇA: - Por conter partes pequenas que podem ser engolidas é preciso supervisão de um adulto durante o uso pela criança. Características: - Marca: Cotiplas - Modelo: 2569 *Imagens meramente Ilustrativas Especificações técnicas: - Idade Mínima Recomendada: 3 anos - Altura (cm): 18 cm - Franquia: Masha E O Urso - Acessórios: Sim - Luzes: Não - Som: Não Conteúdo da Embalagem: - 1x Boneca Masha com moranguinho com velcro, tábua e faquinha sem corte', 58.0, 52.2, NULL, 'Mom & Baby > Toys > Others', 'https://cf.shopee.com.br/file/sg-11134201-81ztn-milp5x5rztokdb', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F356143297%2F19099297814', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
