INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '22292977768', 'Livro Uma pergunta por dia: 365 perguntas - 5 anos - 1.825 respostas, por Potter Style - Intrínseca', 'Livro Uma pergunta por dia: 365 perguntas - 5 anos - 1.825 respostas, por Potter Style - Intrínseca Todos os dias criamos uma imensa quantidade de registros em celulares, redes sociais e aplicativos. No entanto, quase nunca temos o hábito de retornar a eles. Às vezes podem parecer só besteiras, mas quantos desses relatos não mostrariam nosso crescimento e nossas mudanças em todos esses anos? Uma pergunta por dia convida a registrar suas respostas a uma variedade de questões, das mais simples às mais complicadas, como "Para onde você quer fazer sua próxima viagem?" ou "Escreva a primeira linha da sua autobiografia". Em cada página há espaço para cinco respostas, uma por ano, ao longo de cinco anos. Com o passar do tempo, quando voltar a um dia já anotado, o dono do diário encontrará seus pensamentos anteriores, num exercício divertido e construtivo de recordar e refletir. Sobre o Autor: Potter Style é uma marca do grupo editorial Crown Publishing dedicada a livros de design, arte, moda, humor e estilo de vida. Uma pergunta por dia é um de seus maiores sucessos. Tradução: Lourdes Sette Páginas: 368 Gênero: Crônicas, Humor e Entretenimento Formato: 10 x 15,3 x 2,7 cm Peso: 320,0 gramas Tipo de capa: Livro capa dura Data de Lançamento: 18/11/2015', 79.9, 63.92, NULL, 'Books & Magazines > Books > Others', 'https://cf.shopee.com.br/file/br-11134207-7r98o-lu87gvfj4yacc8', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1208017249%2F22292977768', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
