INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '20361833931', 'Reservatório Água Radiador Ecosport Fiesta 2 Saídas Flório', 'NÃO VENDEMOS PARA PESSOA JURÍDICA CONSUMIDOR. PRODUTO NOVO. Aplicação Aplicação Ford Ecosport 2003 até 2021 Fiesta 2002 até 2014 (Exceto Street) Conteúdo Da Embalagem 1 Reservatório Observação com 2 Saídas Tipo de Veículo para Carros Marca Há mais de 30 anos no mercado automotivo, a Flório é referência no segmento de reservatório, tampas, mangueiras e interruptores. Tradição em qualidade e preços justos são dois pilares primordiais para a Flório. Além disso, a empresa é reconhecida no Brasil e no exteriror, por isso, fornece autopeças para as principais montadoras de veículos. Importante Recomendamos que os produtos sejam instalados por profissionais especializados e não nos responsabilizamos pelo mau uso ou instalação indevida, causando a perda da garantia. Todas as informações divulgadas são de responsabilidade do fabricante/fornecedor. Verifique com os fabricantes do produto e de seus componentes eventuais limitações à utilização de todos os recursos e funcionalidades. Tempo de garantia : 3 meses Valor referente a unidade Imagem meramente ilustrativa Prazo de troca e devolução: 7 dias a partir do recebimento do produto - Lei nº 8.07 Código do Fabricante 12462 Código da Montadora 2S65.8K218.BA', 62.56, 62.56, NULL, 'Spare Parts and Accessories for Vehicles > Spare Parts for Automobiles > Engine', 'https://cf.shopee.com.br/file/sg-11134201-7ra0y-mbcs67rcsg9d3c', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F817551928%2F20361833931', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '22098545487', 'Océane Edition Foundation Stick Semi-Matte Beige - Base em Bastão 8g', 'Océane Edition Foundation Stick Semi-Matte Beige - Base em Bastão 8g Para todos os tipos de pele. Prático e descomplicado, a base em bastão da Océane confere máxima praticidade para alcançar uma pele com tom uniforme. Enriquecido com vitamina E, ácido hialurônico, óleo de jojoba e rícino. Sua textura cremosa e acabamento semi-matte, facilita a aplicação, disfarça imperfeições e linhas finas. Com formato triangular possibilita uma aplicação precisa. Conselho de Aplicação Aplique bastão diretamente no rosto e espalhe o produto com o pincel, fazendo movimentos circulares; ou com a esponja, com batidinhas. Se necessário construa camadas repetindo este processo até chegar na cobertura desejada.', 134.7, 75.9, NULL, 'Beauty > Makeup > Lips', 'https://cf.shopee.com.br/file/sg-11134201-7rav5-ma47g6ncprr8b7', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F322434863%2F22098545487', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '22393480296', 'Kit Cadiveu Profissional Essentials Glamour Shampoo Condicionador Máscara e Fluído (4 produtos)', 'Kit Cadiveu Profissional Essentials Glamour Shampoo Condicionador Máscara e Fluído (4 produtos) Esse Kit Contém Cadiveu Professional Essentials Glamour - Shampoo 250ml: limpa os fios e garante um cabelo três vezes mais forte, hidratado e saudável. Apresenta uma nova fórmula 100% vegana e que garante uma limpeza equilibrada. Ideal para a sua rotina de cuidados com as madeixas. Cadiveu Professional Essentials Glamour - Condicionador 250ml: promove força e hidratação instantânea dos fios. Traz uma fórmula vegana ainda mais poderosa. Sua composição é enriquecida com Biotina e Extrato de Quinoa, que ajudam a deixar suas madeixas saudáveis, macias e iluminadas. Cadiveu Professional Essentials Glamour - Máscara 200ml: é a solução perfeita para quem busca cabelos mais fortes, hidratados e brilhantes. Com sua nova fórmula infundida com Biotina, esta máscara é capaz de converter os fios enfraquecidos em cabelos 3x mais fortes e saudáveis, ajudando a recuperar os cabelos quebradiços e transformá-los em fios super macios e brilhantes. Cadiveu Professional Essentials Glamour Fluído – Leave-in de Tratamento 200ml: com fórmula reforçada com Biotina fortalece a estrutura do fio contra quebra e facilita a secagem do cabelo. Com proteção térmica até 180ºC para um penteado perfeito. Textura super. Leve não pesa nos fios. Reduz em até 70% a quebra dos cabelos. Nova fórmula mais poderosa e com formulação 100% vegana! Conselho de Aplicação Shampoo: aplicar sobre os cabelos úmidos, massagear e enxaguar. Se necessário, repita a operação. Condicionador: com os fios já limpos e úmidos aplicar o condicionador ao longo do comprimento às pontas. Massagear e enxaguar. Máscara: após lavar os cabelos com o shampoo da mesma linha, aplique uma quantidade razoável de produto por todo o comprimento e pontas dos fios. Massageie delicadamente, deixe agir por 3 minutos e enxágue. Leave-in: espalhar sobre os cabelos úmidos ou secos e pentear. Ideal para ser utilizado antes do secador ou prancha.', 371.8, 371.8, NULL, 'Beauty > Hair Care > Hair Treatment', 'https://cf.shopee.com.br/file/sg-11134201-7rdxc-m1iipusn93r114', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F322434863%2F22393480296', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
