INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '20799306365', 'Carregador de tomada USB-C Branco EC 10 power Intelbras', 'Carregador de tomada USB-C Branco EC 10 power - Intelbras O EC 10 Power 20W é um carregador USB-C ultrarrápido, com uma porta USB-C, oferecendo flexibilidade para atender os mais diferentes tipos de dispositivos, dos mais novos aos mais antigos. Com saída USB-C Power Delivery (USB-C PD) com potência máxima de 20 W, ele carrega seu aparelho até três vezes mais rápido* que um carregador convencional. *a potência e corrente podem variar de acordo com a fonte de alimentação e dispositivo conectados. Detalhes: - Entrada: 100 ~ 240 Vca 50/60 Hz 0,6 A máximo (bivolt automático) - Saída: USB Type-C Power Delivery 5 V 3,0 A, 9 V 2,22 A, 12 V 1,67 A (máximo), USB Type-A Quick 5 V 3,0 A, 9 V 2,0 A, 12 V 1,5 A (máximo), total simultâneo: 5 V 3,0 A (máximo) - Possui proteção contra surtos de tensão e sobrecarga - Carrega qualquer dispositivo com conexão USB - Carregamento seguro que não vicia a bateria do produto conectado', 89.88, 89.88, NULL, 'Home Appliances > Electrical Circuitry & Parts > Electric Sockets & Extension Cords', 'https://cf.shopee.com.br/file/sg-11134201-7rdxj-ly2m0r0q1cs72f', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F400736454%2F20799306365', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
