INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '40876970563', 'Mochila Esportiva Flamengo Bagaggio 23L - Preto e Vermelho', 'A Mochila Esportiva Flamengo é ideal para os torcedores apaixonados pelo clube e que buscam praticidade no dia a dia. Com um design moderno e funcional, ela é perfeita para transportar materiais esportivos e itens essenciais com estilo, exibindo o escudo do Flamengo com orgulho. A mochila traz o escudo oficial do Flamengo bordado em destaque, reforçando o orgulho pelo time em qualquer ocasião. Possui compartimento frontal em tela é perfeito para carregar uma bola de futebol, oferecendo praticidade para quem pratica esportes, bolsos laterais que são ideais para transportar garrafas de água ou outros itens de uso rápido durante a prática esportiva, o compartimento principal oferece amplo espaço para transportar uniformes, chuteiras, materiais escolares ou itens do dia a dia e alças acolchoadas e ajustáveis poporcionam mais conforto durante o uso prolongado, sendo ajustáveis para maior praticidade e ergonomia. Garanta já a sua!', 259.9, 229.9, NULL, 'Travel & Luggage > Others', 'https://cf.shopee.com.br/file/sg-11134201-81ztw-miesg55z22h383', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1178125772%2F40876970563', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '23092998371', 'Trilho Spot LED para trilho eletrificado + Trilho + Conector Tubinho Preto e Branco 15W 360° Bivolt | Acompanha Trilho', '📢 Observações: - Este produto acompanha manual de instalação em PDF. - Recomendamos verificar o vídeo fornecido para instruções de instalação. - Acompanha Trilho: - Escolha entre 2 metro ou 3 metros (conforme a sua seleção). - Acompanha Conector de Trilho: - Inclui conector para trilhos de 2 metros ou mais. Características: 💡 POTÊNCIA: 15W 🔌 TENSÃO: 100-240V 🌈 LÚMENS: 1200LM 📐 ÂNGULO DE ABERTURA: 24° 💡 FATOR DE POTÊNCIA: >0,5 🌟 COR DA LUZ: Branco Frio (6,500K), Branco Neutro (4200K) ou Branco Quente (3500K) ⏳ VIDA ÚTIL: 1 ANO 🎨 IRC (ÍNDICE DE REPRODUÇÃO DE COR): >80 💧 IP (ÍNDICE DE PROTEÇÃO): IP20 🤝 GARANTIA: 1 ano 📏 TAMANHO: Ø50*80mm 🎨 COR DO MATERIAL: PRETO ou BRANCO 📢 OBS: Certifique-se de verificar as especificações detalhadas antes da compra para garantir que atenda às suas necessidades específicas. As informações fornecidas são baseadas no modelo mencionado.', 449.99, 109.9, NULL, 'Home & Living > Lighting', 'https://cf.shopee.com.br/file/br-11134207-81z1k-mgxo9j264y6f50', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F979730489%2F23092998371', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '23298802304', 'Relógio Casio MW-240-7BVDF', 'Relógio Casio MW-240-7BVDF Especificações Técnicas Gênero: Masculino Máquina movida a bateria / quartz Mecanismo Analógico Caixa do relógio em resina Pulseira de resina Fivela de plástico Vidro de Cristal Mineral Tampa posterior parafusada Resistência à água 5ATM (50M) Medidas do Relógio 48mm × 43,6mm Duração aproximada da pilha: 3 anos em SR626SW Peso: 35g Relógio 100% Original, acompanha caixa, manual, certificado de garantia Casio e NF. Somos revendedores oficial e autorizado da CASIO (fabricado e comercializado pela CASIO BRASIL COMÉRCIO PRODUTOS ELETRONICOS LTDA), todos os relógios comercializados pela nossa empresa possuem GARANTIA NACIONAL do FABRICANTE e caso o produto que adquiriu apresente algum defeito durante o período da garantia, basta encaminhá-lo diretamente à assistência técnica mais próxima de sua região, sempre acompanhado do CERTIFICADO de GARANTIA e NOTA FISCAL.', 168.9, 168.9, NULL, 'Watches > Men Watches', 'https://cf.shopee.com.br/file/sg-11134201-7rdx1-mdal3x8svjv289', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F589442593%2F23298802304', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '22598822821', '20M Luz Solar Fio de Fada Flor RGB 5M Led Com Placa Solar para ambientes externos', '🌸 Luz Solar Fio de Fada Flor RGB 5M LED com Placa Solar | Decoração Jardim e Externo Crie uma atmosfera mágica e encantadora em seu jardim, varanda ou festa com a Luz Solar Fio de Fada Flor RGB 5M. Com design de flores delicadas e iluminação colorida, é perfeita para decoração externa ou interna, funcionando de forma automática e sustentável com energia solar. 🌟 Destaques do Produto ☀️ Energia Solar Automática: carrega durante o dia e acende automaticamente à noite. 🌈 Efeito Encantador RGB: cada fio possui cor fixa, mas com vários modos de iluminação para personalizar o ambiente. 💧 À Prova d’Água (IP65): ideal para uso externo em jardins, festas, casamentos e varandas. 🌸 Design Flor de Pêssego: 50 mini flores iluminadas que criam um efeito delicado e romântico. 🔋 Bateria Recarregável Embutida: reutilizável, ecológica e sem necessidade de troca constante. 🎁 Perfeito para Presentear: decoração charmosa que combina com qualquer ocasião especial. 📏 Especificações Técnicas Modelo: Luz Solar Fio de Fada Flor Comprimento: 5 metros (aprox.) LEDs: 50 unidades Alimentação: Energia solar (placa solar inclusa) Modos de Iluminação: múltiplos efeitos piscantes e fixos Cor: fixa por fio (escolha nas opções do anúncio) Uso: Interno e Externo (resistente à água) Bateria: Recarregável embutida Instalação: fácil e sem fios 📦 Itens Inclusos 1 a 4 fios de luz solar (conforme opção escolhida) 1 a 4x Placa Solar com estaca para fixação 🎯 Indicações de Uso Decoração de jardim, quintal e varanda Casamentos, festas e eventos ao ar livre Natal, Halloween e datas comemorativas Gazebos, barracas e áreas de lazer Presentes criativos e decorativos ✨ Leve a magia da natureza para seus espaços com esta Luz Solar Flor de Fada! 🌙 Iluminação encantadora e sustentável para todas as ocasiões.', 80.0, 57.9, NULL, 'Home & Living > Lighting', 'https://cf.shopee.com.br/file/br-11134207-7r98o-mdktc4ogzky9b3', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F979730489%2F22598822821', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
