INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '20398864774', 'Blusa Básica Feminina Decote Quadrado Malha Canelada', 'Blusa confeccionada em malha canelada. O modelo possui decote quadrado profundo e mangas curtas. Uma peça versátil e ideal para o dia a dia, do trabalho aos momentos de lazer com os amigos. A malha canelada tem o diferencial por ser texturizada. É Um tecido maleável, flexível e com excelente elasticidade e por isso se adapta com facilidade aos movimentos do corpo. Invista com calça mom jeans e sandália de tiras finas, para arrematar com modernidade. Decote: Quadrado Mangas: Curtas', 99.9, 89.91, NULL, 'Baby & Kids Fashion > Girl Clothes > Tops', 'https://cf.shopee.com.br/file/sg-11134201-7rbk0-lkpjfja9b9351e', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F939838662%2F20398864774', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
