INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '14481375181', 'Kit Borrachas Kombi Carat 1998 a 2013 Portas e Vidros Completo', 'Kit Borrachas Completo Portas e Vidros – Kombi Carat 1998 a 2013 O Kit de Borrachas Completo para Volkswagen Kombi Carat é fabricado em material de alta qualidade e resistência, garantindo vedação eficiente, encaixe perfeito e longa durabilidade. Ideal para restauração ou substituição das borrachas ressecadas ou danificadas, o kit proporciona proteção contra água, poeira e ruídos, mantendo o padrão original do veículo. Produto novo, desenvolvido no padrão tipo original, pronto para instalação. Compatibilidade: Volkswagen Kombi Carat – 1998 a 2013 (Aplicação nas portas e vidros do veículo, conforme conjunto do kit.) Características: Kit completo de vedação Ideal para restauração de Kombi Excelente vedação contra água e poeira Reduz ruídos externos Material resistente e durável Encaixe perfeito Padrão tipo original Produto novo Conteúdo da Embalagem: Borrachas das portas do veículo Borrachas dos vidros (Kit completo conforme descrição do anúncio.) Tempo de Garantia: GARANTIA 3 MESES Observações: PARA EVITAR PROBLEMAS NA INSTALAÇÃO DO PRODUTO ELA DEVE SER FEITA POR UM PROFISSIONAL', 790.19, 711.18, NULL, 'Spare Parts and Accessories for Vehicles > Spare Parts for Automobiles > Others', 'https://cf.shopee.com.br/file/5377ff8b4cdf2fd0cb53eecddd88127d', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F691145803%2F14481375181', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
