INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '49302495917', 'BENGALA CILINDRO INTERNO BROS 150 06-14 / BROS 125 13-15 / BROS 160 / XRE 190 SMARTFOX CADA', 'BENGALA CILINDRO INTERNO BROS 150 06-14 / BROS 125 13-15 / BROS 160 / XRE 190 SMARTFOX CADA Descrição BENGALA CILINDRO INTERNO BROS 150 06-14 / BROS 125 13-15 / BROS 160 / XRE 190 SMARTFOX CADA Melhore a performance da sua motocicleta com o Tubo Interno Bengala Smartfox. Fabricado com materiais de qualidade e precisão, este tubo interno é projetado para oferecer durabilidade e desempenho excepcionais. O Tubo Interno Bengala Smartfox é a escolha ideal para quem busca confiabilidade e desempenho superiores. Garanta uma condução suave e estável em todas as suas aventuras na estrada ou fora dela. Não deixe a qualidade comprometer sua viagem - escolha Smartfox. O que é o tubo interno? Mais conhecido como bengala, o tubo interno é uma peça que faz parte do sistema de amortecimento dianteiro de motocicletas, que tem como objetivo frear o movimento de oscilação da mola, mantendo o pneu em contato com o solo. Aplicação: - BROS 150 06-14 / BROS 125 13-15 / BROS 160 / XRE 190 Contém: - 01 Tubo de Bengala Garantia 3 meses defeito fabricação Foto Ilustrativa BENGALA CILINDRO INTERNO BROS 150 06-14 / BROS 125 13-15 / BROS 160 / XRE 190 SMARTFOX CADA Encontre a Bengala Cilindro Interno BROS 150 06-14 / BROS 125 13-15 / BROS 160 / XRE 190 na Paulinho Motos. Qualidade e preço justo em peças para sua moto. Confira!', 101.0, 101.0, NULL, 'Spare Parts and Accessories for Vehicles > Spare Parts for Motorcycles > Chassis', 'https://cf.shopee.com.br/file/sg-11134201-8227r-mhrs0fzify0x0a', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F784758508%2F49302495917', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '22897473549', 'Guarda Roupa Casal 3 Portas com Espelho 4 Gavetas Costa Rica Cinamomo/Off-White Cinamomo/Off-White', 'Transforme seu quarto em um oásis de organização e estilo com o Guarda-Roupa Casal Costa Rica. Esta peça essencial combina um design moderno com máxima funcionalidade, sendo a solução de armazenamento definitiva para quem busca elegância e um ambiente bem planejado. • Com 185,5 cm de largura, este armário oferece um espaço interno generoso, projetado para acomodar perfeitamente as roupas do casal. • O grande destaque é a porta central com espelho, um detalhe que não só confere praticidade ao dia a dia, mas também ajuda a criar uma sensação de amplitude e luminosidade no quarto. • A organização interna é o ponto forte deste móvel. Ele conta com quatro gavetas espaçosas equipadas com corrediças telescópicas, garantindo um deslize suave, silencioso e acesso total aos seus pertences. Além disso, possui sete prateleiras bem distribuídas e cabideiros resistentes em alumínio, permitindo que tudo, de roupas dobradas a vestidos e casacos, tenha seu lugar definido. Fabricado com uma estrutura robusta em MDF/MDP e acabamento de alta qualidade em Pintura UV, o Guarda-Roupa Costa Rica assegura excelente durabilidade e resistência para o uso diário. É a escolha inteligente para quem não abre mão de funcionalidade e bom gosto na decoração. Importante: o produto não inclui itens decorativos ou acessórios mostrados nas imagens. Confira o título e a ficha técnica completa para garantir que sua compra seja exatamente o que você espera! Garanta o encaixe perfeito! Planeje seu ambiente com cuidado comparando as medidas do produto com o espaço disponível e reserve uma folga de até 2 cm para posicioná-lo com conforto. Estilo: Moderno Modular: Não Peso (kg): 112 Garantia: 03 Meses Altura (cm): 208 Acabamento: Pintura UV Largura (cm): 185.5 Possui Pés: Não Possui Nichos: Não Possui Portas: Sim Tipo de Porta: Correr Possui Gavetas: Sim Tipo de Gaveta: Interna Possui Espelhos: Sim Profundidade (cm): 47 Possui Calceiros: 1 Material da Porta: MDP Origem do Produto: Nacional Possui Cabideiros: Sim Ambiente Principal: Quarto Material da Gaveta: MDF Material Principal: MDF/MDP Necessita Montagem: Sim Possui Penteadeira: Não Possui Prateleiras: Sim Acabamento da Porta: Pintura Texturizada UV Nicho com Cabideiro: Não Espessura do Espelho: 3 Espessura do Fundo (mm): 3 Material da Prateleira: MDP Peso Máximo por Gaveta: 5 Possui Espelho Interno: Não Quantidade de Espelhos: 03 Espelhos com Tamanhos Iguais Espessura das Portas (mm): 15 Acabamento da Prateleira: Pintura Texturizada UV Complexidade da Montagem: Alta: deve ser montado por um montador especializado Espessura da Estrutura (mm): 12 Peso Máximo por Prateleira: 8 Tipo de Corrediça da Gaveta: Metálica Telescópica Espessura das Prateleiras (mm): 12 Material do Puxador da Porta: MDF Espessura do Fundo das Gavetas (mm): 3 Tipo de Dobradiça/Corrediça da Porta: Metálica Telescópica Marca: Sallêto Móveis Cor: Cinamomo/Off-White Itens Inclusos: 1 Guarda Roupa, kit ferragens e manual de montagem. Linha ou Coleção: Costa Rica Cor do Puxador: Marrom Quantidade de Prateleiras: 03 Prateleiras Quantidade de Portas: 3 Portas Quantidade de Portas com Espelhos: 1 Porta com Espelho', 1317.41, 1140.71, NULL, 'Home & Living > Furniture > Wardrobes', 'https://cf.shopee.com.br/file/sg-11134201-82580-mqwyb8jugg7gd4', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F855489892%2F22897473549', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
