INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '48206766771', 'Ração Premier 7,5kg Shih Tzu Frango Cães Pequenos', '🐾 Ração PremieR Shih Tzu Adulto 7,5kg – Nutrição Super Premium Garanta o melhor para o seu melhor amigo! A Ração PremieR Raças Específicas Shih Tzu é o alimento ideal para quem busca saúde, beleza e longevidade. Desenvolvida por especialistas, ela atende exatamente o que o seu Shih Tzu precisa. ✨ Por que escolher a PremieR Raças Específicas? • Grão Especial: Formato exclusivo para cães braquicefálicos, facilitando a preensão e mastigação. • Pelagem de Luxo: Rica em Ômegas 3 e 6, Biotina e Zinco. Deixa os pelos macios, sedosos e brilhantes. • Saúde Oral: Contém Hexametafosfato de Sódio, que reduz em até 80% a formação do tártaro. • Intestino Equilibrado: Combinação de fibras e prebióticos que garantem fezes firmes e com odor reduzido. • Cuidado Articular: Com Condroitina e Glicosamina para manter as articulações sempre fortes. 📋 Ficha Técnica: • Marca: PremieR Pet • Linha: Raças Específicas • Pet: Cães Adultos (acima de 1 ano) • Raça: Shih Tzu • Sabor: Frango • Peso: 7,5kg • Categoria: Super Premium', 263.64, 194.88, NULL, 'Pets > Pet Food > Dog Treats', 'https://cf.shopee.com.br/file/br-11134207-820lt-mlgcsiqe3evb26', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F290073877%2F48206766771', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
