INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '53658748301', 'Comedouro Gato Filhote Ergonômico 80ml Mypetone Azul', 'Comedouro Ergonômico Filhote 80mL Mypetone – Azul O Comedouro Ergonômico Filhote 80mL Mypetone foi desenvolvido especialmente para gatos filhotes, oferecendo mais conforto, segurança e postura adequada durante a alimentação. Seu design ergonômico com leve inclinação facilita o acesso à ração ou água, ajudando o filhote a se alimentar de forma mais natural e confortável desde os primeiros meses de vida. Com capacidade de 80mL, é ideal para pequenas porções, respeitando a rotina alimentar dos filhotes. Produzido em material resistente e de fácil higienização, proporciona praticidade no dia a dia e design moderno na cor azul. Benefícios: Design ergonômico que favorece a postura correta do filhote ao se alimentar Inclinação estratégica que facilita o acesso à ração ou água Capacidade ideal para pequenas porções, evitando desperdícios Base estável que reduz movimentação durante o uso Superfície lisa que facilita a limpeza diária Tamanho ideal para a fase de crescimento Especificações: Marca: Mypetone Produto: Comedouro Ergonômico Filhote Categoria: Alimentação Indicação: Gatos filhotes Porte recomendado: Pequeno porte Material: Plástico resistente Capacidade: 80mL Cor: Azul Apresentação: 1 unidade Formato de venda: Unitário Observações Importantes: Higienizar regularmente com água e sabão neutro Utilizar em superfície plana para melhor estabilidade Não expor a calor excessivo Supervisão recomendada durante a adaptação do filhote Mypetone: Seu pet em primeiro lugar.', 9.48, 7.11, NULL, 'Pets > Pet Accessories > Bowls & Feeders', 'https://cf.shopee.com.br/file/br-11134207-820ma-mn09fjn80ft039', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F290073877%2F53658748301', NULL, NULL, '20