INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '19299028591', 'Baqueta Spanking Colors Fluorescente Ponta Madeira 5B', 'Baqueta Spanking Colors Fluorescente Ponta Madeira 5B FOTOS ILUTRATIVAS. Descrição: Marca: Spanking Modelo: Colors Medida: 5B Madeira: Marfim Comprimento: 40,6cm Diâmetro: 1,48cm Tipo de ponta: Barril 1 Par de Baquetas Spanking Linha Colors Clássica 5B . Indicado para: Fusion, Pop, Rock, Reggae. A baqueta Spanking colors fluoerescente é produzida em marfim com as pontas em madeira. A característica mais marcante dessas baquetas é o seu design fluorescente. Quando expostas à luz negra ou iluminação especial, as baquetas brilham de forma vibrante, criando um efeito visual cativante durante apresentações ao vivo. Isso não apenas melhora a visibilidade das baquetas, mas também adiciona um toque de estilo ao seu desempenho. Estas baquetas são versáteis o suficiente para se adaptarem a uma ampla variedade de estilos musicais, desde rock e pop até jazz, samba e etc. Produzidas com material durável e equilibrado as torna ideais para bateristas de todas as disciplinas. mas também adiciona um toque de estilo ao seu desempenho. Estas baquetas são versáteis o suficiente para se adaptarem a uma ampla variedade de estilos musicais, desde rock e pop até jazz, samba e etc. Produzidas com material durável e equilibrado as torna ideais para bateristas de todas as disciplinas.', 55.6, 55.6, NULL, 'Hobbies & Collections > Musical Instruments & Accessories > Music Accessories', 'https://cf.shopee.com.br/file/br-11134207-7r98o-lmyt1r2a0q965a', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F442397041%2F19299028591', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
