INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '18698045168', 'Kit 3 Areia Biodegradável 3,8 Kg Grossa para Gatos - Great Pets', 'Areia Biodegradável Grossa Great Pets para Gatos - 3,8 Kg - Alto poder de absorção: prolonga a utilidade da areia, reduzindo a frequência de reposição; - Ajuda a reduzir odores indesejáveis, mantendo o ambiente mais agradável para o gato e tutor; - Forma torrões firmes, facilitando a remoção dos resíduos sólidos e o descarte de maneira adequada; - Matérias-primas 100% naturais: decompõe naturalmente, ajudando a reduzir o impacto ambiental. Detalhes A Areia Higiênica Great Pets Biodegradável Grossa para Gatos - 3,8 Kg, se destaca por sua composição natural e ecologicamente amigável. Produzida com ingredientes derivados de milho e mandioca, é biodegradável e orgânica. Sua principal característica é a capacidade excepcional de absorção e controle de odores, garantindo um ambiente higiênico e livre de odores desagradáveis. Além disso, forma torrões firmes, facilitando o descarte e a limpeza da caixa de areia. Dicas Especiais A limpeza da bandeja de areia deve ser diária, eliminando os dejetos no dia, evitando assim o mau cheiro. O descarte precisa ser feito em lixo comum ou em vasos de plantas e jardins (servindo de adubo), nunca descarte em vasos sanitários. Indicação: Gatos Porte/Raça: Raças Pequenas, Raças Médias, Raças Grandes Idade: Filhotes, Adultos, Idosos Composição: Milho e Mandioca Apresentação: Fardo 3,8 Kg', 274.33, 155.77, NULL, 'Pets > Litter & Toilet > Small Pet Bedding & Litter', 'https://cf.shopee.com.br/file/br-11134207-820mc-mnvsbav178jled', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F290073877%2F18698045168', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
