INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '22999205558', 'Lavadora De Alta Pressão 1700w 2000psi Bosch Ghp 200', 'Distribuído por ISmafer Ferramentas Descrição: Lavadora de Alta Pressão Bosch GHP 200 A Bosch GHP 200 é ideal para quem busca uma limpeza poderosa e prática em casa ou no trabalho. Com 1700W de potência, pressão máxima de 2000 psi e apenas 8 kg, essa lavadora entrega alto desempenho, economia de água e fácil transporte. Principais Vantagens: • Pressão máxima de 2000 PSI– remove sujeiras difíceis com facilidade • Dupla filtragem de água – protege o motor e prolonga a vida útil • Alça dobrável – facilita o transporte e o armazenamento • Acompanha acessórios para diferentes aplicações • Pronta para uso – não requer montagem Especificações Técnicas: • Potência: 1700W • Voltagem: 127V • Pressão máxima: 2000 psi • Peso: 8 kg • Mangueira: 6 metros de comprimento • Aplicação: superfícies diversas (pisos, muros, carros, motos, fachadas, etc.) Itens Inclusos: • 1 Pistola e lança de alta pressão • 1 Bico de jato rotativo (turbo) • 1 Bico de jato variável • 1 Aplicador de detergente • 1 Filtro externo • 1 Adaptador de mangueira de engate rápido • 1 Mangueira de 6 metros Limpeza Muito Mais Eficiente! • Com seu pulverizador de alta pressão, você economiza até 80% de água comparado ao uso de mangueiras comuns. • Seu jato é de 10 a 50 vezes mais potente, proporcionando agilidade e eficácia na limpeza pesada. Modos de Uso Inteligente: • Linha reta – ideal para sujeiras localizadas e maior impacto • Leque – ideal para cobrir áreas maiores com mais agilidade Ideal para: • Uso doméstico intensivo • Limpeza de pisos, fachadas, calçadas, telhados • Lavagem de veículos (carros, motos, bikes, etc.) • Pequenos comércios e prestadores de serviço Mais Eficiência no Dia a Dia Garantia Bosch de até 2 anos: 1 ano padrão + 1 ano adicional ao registrar o produto no app BeConnected. Sua limpeza nunca mais será a mesma com a Bosch GHP 200! Aviso legal • Certificado pela INMETRO. SKU: 23862 127v - 23859 220v Distribuído por Ismafer Ferramentas', 1999.9, 949.9, NULL, 'Home & Living > Tools & Home Improvement > Tools', 'https://cf.shopee.com.br/file/br-11134207-81z1k-mhvuujgw1c773e', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1617570446%2F22999205558', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
