INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '20897737994', 'Moldura Redutora 10 polegadas para 9 polegadas Expex EPX RDR-9 - EPX10UN001', 'Moldura Adaptadora 10 polegadas para 9 polegadas Expex RDR-9 Tem a multimídia 9" Polegadas mas não achou a moldura? Essa moldura é própria para multimídias 9" polegadas. A moldura é fabricada com tecnologia de alta qualidade e proporciona um design com acabamento impecável para seu veículo. Compatível com uma variedade de painel, a moldura deverá ser encaixada em uma moldura de 10" Polegadas. * Obs.: PRODUTO SIMILAR AO ORIGINAL, REQUER ADAPTAÇÃO. RECOMENDAMOS A INSTALAÇÃO POR UM PROFISSIONAL ESPECIALIZADO. * Caracteristicas: - Marca: Expex - Modelo: EPX RDR-9 Características Principais: - Compatível: Universal, molduras de 10 polegadas para transformar em 9 - Cor disponível: Preto - Modelo: Moldura 10 e 9 Polegadas - Agora você pode instalar outro som no seu veículo sem tirar sua originalidade; - Moldura Adaptadora de 10" Polegadas para aparelhos de 9" Polegadas; - Pode ser utilizada com centrais multimídias, Dvd players de 9" polegadas; - Acabamento impecável na cor PRETO (preto fosco); - Encaixe perfeito e de fácil instalação/utilização; - Longa durabilidade; - Excelente acabamento. Conteúdo da embalagem: - Moldura Adaptadora 10 polegadas para 9 polegadas Expex RDR-9', 42.48, 42.48, NULL, 'Spare Parts and Accessories for Vehicles > Internal Accessories for Automobiles > Others', 'https://cf.shopee.com.br/file/sg-11134201-7rdwf-lyv2awbzg2zsb3', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F371036439%2F20897737994', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
