INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '23793892967', 'Tampa Modular Plasútil Encaixa 15552 T6', 'Tampa Modular Plasútil Encaixa 15552 T6 Dimensao: (Comp x Larg x Alt): 21,9 x 14,6 x 0,9 cm Tampa Modelo T6 Modelo compatível com três modelos de Caixas EnCaixa de alturas diferentes A Tampa T6 da Linha EnCaixa colabora na organização de itens que ocupam espaço mediano na profundidade e na largura, é adaptável a três produtos da mesma linha com alturas distintas, ela serve como tampa e também como bandeja para alocar objetos em geral O sistema de organização EnCaixa conta com atributos que são essenciais para qualquer organização: 10 formatos de Tampas 26 formatos de Caixas: todos múltiplos do menor formato Paredes retas: sem ângulo, otimizando 100% do espaço na organização! Empilhamento perfeito (com ou sem tampa): o fundo de cada produto encaixa perfeitamente no seu semelhante! Tampas: vendidas separadamente, conforme a necessidade da organização, uma vez que o fundo de cada organizador já fecha o organizador que está posicionado abaixo! Supertransparente: Rápida identificação dos itens armazenados. O que não é visto, não é lembrado! Versatilidade: encaixam em qualquer espaço, seja ele vertical ou horizontal. Organização viva: os organizadores podem migrar de uso e ambiente, conforme o momento ou necessidade de organização. Mais que uma caixa, um sistema de organização! A linha de organizadores enCaixa conta com 26 modelos de caixas, que variam em altura, largura e profundidade, o que torna esse o organizador mais completo e mais versátil do mercado. Fabricado em Politereftalato de etileno (PET) um tipo de plástico super transparente, atóxico e que não contém BPA em sua composição. Este material é MUITO MAIS RESISTENTE A IMPACTOS e mais maleável que a versão anterior em PS (Poliestireno). Produto sensível ao calor: Não pode ser aquecido no micro-ondas. Não pode ser lavado na lava-louças. .', 17.9, 17.9, NULL, 'Home & Living > Home Organizers > Storage Boxes, Bags & Baskets', 'https://cf.shopee.com.br/file/sg-11134201-7renu-m8l0vxgidiuff0', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F648928964%2F23793892967', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
