INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '11848337148', 'Inseticida Aerossol Raid Multi-Insetos Base Água 420ml Embalagem Econômica', 'Raid Multi Insetos garante proteção por 24h contra a maioria dos insetos, como mosquitos, moscas, baratas, formigas e problemas de infestações em geral, incluindo os mosquitos que podem transmitir a dengue, o zika vírus e a febre Chikungunya. Agite bem antes de usar. Feche o ambiente e pulverize devagar, por 7 a 9 segundos, em todas as direções, para uma área de 10 m2, mantendo o spray a pelo menos 1 m de distância de paredes, tecidos e móveis. Deixe o produto agir por 15 a 20 minutos. Não permaneça na área tratada. Ventile o ambiente antes de retornar. Para garantir uma ação mais rápida, aplique o produto diretamente no inseto, mantendo pelo menos 1 m de distância de paredes, tecidos e móveis.', 30.59, 30.59, NULL, 'Home & Living > Home Care Supplies > Others', 'https://cf.shopee.com.br/file/sg-11134201-823py-mp3qljus12q36e', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F528273775%2F11848337148', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
