INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '19599443076', 'Cuba Pia Dalla Para Banheiro com Válvula Oculta Preto Brilho', 'O conjunto Cuba Dalla com Valvula Oculta é um item essencial para qualquer banheiro moderno. Com seu design elegante e minimalista, esta cuba é perfeita para adicionar um toque de sofisticação ao seu espaço. Combinando funcionalidade e estilo, esta cuba é a escolha perfeita para transformar o seu banheiro em um ambiente elegante e funcional. Modelo: Cuba Dalla com Válvula Oculta; - Cuba: Altura: 11 cm; Largura: 31 cm; Comprimento: 44 cm; Profundidade: 8 cm; Tipo: de sobrepor; - Tampo para ocultar a válvula: Espessura: 3 mm; Largura: 22,4 cm; Comprimento: 34,7 cm; Material: Mármore Sintético; Forma: Retangular; Inclui Válvula: Sim; Modelo da Válvula: ABS; Acabamento: Cromado; Material: ABS; Fixação: Rosca Rosca: 7/8” Inclui torneira: Não; Embalagem do envio: Isopor, papelão e plástico. Informações adicionais: - Os objetos que ambientam as fotos não acompanham o produto; - É de inteira responsabilidade do cliente a montagem do produto e/ou instalação, assim como possíveis irregularidades provenientes de manuseio inadequado; - Embora o produto acompanhe o manual de montagem, verifique a complexidade antes de decidir montá-lo sozinho, recomendamos que contrate um profissional de sua confiança; - Fique atento, nossas cores podem sofrer alterações dependendo do seu monitor; - ANTES DE MONTAR O SEU PRODUTO, verifique se há alguma peça danificada, caso esteja, prestaremos a devida assistência dentro do prazo da garantia.', 269.98, 269.98, NULL, 'Home & Living > Tools & Home Improvement > Sinks & Water Taps', 'https://cf.shopee.com.br/file/sg-11134201-7rdvk-m0ete9v5p70pd1', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F401986069%2F19599443076', NULL, NULL, '2026-07-28T02:11: