INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '13547151707', 'Par Farol Vectra 2010 2011 2012 Foco Duplo Máscara Negra', 'Código do produto: 48456 VALOR ANUNCIADO REFERENTE AO PAR - Direito + Esquerdo. O farol é uma peça essencial para sinalização e visibilidade em vias noturnas e para maior segurança eles devem estar sempre em bom estado. E aqui temos o produto ideal para você. Este item possui material de alta qualidade e resistência, composto com sua lente acrílico lisa,encaixe da lâmpada H7 / H1 que suporta até 55W e um design que deixa seu carro com aspecto diferenciado de todos os outros. Compatível com: Chevrolet - Vectra 2010 - Vectra 2011 - Vectra 2012 Especificações Técnicas: - Foco Duplo - Regulagem Manual - Encaixe da lâmpada H7 / H1 - Lente Lisa - Material da Lente em Acrílico - Material da Carcaça em Plástico - Suporta lâmpadas de até 55W ATENÇÃO Garantia - 3 Meses O valor anunciado referente ao Par mais o frete por conta do comprador. A empresa não se responsabiliza pela má instalação do produto. Procure por um profissional especializado!', 925.96, 925.96, NULL, 'Spare Parts and Accessories for Vehicles > Spare Parts for Automobiles > Lighting', 'https://cf.shopee.com.br/file/bcab1e0e122f371535b5d312aadbfae0', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F469347212%2F13547151707', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '22197321423', 'Fast Remove 1,5l Protelim - Remove Cola Piche Grude Insufilm', 'PRODUTO COM NOTA FISCAL E PRONTA ENTREGA !!! REMOVEDOR DE COLA FAST REMOVE PROTELIM 1,5l FAST REMOVE é um produto desenvolvido com matérias-primas de última geração, proporcionando uma qualidade inovadora como REMOVEDOR DE COLA INSULFILM, COLA DE ADESIVOS, PICHES, TINTAS DE CANETA, CHICLETES, etc. Também pode ser aplicado em superfícies como VIDRO, METAIS e FÓRMICAS, sem deixar manchas. BENEFÍCIOS: Remove tintas de caneta, Cola e Piche EMBALAGENS: 500ml e 1,5l DILUIÇÃO: PRONTO USO MODO DE USAR Borrife o FAST REMOVE sob a superfície. Certifique-se que o produto tenha sido aplicado uniformemente. Deixe agir de 30 a 60 segundos. Remova todo produto com uma flanela de microfibra. Se necessário, repita a aplicação. IMPORTANTE: Em superfícies delicadas como couro, Courvin, etc. Faça teste com o produto em uma pequena parte da superfície a ser limpa para verificar se a superfície foi atacada pelo produto, antes da aplicação na sua totalidade. Utilize Equipamento de Proteção Individual (EPIs). OBS: EMBALAGEM NOVA!!!', 199.9, 199.9, NULL, 'Spare Parts and Accessories for Vehicles > Vehicular Care > Others', 'https://cf.shopee.com.br/file/br-11134207-81z1k-mestmoouvzlu7c', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F999160347%2F22197321423', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '58259686826', 'Coqueiro Atum em Pedaços ao Óleo', 'O Atum em Pedaços ao Óleo Coqueiro é uma opção prática e saborosa para suas refeições. Uma excelente fonte de Proteína, Ômega 3 e Vitamina D, pronto para comer e sem conservantes. Versátil, combina com diversos pratos e já vem pronto para ser usado em lanches, macarrões e saladas. Experimente! Ingredientes: Atum, óleo vegetal de soja, água, sal e extrato vegetal em pó (extratos de soja, cenoura e batata).', 11.79, 11.79, NULL, 'Food & Beverages > Food Staples > Canned Food', 'https://cf.shopee.com.br/file/sg-11134201-825ag-mqnel0blvll7d6', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1676554925%2F58259686826', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '10970121409', 'Par Lanterna Ka 2008 2009 2010 2011 2012', 'Código do Produto: 103627 VALOR ANUNCIADO REFERENTE AO PAR - Direito + Esquerdo. A Lanterna traseira é uma peça essencial para sinalização e visibilidade em vias noturnas. Este item possui material de alta qualidade e resistência, composto com sua lente em acrílico liso, que suporta lâmpadas de até 55W. Compatível com: Ford - Ka 2008 - Ka 2009 - Ka 2010 - Ka 2011 - Ka 2012 Especificações Técnicas: - Lente Lisa - Material da Lente em Acrílico - Material da Carcaça em Plástico - Suporta lâmpadas de até 55W ATENÇÃO Garantia - 3 Meses O valor anunciado é referente ao par. A empresa não se responsabiliza pela má instalação do produto. Procure por um profissional especializado!', 396.48, 396.48, NULL, 'Spare Parts and Accessories for Vehicles > Spare Parts for Automobiles > Lighting', 'https://cf.shopee.com.br/file/49c2eaac430cf0464520d396c4c7b2db', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F469347212%2F10970121409', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '22491523084', 'Chave Impacto 1/2 Pol. 350Nm 20V 2Ah Intercambiável Velocidade Variável Carregador Rápido FORTG', 'Loja do Mecânico - O que você precisa, nós temos! Chave de Impacto FORTG, com encaixe de 1/2" e 350Nm de força de torque, uma das mais fortes e potentes da categoria, com variações de velocidade e rotações reversíveis classifica a ferramenta como ideal para trabalhos que exijam força, rapidez e segurança em apertos e desapertos dos mais fortes parafusos e porcas, sua utilização é indicada para montagens industriais, borracharias, autocenters e com nichos automotivos, aeronáuticos e navais. Sua bateria High Power (de longa duração) de 20V 2Ah é responsável pelo desempenho notável da ferramenta e intercambiável para toda linha Azul FORTG. O carregador rápido e compacto que compõe e faz da chave de impacto essencial para os mais exigentes profissionais. Especificações Técnicas # Chave de Impacto - Voltagem: 20V - Mandril de Encaixe: 1/2" • 12.7mm - Velocidade Mecânica: 0-2600 rpm - Taxa de Impacto: 0-3200 bpm - Torque: 350 Nm - Rotação Reversível - Peso: 2 Kg # Bateria FG3002XX High Power - Voltagem: 20V - Potência: 2Ah - Tipo de Bateria: Íons de Lítio - Dimensões: 11.4x7.5x4.5cm - Peso: 300g - Intercambiável com os modelos FORTG • FG3000X • FG3014X • FG3027X # Carregador Rápido Compacto - Voltagem: 127V-220V AC • Bivolt - Frequência: 60Hz - Tensão de Saída: 21.5V • 1.5A - Luzes de Alerta de Funcionamento - Cabo: 1.8m - Padrão: 2 pinos e plug DC Macho - Peso: 157g Conteúdo da Embalagem - Chave de Impacto - Carregador Rápido Compacto Bivolt - Bateria 20V - Clipe para Cinto Importante - Garantia 3 meses; - Enviamos em até 24 horas úteis; - A embalagem pode variar de acordo com o estoque do fabricante; - A cor do produto pode variar de acordo com a tela do seu smartphone/computador; - Qualquer dúvida, utilize o campo "Perguntas e Respostas" e converse com o nosso SAC.', 369.99, 347.79, NULL, 'Home & Living > Tools & Home Improvement > Tools', 'https://cf.shopee.com.br/file/sg-11134201-7qvf1-ljbizkdwu9s60c', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F902146556%2F22491523084', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '21697727523', 'Motocultivador BTTG6.5 Tratorito à Gasolina 6,5cv Partida Manual - Branco', 'Loja do Mecânico - O que você precisa, nós temos! O Moto cultivador Tratorito Branco BTTG6.5 (6,5CV) é a escolha certa para você que precisa de produtividade no preparo do solo, cultivo e adubação em pequenas e médias áreas. Movido a gasolina, ele foi projetado para revolver e preparar diversos tipos de solo, entregando desempenho consistente com motor de 196 cm³, partida manual e combustão eletrônica. Também é conhecido como moto enxada (Portugal) e motoazada, e se destaca pela adaptabilidade na agricultura familiar e horticultura. Para facilitar o trabalho, o equipamento conta com largura de corte de até 800 mm e profundidade ajustável de 150 a 300 mm, ajudando a acelerar o serviço com melhor cobertura por passada. O tanque de 6 litros aliado à tecnologia ECO (exclusiva Branco Motores) contribui para mais economia de combustível durante a operação, reduzindo paradas e aumentando a eficiência no campo. A mobilidade e o controle também são pontos fortes. Suas rodas agrícolas 4.00-8 (8") oferecem mais estabilidade e deslocamento, e o ajuste de guidão melhora a ergonomia, especialmente em uso prolongado. A transmissão com 2 marchas para frente, neutro e ré facilita manobras e posicionamento, enquanto o farol amplia a segurança em trabalhos noturnos ou locais de baixa luz. Confira também ferramentas para jardim, agricultura e veja também nossa linha de roçadeiras, pulverizadores e itens para preparo de solo. Se você precisa ganhar ritmo no plantio e na preparação do terreno, este tratorito 6,5CV entrega força, praticidade e robustez. Benefícios e Destaques do Produto - 6,5CV (196 cm³): potência para preparo de solo com eficiência - Largura de corte 800 mm e profundidade 150–300 mm: mais produtividade - Tecnologia ECO: economia de combustível - 2 marchas à frente + ré + neutro: manobras mais fáceis - Rodas 8" e pneus agrícolas 4.00-8: estabilidade e mobilidade - Farol: apoio para trabalhos em baixa luminosidade - Acompanha rodas e enxadas rotativas: pronto para operar Aplicações do Produto - Preparação e revolvimento do solo para plantio - Hortas, chácaras, sítios e agricultura familiar - Apoio em jardinagem e trabalhos rurais com necessidade de produtividade Especificações Técnicas - Partida: manual - Combustível: gasolina | Tanque: 6 L - Cilindrada: 196 cm³ | Potência máx.: 6,5 CV a 3600 rpm - Torque máx.: 1,35 kgfm a 2500 rpm | Compressão: 8,5:1 - Diâmetro x curso: 68 mm x 54 mm | Combustão: eletrônica - Largura de corte: 800 mm (com disco) | Profundidade: 150 a 300 mm - Transmissão: frente / neutro / ré - Tração/marchas: acompanha pneus e enxadas rotativas Conteúdo da Embalagem - 01 Moto cultivador Tratorito à Gasolina 6,5CV Partida Manual BTTG6.5 - Branco - Kit ferramentas - Lâminas de corte - Manual - Rodas com pneus agrícolas 4.00-8 Perguntas Frequentes - FAQs Para que serve um moto cultivador (tratorito)? - Serve para preparar o solo, facilitando arar, revolver e cultivar a terra. Esse moto cultivador é indicado para quais usos? - É indicado para hortas, sítios, chácaras, agricultura familiar e pequenos terrenos. O que significa potência de 6,5 CV? - Indica força suficiente para trabalhos agrícolas leves e médios. O moto cultivador funciona com qual combustível? - Funciona à gasolina. O que é partida manual? - É o sistema de ligar o motor por corda retrátil, simples e confiável. Esse moto cultivador aceita implementos agrícolas? - Sim, pode ser usado com enxadas rotativas e outros implementos compatíveis. É indicado para solo duro ou compactado? - Sim, desde que o solo seja preparado gradualmente e dentro da capacidade do equipamento. O motor é 4 tempos? - Sim, motores 4T são mais econômicos, duráveis e fáceis de manter. O moto cultivador substitui um trator agrícola? Não, mas é ideal para espaços menores e serviços específicos. É fácil de operar? - Sim, possui controles simples, sendo adequado para operadores iniciantes. Consome muito combustível? - Não, o consumo é baixo para a categoria, dependendo da carga e do solo. Pode ser usado em terrenos inclinados? - Pode, com cuidado e dentro dos limites de segurança. O equipamento é indicado para uso profissional? - Sim, para uso frequente em pequenas propriedades. Precisa de manutenção frequente? - Apenas manutenção básica, como troca de óleo e limpeza do filtro de ar. Quais cuidados aumentam a vida útil do moto cultivador? - Manter manutenção em dia, usar combustível limpo e respeitar a capacidade do equipamento. Importante - Enviamos em até 24 horas úteis; - A embalagem pode variar de acordo com o estoque do fabricante; - A cor do produto pode variar de acordo com a tela do seu smartphone/computador; - Qualquer dúvida, utilize o campo "Perguntas e Respostas" e converse com o nosso SAC.', 5399.99, 4765.79, NULL, 'Home & Living > Gardening > Gardening Tools', 'https://cf.shopee.com.br/file/sg-11134201-7rd3w-lx2upl5xwzhb5c', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F902146556%2F21697727523', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '40615748321', 'Ração PremieR Ambientes Internos sênior raças pequenas cachorros 7+ frango & salmão 1,0kg', 'Ração PremieR Ambientes Internos sênior raças pequenas cachorros 7+ frango; salmão 1,0kg Pet: Cachorros Idade: Adultos apartir de 7 anos Porte de Raça: Pequeno Condição: Ambientes Internos Sabor: Frango e Salmão Tamanho de grão: Específico para raças pequenas Quais os benefícios da Ração PremieR Ambientes Internos sênior raças pequenas? PremieR Ambientes Internos Senior para cachorros apartir de 7 anos sabor frango e salmão é um alimento super premium destinado e formulado para as necessidades de cachorros mais velhinho, possuindo uma ótima palatabilidade e garantindo um envelhecimento saudavel. Possui redução de sódio em sua composição, alem de auxiliar manutenção nas articulações e reduzindo o odor das fezes. Qual a diferença das rações comuns e das rações seniors? As rações garantem ao seu pet a nutrição e vitaminas que o organismo dele necessita, mas ao decorrer do envelhecimento dele a sua necessidade energética e nutricional se modifica, não necessitando de certos nutrientes e vitaminas, e até apresentando dificuldades em absorver nutrientes necessários nessa fase. As rações sênior vão prover ao pet uma dose adequada das nitaminas que eles mais necessitam e reduzir vitaminas que acabam por serem prejudiciais nas porções que eles consumiam antes, alem de uma quantidade melhor de fibras digestivas para facilitar a absorção dos nutrientes e funcionamento do aparelho digestivo. Por que oferecer uma ração específica para cachorros de ambientes internos? As rações comuns e as rações para animais de ambientes internos se diferenciam por sua composição de nutrientes, uma vez que rações comuns são indicadas para cachorros que acabam por se exercitarem mais em espaços abertos tanto em quintais ou parques, quanto os cachorros que são mais caseiros, tanto os que não tem um quintal em casa ou que vivem em apartamentos. O alimento para estes pets tem de ser mais equilibrado, com menos gordura e que auxilie no controle do peso e manutenção do pelo e pele. Por que a Ração PremieR Ambientes Internos Senior raças pequenas para cachorros 7 anos + frango; salmão é alimento Super Premium? Os alimentos Super Premium apresentam um nível nutricional mais elevado, e atendendo os requisitos mínimos estabelecidos pelo Conselho de Nutrição Animal, os níveis nutricionais devem estar em equilíbrio entre os níveis mínimos e máximos apresentados pela AAFCO (Association of American Feed Control Officials). A Ração PremieR Ambientes Internos Senior raças pequenas para cachorros frango; salmão 7 anos + foi produzida atendendo todos os requisitos. Esses níveis são determinados pelas pesquisas, que buscam ótimas condições de pelagem, desenvolvimento de musculatura e, principalmente, otimização de performance na reprodução e no sistema imunológico. Selo Cage Free Bem estar dos animais é saúde para todos, levamos este selo conosco pois os ovos que utilizamos em nossos produtos são de galinhas criadas livres de gaiolas,com áreas de repouso para que os animais possam manifestar o comportamento natural da sua espécie, garantindo o bem-estar do animal. Quais os tamanhos das embalagens disponiveis de Ração PremieR Ambientes Internos Sênior raças pequenas cachorros 7+? Nas lojas da você encontra a Ração PremieR Ambientes Internos Sênior raças pequenas cachorros 7+ nas apresentações: 1,0kg, 2,5kg e 12,0kg. Composição: Ingredientes da Ração PremieR Ambientes Internos Senior raças pequenas para cachorros 7 anos + frango; salmão. Farinha de vísceras de frango, farinha de salmão, ovo desidratado, proteína isolada de suíno, quirera de arroz, polpa de beterraba, aveia, gordura de frango, óleo de peixe, ácido propiônico, antioxidantes BHA e BHT (0,012%), betaína, cloreto de potássio, DL-metionina, extrato de yucca (0,06%), fruto-oligossacarídeos, hexametafosfato de sódio, hidrolisado de suíno e frango, L-carnitina, levedura seca de cervejaria, mananoligossacarideos, parede celular de levedura , sulfato de condroitina, sulfato de glicosamina, taurina, vitamina A, vitamina B12, vitamina C, vitamina D3, vitamina E, vitamina K3, ácido fólico, ácido pantotênico, biotina, cloreto de colina, niacina, piridoxina, riboflavina, tiamina, cobre aminoácido quelato, ferro aminoácido quelato, iodeto de potássio, manganês aminoácido quelato, proteinato de selênio, sulfato de cobre, sulfato de ferro, sulfato de manganês, sulfato de zinco, zinco aminoácido quelato.', 59.88, 50.77, NULL, 'Pets > Pet Food > Dog Food', 'https://cf.shopee.com.br/file/sg-11134201-824hz-mdzznbjj91q922', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1470189844%2F40615748321', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '23299021814', 'Whey Protein Concentrado - 1 Sachês 30g Doce de Leite com Café - NewNutrition', 'É uma proteína obtida a partir de processos de filtração e microfiltração do soro do leite bovino. Dependendo da concentração de proteínas pode ser classificado como concentrado 80%, Whey Protein Isolado 90% ou Whey Protein Hidrolisado mais de 90%. O Whey Protein Concentrado tem 80% de concentração em proteína de alto valor biológico, pois fornece todos os aminoácidos essenciais para o organismo, inclusive os BCAAs e glutamina. Possui como características marcantes seu elevado valor nutricional e uma rápida absorção, disponibilizando assim aminoácidos para a recuperação das células musculares e para a síntese proteica. Como Tomar Misturar 1 Sachê em 200ml de água ou em sua bebida de preferência. ESTE PRODUTO DESTINA-SE A ATLETAS E INDIVÍDUOS ACIMA DE 19 ANOS. ESTE PRODUTO NÃO É UM MEDICAMENTO. NÃO EXCEDER A RECOMENDAÇÃO DIÁRIA DE CONSUMO INDICADA NA EMBALAGEM. MANTENHA FORA DO ALCANCE DE CRIANÇAS. Ingredientes Proteína concentrada de soro do leite, doce de leite em pó, café solúvel extra forte, espessante goma xantana e edulcorante sucralose. ALÉRGICOS: CONTÉM DERIVADOS DE LEITE. CONTÉM LACTOSE. Não contém Glúten. ...', 20.3, 20.3, NULL, 'Health > Food Supplement > Fitness', 'https://cf.shopee.com.br/file/sg-11134201-82581-mfv7s5mfcwsv4b', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F976704374%2F23299021814', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '18499923565', 'Arado Husqvarna Tf338 Metal 588266601 130797', 'Arado Husqvarna Tf338 Metal 588266601 130797 - Preto O Arado Husqvarna Tf338 é a ferramenta ideal para o preparo eficiente e robusto de solos, garantindo durabilidade e performance em suas atividades agrícolas. O Arado Husqvarna Tf338, modelo 588266601, é uma ferramenta agrícola essencial projetada para o preparo de solos em diversas aplicações, desde hortas domésticas e jardins até pequenas propriedades rurais. Fabricado em aço de alta resistência, este arado garante durabilidade excepcional e um desempenho confiável no revolvimento da terra. Seu design robusto facilita a aeração do solo e o preparo para o plantio, otimizando o trabalho em campo. É compatível com motocultivadores Husqvarna TF338 e TF545D, oferecendo versatilidade e integração perfeita com seus equipamentos. Diferenciais: Fabricado em aço resistente: Garante uma vida útil prolongada e alta performance mesmo em condições de uso intensivo, suportando o trabalho pesado no campo. Design robusto e eficiente: Desenvolvido para um preparo de solos otimizado, o arado revoluciona a terra com facilidade, melhorando a aeração e a estrutura para o cultivo. Ideal para diversas aplicações: Perfeito para hortas, jardins, e pequenas áreas de cultivo, adaptando-se a diferentes necessidades de preparo de solo. Compatibilidade garantida: Projetado para se integrar perfeitamente com motocultivadores Husqvarna TF338 e TF545D, assegurando um encaixe preciso e operação segura. Mais sobre o Produto: Com o Arado Husqvarna Tf338, você obtém um auxílio valioso para melhorar a produtividade do seu solo, facilitando o plantio e o desenvolvimento saudável das culturas. Sua construção em metal de alta qualidade resiste à corrosão e ao desgaste natural do trabalho agrícola. A facilidade de acoplamento aos motocultivadores compatíveis torna a troca de implementos ágil, otimizando seu tempo de trabalho no campo. Dicas de Uso: Para um preparo de solo eficiente, utilize o arado acoplado a um motocultivador Husqvarna compatível, seguindo as instruções do manual do seu equipamento. Realize manutenção simples regularmente, como a limpeza após o uso e verificação de parafusos e conexões, para prolongar a vida útil do arado. Armazene o arado em local seco e protegido da umidade quando não estiver em uso para evitar a oxidação do aço. Ficha Técnica: Marca: Husqvarna Modelo: Tf338 Código de Referência: 130797 EAN: 7393089314865 Material: Aço Cor: Preto Compatibilidade: Motocultivadores Husqvarna TF338/TF545D Dimensões do Produto (AxLxP): 400mm x 350mm x 150mm Peso Líquido: 12 kg Peso Bruto (embalagem): 14 kg Tipo de Embalagem: Caixa Garantia do Fornecedor: 12 meses Diferenciais: Fabricado em aço resistente: Garante uma vida útil prolongada e alta performance mesmo em condições de uso intensivo, suportando o trabalho pesado no campo. Design robusto e eficiente: Desenvolvido para um preparo de solos otimizado, o arado revoluciona a terra com facilidade, melhorando a aeração e a estrutura para o cultivo. Ideal para diversas aplicações: Perfeito para hortas, jardins, e pequenas áreas de cultivo, adaptando-se a diferentes necessidades de preparo de solo. Compatibilidade garantida: Projetado para se integrar perfeitamente com motocultivadores Husqvarna TF338 e TF545D, assegurando um encaixe preciso e operação segura.', 359.87, 287.9, NULL, 'Home & Living > Gardening > Others', 'https://cf.shopee.com.br/file/sg-11134201-82622-mlfbs2yu366a60', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F412527932%2F18499923565', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '17172174649', 'Retrovisor F800 Para Moto Honda Lead Elite 125 Giro 360 Gvs Lente Convexa + Par Adapt M8 Para M10', '======================================================================= DISPONÍVEL: ROSCA HONDA + ADAPTADOR MOTO ELITE/ LEAD M8 PARA M10 ESPECIFICAÇÕES TÉCNICAS RETROVISOR: - Design Original (conforme fotos) - Adaptável todos modelos de moto (Rosca Universal M10) - Fabricado no Brasil - Excelente qualidade - Na Cor preta - Equipado com LENTE CONVEXA - Maior campo de visão ao condutor - Sistema GIRO 360º - Encaixe perfeito - Fácil instalação - Modelo idêntico ao original (conforme tamanho e peso evitando trepidações) ESPECIFICAÇÕES TÉCNICAS ADAPTADOR: - ROSCA M8 MOTO ELITE/ LEAD PARA ROSCA M10 CONTEÚDO da EMBALAGEM: - 1 (um) Par de retrovisor para moto (esquerdo/ direito) - 1 (um) Par de Adaptador M8 para M10 IMPORTANTE: - Garantia contra defeitos de fabricação. - Não nos responsabilizamos pelo mau uso do produto. - Recomendamos que a troca/ instalação seja realizada por um profissional qualificado. - Tire todas as dúvidas no chat, temos uma equipe totalmente qualificada a disposição pronta para ajudar. ATENÇÃO! - AS ETIQUETAS DE ENVIO SÃO GERADAS AUTOMATICAMENTE ATRAVÉS DO SEU CADASTRO VERIFIQUE CORRETAMENTE SEU ENDEREÇO PARA EVITAR PROBLEMAS CAUSADOS NA ENTREGA DOS PRODUTOS! OBRIGADO. MOON MOTO PEÇAS.', 152.99, 149.94, NULL, 'Spare Parts and Accessories for Vehicles > Spare Parts for Motorcycles > Side Mirrors', 'https://cf.shopee.com.br/file/br-11134207-820l6-mp3w2ys28pa8e5', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F305169728%2F17172174649', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '22399542673', '1l Aditivo Orgânico Radiador Pronto Uso Rosa Radiex Bio Coolant', '1 Litro Aditivo Protetor Orgânico de Radiador Pronto Uso Bio Coolant Original Rosa É um composto químico desenvolvido com polímeros de alta performance, pronto para ser usado no sistema de arrefecimento de motores. Contém inibidores de corrosão para o ressecamento das mangueiras e lubrifica a bomba d’água. Na proporção adequada também para a proteção dos metais e motor do sistema dos veículos a gasolina, álcool, diesel, GNV, flex e motores estacionários. Características: - Marca: Radiex; - Cor: Rosa; - Linha: Bio Coolant; - Pronto para Uso; - Protetor do Sistema de Arrefecimento de motores linha leve, pesada e estacionários; - Orgânico ( OAT ); - Inibe o ressecamento das mangueiras; - Evita corrosão, fervura e congelamento. Composição: - Inibidores Orgânicos Anticorrosivos; - Antiespumante; - Preservante; - Corante; - Antitérmico. Conteúdo da Embalagem: - 1 Litro Protetor do Sistema de Arrefecimento Orgânico Rosa. Modo de Usar: Execute a limpeza completa no sistema de arrefecimento com água desmineralizada. Caso tenha excesso de sujeira recomenda-se a aplicação do Limpa Radiador Radiex vendido na nossa loja. Colocar o Protetor de Arrefecimento Pronto para uso no vaso expansor ou radiador até completar o nível indicado. Exemplo: Para um sistema cuja capacidade é de 5 litros, colocar 5 litros do Aditivo. Efetue a substituição do produto no sistema a cada 1 ano. ATENÇÃO: Não misturar ou diluir o produto com outros aditivo e soluções. Validade: 3 Anos. Garantia de fábrica: 3 meses', 22.0, 18.7, NULL, 'Spare Parts and Accessories for Vehicles > Spare Parts for Automobiles > Additive and Lubricant', 'https://cf.shopee.com.br/file/br-11134207-820m9-mpsairc9vksg15', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1462054129%2F22399542673', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '23993089603', 'Defletor Calha de Chuva Fox 2004 a 2019 4 Portas', 'Defletor Calha de Chuva Fox 2004 a 2019 4 Portas A Ecoflex possui uma vasta linha de calhas defletores automotivas para os mais diversos modelos. Utiliza matéria-prima de primeira, 100% acrílico, com tecnologia 3M e instalação simples. Os produtos comercializados pela Ecoflex têm como objetivo trazer conforto e segurança em seu automóvel nos dias de chuva. Com a calha de chuva a água da chuva não entrará no interior do veículo e evita que os vidros embacem. Compatibilidade: • Fox 2004 a 2019 4 Portas • Crossfox 2004 a 2019 4 Portas • Spacefox 2004 a 2019 4 Portas Especificações: • 100% Acrílica; • Proteção e Design; • Contra chuva e sol; • Fixada por Fita Dupla Face 3M; • Não deixa os vidros embaçarem. Conteúdo da Embalagem: • 4 Calhas Defletores de Chuva Garantia: • 5 Anos (defeito de fabricação) Se tiver alguma dúvida a equipe Triangulo Auto Parts estará pronta para lhe atender.', 133.9, 109.9, NULL, 'Spare Parts and Accessories for Vehicles > External Accessories for Automobiles > Others', 'https://cf.shopee.com.br/file/sg-11134201-7rd6l-lwg9h5l0e0ws03', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1276072791%2F23993089603', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
