INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '42103847107', 'Shampoo Seda Toque de Seda 300ml', 'O Shampoo Toque de Seda é enriquecido com 2% Amino-Silk Complex, um poderoso mix com a proteína da seda, que se conecta com as fibras capilares, resultando em um cabelo mais forte e com toque macio. Em combinação com o condicionador, este produto capilar oferece o combo perfeito para seu momento de lavagem com controle prolongado do frizz* e garante 1,5x mais maciez e sedosidade. Modo de uso: coloque o shampoo na mão, aplique nos cabelos, massageie suavemente e depois enxágue. A nova linha Toque de Seda é ideal para quem busca um aliado no controle do frizz e não abre mão de fios sedosos com brilho intenso e movimento. Todos os produtos são enriquecidos com Amino-Silk Complex, a novidade de Seda para entregar cabelos mais macios por 1 semana*. Conheça e experimente a linha completa para resultados ainda mais incríveis e desfrute de um cabelo mais sedoso que desliza como a seda. *Com o uso de Shampoo e Condicionador vs shampoo sem agentes condicionantes.', 21.58, 21.58, NULL, 'Beauty > Hair Care > Shampoo', 'https://cf.shopee.com.br/file/sg-11134201-7rasw-masm9ojbh3ky6e', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F546513063%2F42103847107', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
