INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '23191774773', 'Kit Pistao E Aneis Rik Xt 225 Tdm 225 Ttr 230 0,25 Premium', 'PISTAO KIT COM ANEL RIK PREMIUM XT 225 - TDM 225 - TTR 230 0,25mm Moto Compativeis: - XT 225 -TDM 225 -TTR 230 KIT PREMIUM - Conjunto nobre de Pistao KMP com Anel Rik, capaz de atender os principais modelos de motos baixa cilindrada. Beneficios de um KIT com qualidade OEM (Fabricante Original do Equipamento), que garante extrema qualidade, desempenho e durabilidade. RIK - E a maior fabricante de aneis para pistao do mundo e fornecedora das principais montadoras de motos de baixa cilindrada que buscam um produto de excelencia, produzido em Taiwan com qualidade OEM (Fabricante Original do Equipamento). Acompanha: 01 jogo de aneis - Marca RIK 01 unidade pistao, pino, e trava - Marca KMP PREMIUM Pino do tamanho original da moto.', 219.0, 219.0, NULL, 'Spare Parts and Accessories for Vehicles > Spare Parts for Motorcycles > Engine', 'https://cf.shopee.com.br/file/sg-11134201-7qvdr-lj76h364cxe552', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F338071078%2F23191774773', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '22499188675', 'Boné Coca Cola Básico Metal Julia Unissex Casual Ajustável Confortável Estilo Urbano', 'Boné Coca Cola Basico Metal Julia Unissex: Estilo e Versatilidade para o Dia a Dia Descubra o Boné Coca Cola Basico Metal Julia Unissex, um acessório essencial que combina o estilo atemporal da marca Coca Cola com um design moderno e versátil. Ideal para quem busca um toque de personalidade e conforto em seu visual diário, este boné é a escolha perfeita para complementar qualquer look casual. Seus diferenciais incluem: Design básico e atemporal que se adapta a diversas ocasiões. Detalhe em metal que adiciona um toque de sofisticação. Conforto garantido para uso prolongado. A autenticidade da marca Coca Cola, reconhecida mundialmente. Este boné unissex é perfeito para passeios, encontros com amigos ou simplesmente para adicionar um toque despojado ao seu estilo. Sua versatilidade o torna um item indispensável no guarda-roupa de qualquer pessoa que valoriza moda e praticidade. Especificações Completas Produto: Boné Coca Cola Basico Metal Julia Unissex Marca: Coca Cola Gênero: Unissex EAN: 7893242564507 Adquira já o seu Boné Coca Cola Basico Metal Julia Unissex e leve o icônico estilo Coca Cola para o seu dia a dia.', 119.9, 89.93, NULL, 'Fashion Accessories > Hats & Caps', 'https://cf.shopee.com.br/file/sg-11134201-821fr-mgy3wotsbpxk66', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1191965739%2F22499188675', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
