INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '11610406726', 'Isca Artificial Soft Criatura Para Traíra Swin Frog Várias Cores', 'Isca Artificial Soft Criatura Para Traíra Swin Frog Isca Artificial Soft Swin Frog, é uma isca elaborada e desenvolvida para se obter o máximo de resultado em suas pescarias devido ao seu trabalho na aguá. Podendo ser trabalhada em superfícies limpas ou com muita vegetação. Esta isca pode ser usada com anzol offset simples ou com anzol offset lastreado. Fabricada com material de alta qualidade e durabilidade, não derretem. Indicada para: Traíras, Black Bass, Dourados, Tucunarés e outros predarores. ESPECIFICAÇÕES Marca: Alligator Modelo: Swin Frog Comprimento 10cm Peso 10g Embalagem 1 peça', 16.89, 16.39, NULL, 'Sports & Outdoors > Sports & Outdoor Recreation Equipments > Fishing', 'https://cf.shopee.com.br/file/br-11134207-7r98o-lr3d0bkut0l7c4', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F320275364%2F11610406726', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
