INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '57910922059', 'Livro Viver é perigoso - Capa Comum', 'Uma obra essencial para quem quer entender as raízes da crise nacional e acredita que outro futuro é possível Neste livro, o professor, político e ativista Marcelo Freixo revela sua trajetória marcada por confrontos com o crime organizado, a corrupção e a violência no Rio de Janeiro. Das negociações tensas dentro de presídios até a investigação do brutal assassinato de Marielle Franco, ex-acessora de seu gabinete político e companheira de lutas, Freixo desvenda os bastidores de uma cidade dominada pelas milícias, pelo tráfico e atingida pelo desgoverno de um Estado em colapso. Com narrativa impactante, ele expõe como o Rio se tornou o laboratório de um modelo político perverso, que hoje se espelha pelo país – especialmente após a ascensão do bolsonarismo. Mas também aponta um caminho: Se foi no Rio que essa máquina de destruição nasceu, é de lá que pode surgir a resistência capaz de mudar o Brasil.', 65.17, 65.17, NULL, 'Books & Magazines > Books > Politics, Law & Social Sciences', 'https://cf.shopee.com.br/file/sg-11134201-823ox-moinfwaonj0v19', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F368398259%2F57910922059', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
