INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '45802613491', 'Jujutsu Kaisen - O Caminho espinhoso ao amanhecer', 'Kugisaki foi chamada para ser modelo no meio da cidade. Porém, o homem que fez isso era um mestre das maldições que queria se aproximar dela por um objetivo! Inumaki foi ao resgate de Kugisaki, mas...?! Além disso, contém também, uma missão solo de Mekamaru, um encontro de bebedeira de Gojou com amigos e mais duas histórias inéditas!', 53.73, 53.73, NULL, 'Books & Magazines > Books > Comics & Manga', 'https://cf.shopee.com.br/file/sg-11134201-8225g-mhul6nniwbgo85', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F368398259%2F45802613491', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
