INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '28582948135', 'Cute & Comfy Super Extra Edição 04 - Livro de Colorir Adulto - Capa Dura Holográfica', 'Cute &amp Comfy Super Extra – Seu momento de relaxamento e criatividade! Se você ama momentos relaxantes e adora colorir, o Cute &amp Comfy Super Extra é a escolha perfeita! Febre do TikTok, este livro traz 40 ilustrações encantadoras, prontas para ganhar vida com suas cores, transformando cada página em uma experiência única e prazerosa. ?Por que você vai se apaixonar? ? 40 ilustrações exclusivas – Desenhos feitos à mão, esperando por sua criatividade.? Traços amplos e fáceis de preencher – Perfeito para um colorir relaxante e sem complicações.? Formato compacto (22,0 x 16,0 cm) – Leve para onde quiser e divirta-se em qualquer lugar.? Encadernação espiral Wire-O – Páginas que se abrem totalmente, garantindo mais conforto ao colorir.? Impressão de alta qualidade – Linhas nítidas e detalhadas para um acabamento impecável.? Acabamento de luxo – Capa dura com um deslumbrante efeito holográfico.? Acompanha uma folha de acetato – Para proteger suas artes e facilitar a pintura. Presenteie-se ou surpreenda alguém especial com um livro que transforma o simples ato de colorir em um verdadeiro momento de terapia e bem-estar. Relaxe, solte a criatividade e aproveite cada página!', 69.11, 69.11, NULL, 'Books & Magazines > Books > Arts, Design & Photography', 'https://cf.shopee.com.br/file/sg-11134201-7reqe-m8f9fzfxyp4wa8', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F368398259%2F28582948135', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '42454161104', 'Vampeerz Vol. 02 - Grupo Editorial JBC', 'Aria continua participando da vida de Ichika como se nada estivesse acontecendo. Com a vampira sempre por perto, Ichika começa a se sentir cada vez mais atraída por sua nova amiga. Além disso, Aria começa a frequentar a escola de Ichika, conhecendo suas colegas e até mesmo interagindo com "uma nova professora", que não passa de outra vampira devotada a ajudar Aria em tudo que ela necessita. Entre novas amizades, um certo teste de coragem e até mesmo a possibilidade de enfrentar inimigos do passado, Aria e Ichika se aproximam o bastante para que a jovem humana crie coragem e tente, enfim, alcançar o seu primeiro beijo!', 40.35, 40.35, NULL, 'Books & Magazines > Books > Comics & Manga', 'https://cf.shopee.com.br/file/sg-11134201-7rat8-mav8shvhr8j72e', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F368398259%2F42454161104', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
