INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '23793470753', 'Alfaparf Real Rigen Repair - Shampoo Reparador 1L', 'Alfaparf Real Rigen Repair - Shampoo Reparador 1000ml Shampoo reparador formulado para cabelos danificados, proporcionando limpeza e nutrição profunda. A nova geração da clássica linha Alfaparf Milano apresenta uma fórmula vegana, ideal para o uso diário. Modo de Uso:Aplique o shampoo nos cabelos úmidos, massageie suavemente e enxágue. Se necessário, repita a aplicação. Para potencializar os resultados, complete o tratamento com o Real Rigen Condicionador Reparador e, dependendo das necessidades do cabelo, utilize também a Real Rigen Máscara Condicionadora Reparadora.', 275.8, 275.8, NULL, 'Beauty > Hair Care > Hair Treatment', 'https://cf.shopee.com.br/file/sg-11134201-7rdvn-m1ivdudp2kdaa6', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F361729924%2F23793470753', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
