INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '22394856876', 'Regata Viés Colorido Preta Microfibra', 'Regata Viés Colorido Preta | Estilo e Frescor Conforto e versatilidade em uma peça atemporal! Descubra a regata que combina leveza e um toque de cor para elevar seus treinos e looks casuais. A Regata Viés Colorido Preta da Donna Carioca é a escolha ideal para quem busca uma peça fresca e estilosa. Seu tecido leve é perfeito tanto para treinos ao ar livre, como beach tennis, quanto para ambientes fechados, como academias e boxes de crossfit, proporcionando conforto e liberdade em qualquer situação. Tecnologia Premium Detalhes Exclusivos Viés em Cor Organic - O detalhe contrastante que oferece um charme único. Logo Donna Carioca - Exclusividade e autenticidade na parte de trás. Modelagem Nadador - Liberdade total de movimentos. Cor Preta Atemporal - Versatilidade para todas as combinações. Prático e estiloso Seja para uma partida de beach tennis, um treino intenso na academia ou para os compromissos do dia a dia, esta regata é a companhia perfeita. O design minimalista com o toque de cor do viés permite inúmeras combinações, trazendo um ar moderno e despojado ao seu visual. COMPRE AGORA - A peça básica que traz elegância e versatilidade ao seu guarda-roupa!', 86.56, 86.56, NULL, 'Sports & Outdoors > Sports & Outdoor Apparels > T-shirts', 'https://cf.shopee.com.br/file/sg-11134201-8261n-mk2dkfi7jugya6', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1576910750%2F22394856876', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '17872135288', 'Celebração da Disciplina | Richard Foster', 'Celebração da Disciplina O Caminho do Crescimento Espiritual EDIÇÃO ESPECIAL 30 ANOS DE ANIVERSÁRIO Mais de 1 milhão de exemplares vendidos em todo o mundo DISCIPLINAS ESPIRITUAIS PORTA DE ENTRADA PARA A LIBERDADE Poucos livros sobre espiritualidade combinam verdadeira originalidade com integridade intelectual Entretanto foi exatamente essa a combinação que Richard Foster conseguiu produzir Impregnado pelos clássicos devocionais o autor apresenta nos um estudo cuidadoso que será apreciado ainda por muito tempo Classificando as disciplinas em três movimentos do Espírito Santo o autor mostra como cada uma delas contribui para uma vida espiritual equilibrada As disciplinas interiores levam os famintos de Deus a uma transformação genuína As disciplinas exteriores são um reflexo das prioridades do Reino de Deus em seus filhos As disciplinas comunitárias lembram nos de que é na comunhão entre os cristãos que nos aproximamos mais de Deus A presente edição comemora o aniversário de 30 anos de sua primeira publicação em 1978 Um clássico aclamado pela revista Christianity Today como um dos dez livros cristãos mais importantes do século XX Desde seu lançamento este livro ajudou milhões de pessoas a descobrirem a porta de entrada para uma vida espiritual rica plena de contentamento paz e profunda compreensão de Deus Richard Foster é autor renomado de vários best sellers teólogo professor na Friends University e pastor da Evangelical Friends Churches Fundador da RENOVARÉ uma organização cristã voltada para a renovação da igreja Mora em Denver Colorado EUA Título Celebração da Disciplina Subtitulo O Caminho do Crescimento Espiritual Autor Richard Foster Páginas 304 Formato 21 x 14 x 1 cm Peso 0 428 kg ISBN 9788538300151 Editora Vida', 47.71, 47.71, NULL, 'Books & Magazines > Books > Religion & Philosophy', 'https://cf.shopee.com.br/file/1626f793ec3488c80ccbc5cb6ddfa7fe', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F400905650%2F17872135288', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '40461763733', 'Bíblia Sagrada | King James | Sola Scriptura', 'Bíblia Sagrada Sola Scriptura | King James | Letra Normal | Capa BrochuraBíblia Sagrada King James Clássica – Edição Exclusiva Plenitude Distribuidora A Plenitude Distribuidora apresenta a Bíblia Sagrada King James Clássica, uma obra que combina tradição, elegância e funcionalidade. Com capa brochura e orelhas, esta edição oferece uma experiência de leitura única, destacando-se pelo design exclusivo desenvolvido pela nossa equipe de marketing, que valoriza a profundidade e a beleza das Escrituras. Disponível apenas através da Plenitude Distribuidora, esta Bíblia é um item essencial para colecionadores e fiéis. Pensada para o conforto do leitor, a edição traz letra normal, facilitando a leitura prolongada, e um design refinado que a torna a companheira ideal para estudo e meditação. Destaque especial para o Plano de Leitura da Bíblia em um Ano, um recurso valioso para quem deseja aprofundar-se na Palavra de Deus de maneira organizada e consistente. Garanta já a sua Bíblia King James Clássica – uma edição exclusiva, feita para inspirar e elevar sua jornada espiritual. Qualidade e devoção em cada página. Especificações Técnicas: Título:Bíblia Sagrada Sola Scriptura | King James | Letra Normal | Capa BrochuraLinguagem:King JamesCapa:BrochuraAcabamento:Laminação BrilhosaBorda:NeutraÍndice:NãoHarpa:NãoPalavras de Jesus em destaque:NãoLetra:NormalFitilho:NãoPáginas:992Dimensões:20,5 x 13,5 x 4 cmPeso:0,600 kgISBN:9786583509369Editora:Plenitude Distribuidora', 21.9, 18.62, NULL, 'Books & Magazines > Books > Religion & Philosophy', 'https://cf.shopee.com.br/file/sg-11134201-824ii-mpjk3ap4fkzm33', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F400905650%2F40461763733', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '41359455220', 'Bíblia Pastoral | Letra Normal | Capa Dura Jardim | Edição Católica', 'Bíblia Pastoral | Letra Normal | Capa Dura Jardim | Edição Católica A Bíblia Pastoral é uma das versões mais procuradas por líderes cristãos, missionários, agentes de pastoral e leitores que buscam uma Bíblia com linguagem acessível, notas explicativas e forte ênfase em justiça social e vida comunitária. Essa edição foi traduzida diretamente dos idiomas originais (hebraico, aramaico e grego) por uma equipe de biblistas comprometida com a fidelidade ao texto bíblico e com a missão evangelizadora da Igreja. Sua proposta é unir fé, prática e transformação da realidade. Por que escolher a Bíblia Pastoral? Linguagem clara e atualizada, fácil de entender para todos os públicos Notas de rodapé e introduções que explicam o contexto histórico, cultural e espiritual de cada livro Destaque para temas como missão, comunidade, justiça, dignidade humana e fé prática Excelente recurso para células, pequenos grupos, EBDs e estudos bíblicos Amada por quem atua em pastorais, projetos sociais, igrejas e movimentos populares Edição com recursos gráficos, mapas e quadros temáticos para facilitar a leitura e o ensino Para quem é esta Bíblia? A Bíblia Pastoral é ideal para: Pastores e agentes de pastoral Evangelistas e missionários Professores de escola bíblica Líderes comunitários e coordenadores de grupos de base Cristãos que desejam aprofundar sua fé com compromisso social Especificações da Bíblia: Título: Bíblia Pastoral | Letra Normal | Capa Dura Jardim | Edição Católica Capa: Jardim Acabamento: Capa Dura Borda: Creme Índice: Não Harpa: Não Palavras de Jesus em destaque: Não Letra: Normal Fitilho: Sim Páginas: 1552 Dimensões: 14 x 21,5 x 3,5 cm Peso: 0.782 kg ISBN: 7898680401421 Editora: O Verso da Vida', 95.79, 95.79, NULL, 'Books & Magazines > Books > Religion & Philosophy', 'https://cf.shopee.com.br/file/sg-11134201-824i4-mfmzlmama0p8f1', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F400905650%2F41359455220', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '23697475469', 'Conjunto Quarto Cama Solteiro com Colchão/Guarda-Roupas/Escrivaninha Multimóveis MP4225', 'O Conjunto Quarto Cama Solteiro com Colchão/Guarda-Roupas/Escrivaninha Multimóveis MP4225 é ideal para criar um design moderno em seu ambiente. Produzidos em MDP com acabamento acetinado (cerca de 20% de brilho), a escrivaninha possui uma gaveta com corrediças metálicas (mais leveza no manuseio), 3 prateleiras para manter o seu ambiente organizado e um tampo espaçoso para equipamentos e materiais de trabalho (suporta até 17 Kg). Já a Cama de solteiro com guarda-roupas embutido pode ser montado de ambos os lados (com a porta do lado direito ou esquerdo). Possui módulo aéreo com amplo espaço e uma porta lateral, com cabideiro (em madeira) e 3 prateleiras com espaço bem dividido para organizar seus pertences. A cama suporta até 90kg e acompanha colchão D23 com tratamento antiácaro e antialérgico que proporcionam noites de sono mais tranquilas e saudáveis. Conteúdo da Embalagem: 1 (uma) Escrivaninha 1 (uma) Cama com Guarda-Roupas 1 (um) Colchão Kit Ferragem Manual de Montagem Dimensões do produto montado: Escrivaninha - Altura: 106cm | Largura: 149cm | Profundidade: 48cm Cama com Guarda-Roupas - Altura: 183cm | Largura: 244,5cm | Profundidade: 95cm Colchão - Altura: 12cm | Largura: 188cm | Profundidade: 78cm *Você pode consultar as medidas detalhadas na imagem técnica do produto. *Obrigatório fixar o guarda roupa na parede. As cores do produto podem sofrer variações de tonalidade de acordo com as configurações do seu dispositivo. Imagem meramente ilustrativa. Decoração não acompanha o produto. O produto será entregue desmontado e não disponibilizamos o serviço de montagem.', 2499.9, 1799.99, NULL, 'Home & Living > Furniture > Bed Frames & Headboards', 'https://cf.shopee.com.br/file/sg-11134201-7rfid-m9hrcf28oxq84c', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F308628919%2F23697475469', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '21164299449', 'Rack Estante com Painel TV 65" e 2 portas Oslo Multimóveis Madeirado/Preto', 'Uma sala de estar moderna, aconchegante e linda para receber os amigos e curtir os melhores filmes e séries. O Rack Estante com Painel TV 65" e 2 portas Oslo Multimóveis é perfeito para você deixar seu ambiente organizado e muito bem decorado. Produzido em MDP, que garante maior durabilidade e facilidade na limpeza, além de um acabamento superior, possui 2 portas articuladas com um excelente espaço interno para organizar seus pertences. Com prateleiras para que você possa personalizar a decoração, deixando-a do seu estilo e nichos para acomodar todos os equipamentos, o painel para TV de até 65” (suporta até 30kg) possui espaçamento para passagem dos fios, que permite deixar os cabos mais organizados. Conteúdo da Embalagem: 1 (uma) estante Dimensões do produto montado: Altura: 171cm | Largura: 213cm | Profundidade: 38cm Painel - Altura: 98cm | Largura: 150cm *Devido as variações de tamanho dos televisores no mercado, sugerimos que verifique as medidas da sua TV e compare com o painel antes de efetuar a compra. *Você pode consultar as medidas internas na imagem técnica do produto. *As cores do produto podem sofrer variações de tonalidade de acordo com as configurações do seu dispositivo. Imagem meramente ilustrativa. Decoração e eletros não acompanham o produto. O produto será entregue desmontado e a Multimóveis não disponibiliza o serviço de montagem.', 1009.99, 839.99, NULL, 'Home & Living > Furniture > Shelves & Racks', 'https://cf.shopee.com.br/file/sg-11134201-22100-d7acztdw24ived', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F308628919%2F21164299449', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '23707259960', 'Armário de Cozinha Completa de Canto com Rodapé Veneza Multimóveis MP2103.895 Preto', 'A Cozinha Completa de Canto com Rodapé Veneza Multimóveis MP2103 com Armário e Balcão tem um excelente custo benefício e um amplo espaço interno. Produzida em MDP com acabamento acetinado (cerca de 20% de brilho), que garante maior durabilidade e resistência, possui corrediças metálicas (mais leveza no manuseio), rodapés, que deixam o ambiente mais estiloso, puxadores em ABS e tampo em MDP 15mm com pintura de alta resistência. Os módulos de canto podem ser montados dos dois lados (esquerdo ou direito), conforme a sua preferência. Esta cozinha conta, ainda, com balcão com tampo removível (compatível com pia de 120 ou 150 cm). Os módulos são individuais e você pode montar da maneira que se adaptar melhor ao seu ambiente. Conteúdo da Embalagem: 1 (um) armário aéreo 120cm 1 (um) armário aéreo de canto 90cm 1 (um) armário aéreo 150cm 1 (um) armário aéreo 70cm 1 (um) balcão com tampo 120cm 1 (um) balcão com tampo de canto 90cm 1 (um) balcão com tampo 150cm 1 (um) kit com rodapés Dimensões do produto montado: Altura: 203cm | Largura: 210 x 272cm | Profundidade: 32cm (aéreos) - 53cm (balcão com tampo) *Você pode consultar as medidas internas na imagem técnica do produto. *As cores do produto podem sofrer variações de tonalidade de acordo com as configurações do seu dispositivo. Imagem meramente ilustrativa. Decoração e eletros não acompanham o produto. O produto será entregue desmontado e não disponibilizamos o serviço de montagem.', 3529.9, 2599.99, NULL, 'Home & Living > Furniture > Cupboards & Cabinets', 'https://cf.shopee.com.br/file/sg-11134201-7qvcu-li0huf8mc38t56', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F308628919%2F23707259960', NULL, NU