INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '23997324091', '10~50 Caixa Azul Textura com Visor S21 15x15x4cm ASSK CAIXA DIA DOS PAIS (CHOCO)', 'Caixa com Visor S21 (15x15x4cm) - ASSK - A Caixa com Visor é ideal para expor seus produtos, para que fiquem visíveis a quem comprar ou receber. Com visor transparente, você pode decorar docinhos, bombons, mini trufas, pães de mel, peças de artesanato para que fiquem encantadoras na Caixa com Visor. Use e abuse de sua criatividade. Amarre uma fita bem bonita, amarre um laço e presenteie ou faça suas encomendas com muito mais estilo. Medidas Aproximadas: Comprimento -> 15cm x Largura -> 15cm x Altura -> 4cm. Características: Base de Papel e Tampa com Visor Transparente. ATENÇÃO: - Quantidade no título do anúncio. - Confira o prazo de envio no ato da compra. - Caso ocorra algum problema com a compra entre em contato com nossos canais de comunicação. - A CAIXA VAI DESMONTADA PARA PRESERVAÇÃO DO PRODUTO.', 32.85, 32.85, NULL, 'Stationery > Gift & Wrapping > Gift Boxes', 'https://cf.shopee.com.br/file/br-11134207-7r98o-lweomqxwlymqbe', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F455834389%2F23997324091', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
