INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '18498930056', 'Par Palheta Limpador Parabrisa Dianteiro New Fiesta 2011 2012 2013 2014 2015 2016 2017 2018 2019', '🚗 Par Palheta Limpador de Para-brisa Dianteiro Mantenha a visibilidade do seu carro sempre perfeita! 🌧️✨ Este par de palhetas dianteiras foi desenvolvido para garantir limpeza eficiente, silenciosa e sem falhas, proporcionando mais segurança ao dirigir. ✅ Compatível com: 🚘 Ford New Fiesta Hatch e Sedan 📅 Ano 2011 a 2019 📦 Conteúdo da embalagem ✔️ 1 Palheta dianteira lado motorista 26 polegadas ✔️ 1 Palheta dianteira lado passageiro 15 polegadas ⭐ Benefícios 🔹 Limpeza uniforme do para-brisa 🔹 Maior visibilidade em dias de chuva 🔹 Funcionamento silencioso 🔹 Alta durabilidade 🔹 Encaixe perfeito 🔹 Instalação rápida e fácil 🛡️ Segurança e conforto Palhetas desgastadas podem causar falhas na limpeza e riscos no vidro. Troque suas palhetas e tenha uma condução muito mais segura! 📦 Produto novo ⚡ Envio rápido 🔧 Instalação simples 🔒 Garantia contra defeito de fabricação', 52.47, 34.49, NULL, 'Spare Parts and Accessories for Vehicles > Spare Parts for Automobiles > External Parts', 'https://cf.shopee.com.br/file/sg-11134201-7rbm5-ll73z3fk18vp2f', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F357432948%2F18498930056', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '22894061214', 'Conjunto Balcões Miami Loft Carraro Freijó', 'O Conjunto Miami Loft é uma modulação cheia de conceito integrando muitas prateleiras e espaços para organização. Traz a modernidade do estilo industrial novaiorquino, fazendo a sua área gourmet ser o centro das atenções. Especificações da modulação: Medidas totais: Largura: 320 cm | Altura: 220 cm | Profundidade: 50 cm Peso total: 152 Kg Material do produto: MDP Informações importantes: - O produto é enviado desmontado; - Acompanha manual com instruções para a montagem; - Acompanha manual com recomendações para a limpeza e conservação do produto; - A empresa Móveis Carraro não realiza o serviço de montagem; - Nenhum objeto decorativo acompanha o produto; - As cores da imagem podem sofrer variações de acordo com o monitor, iluminação do ambiente e percepção visual comparado ao ambiente residencial. Desta forma, as imagens são meramente ilustrativas; - Não é possível realizar a entrega na parte interna da residência ou condomínio e é necessário ter alguém no endereço fornecido para o recebimento da entrega. Garantia: - O produto e seus componentes possuem garantia contra defeitos de fabricação com validade de 03 meses (usado em condições normais). Esta garantia não cobre defeitos por uso inadequado ou abusivo, falta de cuidados e desbotamento natural dos revestimentos. Condições de perda da garantia: - Mau uso ou manuseio incorreto; - Desbotamento causado pela exposição direta da luz solar; - Danos causados por agentes da natureza, como inundações ou acidentes de qualquer espécie; - Uso indevido de produtos abrasivos para realizar a limpeza; - Passado o período de 03 meses. Perguntas frequentes: - Existem outras cores disponíveis? Sim, este produto possui outras cores disponíveis em outros anúncios. - Vocês entregam para todas as regiões do Brasil? Sim, entregamos para todas as regiões do Brasil. A entrega é realizada por transportadoras parceiras e é feita no endereço fornecido pelo cliente no momento da compra. - Este produto é novo? Todos os nossos produtos são novos e acompanham nota fiscal e certificado de garantia.', 1999.99, 1304.33, NULL, 'Home & Living > Furniture > Cupboards & Cabinets', 'https://cf.shopee.com.br/file/sg-11134201-7rata-maij2yrkygsw58', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F952014476%2F22894061214', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
