INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '23297473961', 'UMA FAMILIA FELIZ - CIA DAS LETRAS', 'Em Uma família feliz, o mestre do suspense Raphael Montes desbrava as tensões das relações familiares e do mundo de aparências de um condomínio perfeito, em uma trama complexa sobre infância e maternidade. Do criador da série original Bom dia, Verônica (Netflix) e da novela Beleza fatal (HBO). Eva tem a vida perfeita. Seu marido é um jovem advogado em ascensão. Suas filhas gêmeas são lindas, inteligentes e saudáveis. Seu trabalho, a arte reborn, é um sucesso na internet. À sua volta, tudo está à mão: o Blue Paradise, condomínio fechado de classe média-alta na Barra da Tijuca, oferece todo tipo de serviço para que ela não precise sair do conforto de seu lar. Eva tem a vida perfeita ― até descobrir que está grávida e seu mundo virar de cabeça para baixo.Conhecido por seus suspenses de tirar o fôlego, com mais de 500 mil exemplares vendidos, Raphael Montes inova ao começar este thriller psicológico pelo último capítulo. Assim, como uma bomba-relógio prestes a detonar, acompanhamos os caminhos surpreendentes e as tensões que levam essa família feliz a um final avassalador. Uma história original de Raphael Montes deu origem ao livro e ao longa-metragem Uma família feliz , com Grazi Massafera e Reynaldo Gianecchini e direção de José Eduardo Belmonte. “Um thriller que coloca o dedo na ferida das famílias idealizadas.” ― Vera Iaconelli “Um suspense arrebatador! Eva é uma personagem complexa, vive no fio da navalha sob expectativas sociais tentando equilibrar as exigências da maternidade e as pressões de uma vida de aparências. Sem dúvida, muitas mulheres vão se identificar. Essa história me arrepiou desde o primeiro momento!” ― Grazi Massafera', 62.9, 62.9, NULL, 'Books & Magazines > Books > Fantasy', 'https://cf.shopee.com.br/file/sg-11134201-824i2-mfijsdprmscv8d', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F303956123%2F23297473961', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '22794176593', 'Limpa Bicos Gasolina – 200ml – Sieger SC130', 'O SC130 da Sieger é um poderoso limpador de bicos e sistema de injeção para motores a gasolina. Com tecnologia Clean UP, remove resíduos de carbono, vernizes e outras impurezas que comprometem o desempenho do motor. Ideal para quem busca economia de combustível, redução de emissões e resposta imediata no funcionamento do motor. Principais benefícios - Melhora o desempenho e a resposta do motor - Economiza combustível - Reduz a emissão de CO² - Alto poder de limpeza sem formação de borra - Limpa bicos, válvulas, câmara de combustão e sistema de alimentação Indicação de uso - Veículos a gasolina com perda de rendimento ou consumo elevado - Ideal após longos períodos sem manutenção preventiva - Pode ser usado antes do aditivo de uso contínuo Modo de uso Adicione 200ml diretamente no tanque com até 50 litros de gasolina. Caso o tanque esteja com menos combustível, complete após aplicar o produto. Dicas Reaplicar a cada 5 mil km rodados ou a cada 6 meses. Dados técnicos Composição: Hidrocarboneto alifático, aditivo e corante Densidade: 0,758 g/ml Conteúdo: 153g Cor: levemente alaranjada Fragrância: característica Armazenamento Guardar em local seco, coberto e longe de fontes de calor. Não expor a temperaturas acima de 50 °C.', 49.9, 32.75, NULL, 'Spare Parts and Accessories for Vehicles > Vehicular Care > Degreasers', 'https://cf.shopee.com.br/file/br-11134211-7r98o-mbfl7p9m4dbsdc', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1449962409%2F22794176593', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
