INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '22193273448', 'Liquidificador Philco PLQ2100PI 12 vel + Turbo 1400W 3,0L', 'Ideal para preparar diversos tipos de alimentos! O liquidificador philco plq2100pi 12 velocidades + Função Ice + Função Pulsar + Função Autolimpeza, prepara vitaminas molhos sopas cremosas e muito mais. Suas lâminas ultra afiadas trituram e misturam com grande eficiência desde alimentos a gelo. são 12 diferentes velocidades para você encontrar a que mais se adapta ao seu preparo. Além da função pulsar que ajuda a controlar o nível de trituração do preparo e auxiliar na limpeza com função auto limpeza para não precisar esfregar copo. MODELO: PLQ2100 Velocidades: 12+ função ice + função pulsar + função autolimpeza Filtro Sobretampa dosadora tipo xícara Faca 6 lâminas Copo de plástico com capacidade total 3,0L e útil de 2,0L Tampa com alça na lateral para retirada Base antiderrapante Embutidor de cordão Potência de 1400w Dimensões do produto: Altura: 45 cm Largura: 21,5 cm Profundidade; 22,2 cm Peso: 2,286 kg Garantia: 12 meses', 319.9, 319.9, NULL, 'Home Appliances > Small Household Appliances > Others', 'https://cf.shopee.com.br/file/sg-11134201-7rdxn-lzt587slafdmac', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1243712796%2F22193273448', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '58260126947', 'Leite UHT Integral Porto Alegre', 'O Leite Porto Alegre Integral possui 3% de gordura, é fonte de cálcio e nutritivo. Qualidade e sabor do dia a dia para você e sua família. Ideal para o consumo diário, puro ou em receitas. Não é necessário ferver este leite. Após aberto, conservar sob refrigeração entre 1ºC e 10ºC, e consumir em até 48 horas.', 5.99, 5.99, NULL, 'Food & Beverages > Dairy & Eggs > Milk', 'https://cf.shopee.com.br/file/sg-11134201-82622-mj72mg8eg93aa9', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1676552986%2F58260126947', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
