INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '22795559656', 'Brinquedo Boneco Articulado de Vinil Atóxico Pateta Baby 16cm +4 meses Líder - 2892', 'Os personagens favoritos das crianças de um jeito que elas nunca viram! Nesta versão baby, o Pateta possui articulações nos braços, pernas e cabeça, proporcionando maior liberdade na hora das brincadeiras e trazendo toda a magia do mundo Disney. Características: - Marca: Líder - Modelo: 2892 *Imagens Meramente Ilustrativas Caracteristicas Principais: - Certificações: CE-BRI/IQB 00275552668 - Material: Vinil Atóxico - Idade Recomendada: + 12 meses - Dimensões Aproximadas: 15x20x16cm Conteúdo da Embalagem: - 1 Boneco Articulado Pateta', 184.0, 184.0, NULL, 'Mom & Baby > Toys > Dolls & Stuffed Toys', 'https://cf.shopee.com.br/file/sg-11134201-7qvg7-lfziu7h7t6c678', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F371036439%2F22795559656', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
