INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '16193331033', 'Calça Pantalona Feminina Fluit Cintura Alta Moda Feminina Estilosa', 'Descubra a Elegância e Conforto da Calça Feminina Pantalona Fluit! 🌟 Eleve seu estilo com nossa Calça Feminina Pantalona Fluit, a escolha perfeita para mulheres que valorizam conforto e sofisticação. Com um caimento fluido que valoriza a silhueta, esta calça é ideal tanto para o dia a dia quanto para ocasiões especiais. A modelo da foto veste o tamanho P, ideal para quem usa manequim 36/38. Confira nossa tabela de tamanhos para garantir o ajuste perfeito: P - Manequim 36/38 M - Manequim 40/42 G - Manequim 44 GG - Manequim 46/48 É importante ressaltar que, por se tratar de uma peça artesanal, a cor e o padrão podem variar levemente, tornando cada calça única! 🎨 Para prolongar a durabilidade do seu produto, recomendamos a lavagem em modo delicado. Assim, você garante que a sua calça Pantalona Fluit mantenha sua beleza e qualidade por muito mais tempo. Composição: 90% Fluit e 10% Elastano – um tecido leve e confortável que se adapta perfeitamente ao corpo e proporciona liberdade de movimentos. Não perca a oportunidade de adicionar esta peça versátil e estilosa ao seu guarda-roupa. Adquira já a sua Calça Feminina Pantalona Fluit e sinta-se linda em qualquer ocasião! 🛍️✨', 59.9, 53.91, NULL, 'Women Clothes > Pants & Leggings > Pants', 'https://cf.shopee.com.br/file/br-11134207-7r98o-mcv1fghte8mq5d', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F336042646%2F16193331033', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
