INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '20174704565', 'Limpador Desengorurante Ajax Squeeze para Cozinha 500ml', 'Agora ficou mais fácil limpar forno, fogão, paredes e outras superfícies com o Ajax desengordurante (vs. outra fórmula do mesmo fabricante) para a cozinha, graças à sua fórmula inovadora que remove a gordura e manchas de comida (testado com leite e molho de tomate em superfícies de aço inoxidável). Experimente o poder do Ajax. Benefícios: Maior poder desengordurante: na comparação com outra fórmula do mesmo fabricante, a fórmula inovadora desse limpador de uso geral remove a gordura e manchas de comida (testado com leite e molho de tomate em superfícies de aço inoxidável). Limpeza sem esforço: este Ajax é o seu melhor aliado para uma cozinha efetivamente limpa com poucos movimentos e sem muito esforço. Facilidade: basta aplicar o limpador de uso geral sobre a superfície e esfregar com uma esponja ou pano úmido para deixá-la limpa e brilhante. Poder total: experimente esse Ajax Cozinha, um limpador de uso geral eficaz contra a gordura que facilita a limpeza.', 18.19, 18.19, NULL, 'Home & Living > Home Care Supplies > Cleaning Agents', 'https://cf.shopee.com.br/file/sg-11134201-7rblb-lopevqwfat9hdb', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F557242410%2F20174704565', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
