INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '42962671308', 'Rabisquinhos para colorir: brigadeiro e paçoca', 'Do perfil de sucesso no TikTok e no Instagram, Rabisquinhos para colorir: Brigadeiro e Paçoca traz as cenas mais fofas do cotidiano brasileiro para você relaxar e exercitar o seu lado artístico. Preparado para um passeio por cenários aconchegantes e cheios de brasilidade? Do açaí ao chimarrão, do churrasco à beira da piscina ao banho de mar, Brigadeiro e Paçoca reúne experiências do cotidiano e momentos de lazer de todo brasileiro para você colorir e se distrair. Cada página contém um cenário diferente para uma experiência de pintura variada e envolvente, garantindo, assim, criações únicas e cheias de personalidade. Sucesso nas redes sociais pelos posts e vídeos bem-humorados, o perfil Rabisquinhos entra para o mundo dos livros de colorir com vinte ilustrações originais repletas de detalhes fofos e traços únicos que vão proporcionar uma prática de relaxamento e diversão. Este é o passatempo perfeito para pessoas de todas as idades expressarem a sua criatividade, se deleitarem com os prazeres do dia a dia e deixarem os rabisquinhos mais famosos da internet com a sua cara. Para uma experiência ainda mais agradável, este livro inclui: 20 ilustrações exclusivas com o verso em branco páginas para você testar cores e texturas papel branquinho e de alta gramatura folha de acetato, para você não se preocupar em manchar as outras ilustrações. A coleção Rabisquinhos para colorir vai proporcionar um mergulho em um Brasil cheio de momentos aconchegantes e personagens divertidos e muito fofos!', 22.0, 22.0, NULL, 'Books & Magazines > Books > Hobbies', 'https://cf.shopee.com.br/file/sg-11134201-7rdyj-mddpz3tnnyv080', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F368398259%2F42962671308', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
