INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '19675566287', 'Livro com Aquarela Patrulha Canina O Novo Amigo da Patrulha', 'Patrulha Canina - O novo amigo da Patrulha A Patrulha Canina recebeu uma visita muito especial dos gansos. Um dos filhotes do bando ficou amigo de Marshall e até ganhou o nome de Felpudo. Pinte as ilustrações dessa história com a aquarela e divirta-se! Dimensões: 28cm x 27cm Coleção: Livro com aquarela Idioma: Português Formato: Livro Encadernação: Grampeado Número de páginas: 16 ISBN: 9788538082521 Editora: Ciranda Cultural', 9.63, 9.63, NULL, 'Books & Magazines > Books > Sticker & Colouring Books', 'https://cf.shopee.com.br/file/br-11134201-23030-mhh26hxnihov12', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F400905650%2F19675566287', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '28886547237', 'Livro Como (não) ser secular | James K. A. Smith', 'Como (não) ser secular UM GUIA PERSPICAZ E INTELIGENTE PARA NAVEGARMOS NA CULTURA ATUAL. "Como (não) ser secular" é o que Jamie Smith chama "o guia do mochileiro do presente" - é tanto um guia de leitura para "Uma era secular" (2007), a obra monumental de Charles Taylor, quanto uma orientação filosófica para aprendermos a viver nestes tempos. O livro de Taylor, que se tornou uma referência intelectual incontornável, apresenta uma análise colossal e incisiva do significado de viver no presente pós-cristão - um mundo pluralista de crenças rivais e de crescente incredulidade. O livro de Smith é um compacto guia de campo que busca tornar o brilhante estudo de Taylor sobre o secularismo - uma obra de extrema relevância porém intimidadora - acessível para um segmento mais amplo de leitores. Ademais, este "Como (não) ser secular" é também um guia filosófico prático, um tipo de manual de instruções para viver em nossa era secular. Em última instância, ele nos oferece uma aventura na compreensão de nós próprios e mapeia uma trilha para orientar-nos na cultura secular de nossos dias, não importa quem "nós" somos - seja crentes ou céticos, piedosos ou pirrônicos, convictos ou perplexos e confusos. Este é um livro para todas as pessoas reflexivas nele meditarem. Título: Como (não) ser secular Autor: James K. A. Smith Capa: Capa Brochura Acabamento: Laminação Soft touch Páginas: 231 Miolo: Papel Pólen soft 80g/m² Dimensões: Altura: 20,7 cm Largura: 13,8 cm Profundidade: 1,3 cm Peso: 0,300 kg ISBN: 9786587860220 Editora: Monergismo', 53.48, 53.48, NULL, 'Books & Magazines > Books > Religion & Philosophy', 'https://cf.shopee.com.br/file/br-11134275-7r98o-m9kriv9kzgopb4', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F400905650%2F28886547237', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
