INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '16808756849', 'Parafusadeira Furadeira 3/8 12v A Bateria Bivolt', 'FURADEIRA PARAFUSADEIRA A BATERIA 12V LÍTIO BIVOLT PB3000 Oz A Parafusadeira/Furadeira OZ PB3000 tem design ergonômico, mandril de 3/8" e luz de LED para iluminação, ideal para alcançar cantos menores e com pouca luz. Conta com rotação (sem carga) de 0-550RPM, velocidade variável e reversível e torque máximo de 19Nm. APLICAÇÕES: - Ideal para perfuração em diversos materiais, como metal, madeira e plástico; - Marcenaria, bricolagem e uso doméstico. FICHA TÉCNICA: - Diâmetro do mandril 3/8” 10mm; - Velocidade variável e reversível; - Rotação sem carga : 0-550 - Empunhadura Soft Grip; - Bateria De Lítio 12V; - Torque: 19N.M; - Tensão: Bivolt ; Acompanha: - Parafusadeira 12V PB300 - 1 Bateria - Manual', 138.0, 99.0, NULL, 'Home & Living > Tools & Home Improvement > Tools', 'https://cf.shopee.com.br/file/sg-11134201-824gk-met28lw84h6v80', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F360012700%2F16808756849', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '41465837023', 'Maquina Inversora Solda 120a 220v Tig Mma + Mini Lixadeira Angular 12v Á Bateria', 'Distribuído Por Ismafer Ferramentas Máquina Inversora de Solda 120A - IF-150 The Black Tools - Esse anúncio acompanha: - Fonte Inversora - Cabo Porta Eletrodo - Alça para transporte CARACTERÍSTICAS: - Solda MMA (Eletrodo) e também TIG, porém não acompanha tocha; - Funções: Hot Start, Ark Force e Anti Stick; - Não solda MIG. DIMENSÕES DOS CABOS: - Cabo de força (tomada): 1,50Mt; 20A. - Porta eletrodo e garra: 1,14Mt. Possui tecnologia moderna e avançada, sendo ideal para serviços de solda em montagens e reparos de estruturas metálicas em geral! - Leve, compacta e de fácil operação! - Intensidades mín: 20A - máx: 120A - Eletrodo: 1,5 à 3,25 - Proteção contra super aquecimento Garantia: 6 Meses + Esmerilhadeira Lixadeira Angular Rebarbadora a Bateria 12V 660W 3 Pol 75mm Com Acessórios BMR120 The Black Tools A Esmerilhadeira Lixadeira Angular Rebarbadora a Bateria de 12V oferece liberdade sem fio e alta potência para seus trabalhos de corte, lixamento e polimento. Com um design ergonômico e compacto, permite maior conforto e controle durante o uso, garantindo um desempenho superior em diversas aplicações. Conta com duas baterias de longa duração e uma maleta para transporte, tornando-a ideal para profissionais e entusiastas que buscam mobilidade e eficiência. VANTAGENS: - Design ergonômico: Minimiza a fadiga durante o uso prolongado; - Liberdade sem fio: Trabalhe sem preocupação com cabos e fios; - Desempenho poderoso: Opera a 12V com 660W de potência; - Alta velocidade: Alcança 5000 rpm para maior eficiência. IDEAL PARA: - Cortes rápidos e precisos em metais e outros materiais; - Trabalhos de acabamento, lixamento e polimento; - Profissionais da construção e marcenaria; - Uso doméstico e profissional. FICHA TÉCNICA: - Bateria: 12V 2.0Ah (2 unidades inclusas); - Velocidade sem bloqueio: 5000 rpm; - Modelo: Lixadeira Angular 12V; - Diâmetro do disco: 75mm; - Diâmetro do furo: 10mm; - Rosca do eixo: M5; - Potência: 660W. ITENS INCLUSOS: 1x Lixadeira Angular 12V; 2x Baterias 12V; 1x Carregador; 10x Discos de corte - Marca: The Black Tools - Modelo: BMR120 SKU: KIT22067_24881 Distribuído Por Ismafer Ferramentas', 980.0, 499.9, NULL, 'Home & Living > Tools & Home Improvement > Tools', 'https://cf.shopee.com.br/file/sg-11134201-824j1-mees2fuesumfcd', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F360012700%2F41465837023', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '12907632917', 'Baqueta Tripla Plástico Para Tamborim Instrumentos Percussão', 'A LUEN é uma empresa fabricante de peles, instrumentos de percussão e acessórios musicais que já vem atuando no mercado brasileiro à bastante tempo. O tamborim é um instrumento de percussão muito popular no samba. O instrumentista o percute com uma ou mais baquetas. A Baqueta de Ponta Tripla PP da Luen oferece um som limpo e estalado, ideal para iniciantes. Ela é constituída por cabo e três hastes paralelas. Especificações: Indicação: Tamborim; Instrumentos Percussão Ponta: Tripla Modelo: PP Comprimento: 35,3 cm Material: Polipropileno Peso: 25g Contém: 01 Baqueta *Imagens Ilustrativas **Não contém nenhum instrumento no anúncio', 9.5, 9.5, NULL, 'Hobbies & Collections > Musical Instruments & Accessories > Music Accessories', 'https://cf.shopee.com.br/file/d4e790cd2ed4ed7ec30d610940eff040', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F442397041%2F12907632917', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
