INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '22098693104', 'Cooler para Notebook Asus X515JF-EJ153T | Interno', 'Cooler para Notebook compatível com Asus X515JF-EJ153T | Interno Este é um Cooler bringIT compatível com Asus X515JF-EJ153T. Os coolers para notebook da bringIT são a solução definitiva para possíveis problemas de ventilação e resfriamento do seu equipamento. Também conhecidos como “fans”, “ventiladores” ou “resfriadores”, os coolers são responsáveis pela retirada do máximo de calor gerado pelo processador e por outros componentes eletrônicos. Para evitar problemas de compatibilidade, compare as fotos deste anuncio com seu equipamento original. Assim você consegue verificar as principais informações de compatibilidade e demais especificações do seu cooler. Informações Técnicas Quantidade de vias: 4 vias Tensão (Voltagem): 5V Corrente (Amperagem): 0.5A Garantia: 3 meses de garantia contra defeitos de fabricação Referência: CL231', 83.9, 35.79, NULL, 'Computers & Accessories > Desktop & Laptop Components > Fans & Heatsinks', 'https://cf.shopee.com.br/file/sg-11134201-7ra2c-mbfq2z7a4z3bad', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F801641954%2F22098693104', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '23499434199', 'Cooler Compativel Notebook Dell Latitude 3410 3510 E3510', 'Cooler compatível com Dell Latitude 3410 3510 E3510 Interno Este é um Cooler bringIT compatível com o notebook Dell Latitude 3410 3510 E3510. Os coolers para notebook da bringIT são a solução definitiva para possíveis problemas de ventilação e resfriamento do seu equipamento. Também conhecidos como “fans”, “ventiladores” ou “resfriadores”, os coolers são responsáveis pela retirada do máximo de calor gerado pelo processador e por outros componentes eletrônicos. Para evitar problemas de compatibilidade, compare as fotos deste anuncio com seu equipamento original. Assim você consegue verificar as principais informações de compatibilidade e demais especificações do seu cooler. Atenção: Esse é um cooler bringIT, portanto não é um produto original da fabricante Dell. Caso seja necessário, todo o suporte e garantia do produto serão oferecidos pela nossa equipe. Informações Técnicas Quantidade de vias: 4 vias Corrente (Amperagem): 0.4A Tensão (Voltagem): 5V Garantia: 3 meses de garantia contra defeitos de fabricação Referência: CL220-DE-0008', 114.9, 109.16, NULL, 'Computers & Accessories > Desktop & Laptop Components > Fans & Heatsinks', 'https://cf.shopee.com.br/file/sg-11134201-8259c-mqthw77voqod4f', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F801641954%2F23499434199', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '23298130852', 'Basike Fone De Ouvido Bluetooth Sem Fio, bluetooth earphone original, fone de ouvido iphone fon141', '👑 Bem-vindo à loja oficial Basike. Todos os produtos na loja são produtos originais Basike 🚚Em rela ção à entrega, iremos entregar entre 12 horas após a colocação do pedido ✨Sua satisfa ção é a nossa prioridade e a avaliação de 5 estrelas é aparecida 💢Dever-se notar que quaisque problemas de produto exigem um vídeo de unboxing para ser apresentado ✅【BLUETOOTH AVANÇADO 5.4 E CONEXÃO AUTOMÁTICA】Os fones de ouvido sem fio contam com tecnologia Bluetooth 5.4 avançada, oferecendo velocidade de transmissão 3 vezes mais rápida, conexão estável, baixo consumo de energia e áudio com latência ultrabaixa. ✅【SOM ESTÉREO IMERSIVO】Equipados com drivers de diafragma duplo de 18,2 mm e decodificação de áudio AAC/SBC em alta resolução, os fones reproduzem graves potentes, médios claros e agudos brilhantes. ✅【BATERIA DE ATÉ 60 HORAS】Com carga rápida via USB-C, os fones carregam totalmente em 2 horas e oferecem até 11 horas de reprodução contínua. O estojo de carregamento estende a autonomia para 60 horas, garantindo uso por até 28 dias sem recargas frequentes. ✅【DESIGN ERGONÔMICO E RESISTÊNCIA IPX5】O gancho esportivo de 45°, ultraleve e flexível, adapta-se confortavelmente aos ouvidos (apenas 10g por unidade). A proteção IPX5 resiste a suor e chuva, ideal para atividades físicas ou uso diário. ✅【CONTROLE POR TOQUE E DESIGN PREMIUM】Toques intuitivos nos fones controlam reprodução, volume, chamadas e assistentes virtuais (Siri/Google). O acabamento brilhante e linhas suaves garantem um visual elegante e toque agradável. ✨Introdução do produto: Carregamento do compartimento em tempo integral: 2H Tensão/corrente de entrada do estojo de carregamento: 5 V = 1 A Especificação da bateria do fone de ouvido: 65mAh Especificação da bateria da caixa de carregamento: 500mAh Tempo de espera (conectado): 40 ±10H Tempo de música: 7,5 ±0,5H Distância de conexão: 15 ±1M ✨O que tem na caixa? Fones de ouvido*1 Cabo de carregamento*1 Manual de instruções*1 ✨Instruções de segurança 1. Mantenha o produto longe de ambientes extremamente quentes ou frios, pois isso danificará a bateria e o circuito. 2. Evite mergulhar o produto em líquidos. 3. Não desmonte o produto. 4. Não utilize produtos químicos ou detergentes concentrados para limpar o produto. 5. Use apenas fonte de alimentação de 5 V/1 A. Conectar uma tensão de alimentação muito alta pode causar danos graves. 6. Não descarte o produto a qualquer momento nem o coloque perto do fogo ou de altas temperaturas para evitar risco de explosão.', 289.0, 166.99, NULL, 'Audio > Earphones, Headphones & Headsets', 'https://cf.shopee.com.br/file/br-11134207-7r98o-m8bt3q5krwnl03', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1371911195%2F23298130852', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
