INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '58203188336', 'Kit Refresco em Pó MID® Sabor Jabuticaba Com 5 Unidades de 20g', 'Kit Refresco em Pó MID® Sabor Jabuticaba – 5 Unidades de 20g O Kit MID® Jabuticaba traz toda a praticidade e o sabor refrescante da fruta. Com sabor equilibrado e fonte de vitamina C, o MID® é perfeito para quem busca uma bebida saborosa, econômica e ideal para compartilhar com toda a família. Com o sabor clássico do Jabuticaba, o refresco dissolve com facilidade e rende muito, sendo excelente para o dia a dia. Rápido de preparar, oferece uma bebida refrescante em instantes — ótimo para lanches, refeições e momentos em família. Diferenciais do produto - Sabor autêntico de Jabuticaba - Adoçado na medida certa - Fonte de vitamina C - Fácil de preparar — basta adicionar água - Rende muito e é ideal para toda a família - Perfeito para consumo diário ou ocasiões especiais Como usar Basta adicionar o conteúdo do sachê em água na proporção desejada, misturar até dissolver e servir. Pode ser consumido gelado ou conforme sua preferência. Onde usar Refeições do dia a dia Lanches em família Festas, churrascos e encontros Para levar em viagens ou deixar sempre disponível em casa Composição do kit 5 unidades do Refresco em Pó MID® Sabor Jabuticaba — 20g cada. Conteúdo REFRESCO EM PÓ MID® SABOR JABUTICABA 20g — 5 unidades Refresque seus dias com mais sabor, praticidade e aquele toque especial MID® que todo mundo ama.', 8.45, 8.45, NULL, 'Food & Beverages > Beverages > Powdered Drink Mixes', 'https://cf.shopee.com.br/file/sg-11134201-82623-mjflnhcki70ice', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1598062483%2F58203188336', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
