INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '58256755919', 'Blusa Feminina Recorte Na Costa Infinita Cor Rosa', 'A Blusa Feminina Recorte na Costa Infinita Cor é uma peça moderna e versátil para o dia a dia. Confeccionada em 100% poliéster, oferece leveza, caimento confortável e praticidade no uso. O modelo possui gola redonda com friso e leve queda de manga, proporcionando um visual delicado. O destaque fica por conta do recorte nas costas, que traz um toque de estilo e diferenciação à peça, tornando-a ideal para compor looks casuais com elegância e conforto.', 59.99, 59.99, NULL, 'Women Clothes > Tops > T-shirts', 'https://cf.shopee.com.br/file/sg-11134201-825a7-mr06u04rb6deb1', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F778895824%2F58256755919', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '23598943450', 'Kit 4 assadeiras antiaderente tramontina forma retangular funda', 'Kit 4 Assadeiras Retangulares Tramontina Antiaderente Leve mais praticidade, qualidade e estilo pra sua cozinha com esse kit incrível da Tramontina! São 3 assadeiras retangulares em tamanhos perfeitos para o dia a dia: Medidas: Grande: 40 cm Grande: 34 cm Média: 28 cm Pequena: 22 cm - Destaques do produto: * Revestimento interno e externo antiaderente Starflon Max – os alimentos não grudam e a limpeza é super fácil *Produzidas em alumínio durável – assam de maneira uniforme *Podem ir ao forno até 230°C *Design moderno, na cor preta, combina com qualquer cozinha *Produto original Tramontina, com qualidade garantida Ideal para preparar bolos, carnes, lasanhas, legumes assados e muito mais! E o melhor: o kit completo ocupa pouco espaço, pois as formas se encaixam facilmente. Aproveite para deixar sua cozinha mais prática com um produto resistente, bonito e funcional! O design retangular das assadeiras não só otimiza o espaço no forno, mas também proporciona uma distribuição uniforme do calor, resultando em pratos perfeitamente assados. Com a Tramontina, você pode confiar na durabilidade e na qualidade dos produtos, tornando cada refeição uma ocasião especial.', 329.9, 329.9, NULL, 'Home & Living > Kitchenware > Bakewares & Decorations', 'https://cf.shopee.com.br/file/br-11134207-81z1k-mf8fet0guebq40', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F316877265%2F23598943450', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
