INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '20197622370', 'Livro Messi | O Gênio Completo | Ariel Senosiain', 'Agora completo, o gênio do futebol é retratado neste livro pela visão daqueles que mais estiveram perto e sempre souberam do que ele era capaz. O experiente jornalista Ariel Senosiain fez 68 entrevistas e conseguiu o que ninguém conseguiu: falar com o próprio pai do Messi, o treinador Alejandro Sabella e o ex-presidente da FIFA Sepp Blatter. A recriação vívida das peças-chave são um presente para os amantes do futebol e a análise afiada conquista todos os leitores. Uma leitura cativante. Uma história épica. ARIEL SENOSIAIN é palestrante e escritor. Nascido na Argentina, o jornalista desenvolveu sua carreira dentro do mundo da informação esportiva, com especial atenção ao mundo do futebol e seus principais atores, ou seja, treinadores e jogadores de futebol. Detalhes : Autor: Ariel Senosiain Editora: Vida Capa: Brochura Páginas: 248 Medida: 15,5 larg. x 22,5 alt.', 50.99, 50.99, NULL, 'Books & Magazines > Books > Biography & Memoirs', 'https://cf.shopee.com.br/file/sg-11134201-825bc-mqj9bc98gft7d9', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F217167158%2F20197622370', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
