INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '23898094537', 'Mini Processador Gourmet 100W 1 Velocidade Multilaser', 'Mini Processador Multilaser, tenha uma diversidade de descobertas na cozinha! Desenvolvida com capacidade de 350ml para você preparar grandes quantidades de alimentos de uma só vez, possui botão de pulsar para ter maior controle do resultado desejado da trituração dos alimentos, com a alta velocidade ela te proporciona maior praticidade no seu dia a dia tornando mais rápido o preparo das suas refeições. Vem com tampa com trava para sua maior segurança, botão pulsar, recipiente desmontável para facilitar a limpeza e armazenamento, laminas de aço para moer ou triturar com alto desempenho, trava de segurança para evitar acidentes durante o preparo e pés antideslizantes. Suas receitas mais práticas e deliciosas Características: Capacidade em Litros: 350ml Quantidade de Discos: 1 Quantidade de Peças: 1 Tipos de Discos: Fatiador Potência: 100W Dimensões do produto: Altura: 14,5 cm Largura: 20,5 cm Profundidade: 12 cm Peso: 74 g Garantia do fornecedor: 12 meses Observações: Imagem meramente ilustrativa; Verifique a voltagem do produto antes de colocar no carrinho; Todas as informações divulgadas são de responsabilidade do fabricante/fornecedor; As cores podem sofrer variações de acordo com o tipo, configuração e resolução do seu monitor; Não nos responsabilizamos pela montagem/instalação dos produtos;', 69.9, 69.9, NULL, 'Home Appliances > Kitchen Appliances > Food Processors & Meat Grinders', 'https://cf.shopee.com.br/file/sg-11134201-7rfg4-m4auhh25pp23fa', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F443109642%2F23898094537', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
