INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '23193270449', 'Lápis Retrátil Para Olhos Dazzle Preto', 'Descubra o Lápis Retrátil para Olhos Dazzle Preto – Sua Nova Ferramenta de Beleza Imprescindível Realce o olhar com precisão e elegância utilizando o Lápis Retrátil para Olhos Dazzle Preto. Criado especialmente para quem busca um produto de alta performance, esse lápis oferece uma aplicação suave e eficaz. Com uma cor intensa e profunda, ele é perfeito para definir e contornar os olhos, proporcionando um resultado espetacular que dura o dia todo sem borrar. Seja para um look dia a dia mais natural ou para um olhar dramático de noite, o Lápis Retrátil para Olhos Dazzle Preto é a escolha certa. A sua formulação exclusiva garante um deslizar perfeito, enquanto o mecanismo retrátil oferece praticidade e precisão sem igual. Esqueça o apontador, este lápis está sempre pronto para usar. Características Cor intensa preta Mecanismo retrátil Longa duração Fácil aplicação Benefícios Define e realça os olhos instantaneamente Permanece intacto por horas, mantendo o look perfeito Ideal para uso diário ou ocasiões especiais Prático para levar em qualquer lugar Diferenciais Formulação de alta qualidade que protege a área sensível dos olhos Produto testado dermatologicamente e oftalmologicamente Adequado para usuários de lentes de contato Recomendações Para resultados ótimos, aplique o Lápis Retrátil para Olhos Dazzle Preto junto à linha dos cílios, deslizando suavemente do canto interno para o externo. Para um efeito esfumado, esbata levemente após a aplicação com um pincel apropriado. Não perca a chance de destacar seus olhos com precisão e estilo. Adquira agora seu Lápis Retrátil para Olhos Dazzle Preto e transforme seu olhar!', 43.9, 43.9, NULL, 'Beauty > Makeup > Eyes', 'https://cf.shopee.com.br/file/sg-11134201-7rdwq-m023ohjokmgqd