INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '7060913285', 'Pyraminx QiYi QiMing A Stickerless sem Adesivos Profissional', 'SOBRE O PRODUTO O QiYi QiMing A é um Pyraminx não magnético de entrada, com sistema de posicionamento por esferas e regulagem por parafusos e molas. DESTAQUES - Sistema não magnético com esferas de posicionamento - peças coloridas, sem adesivos - Indicado para aprendizado e treino ESPECIFICAÇÕES - Marca: QiYi MoFangGe - Modelo: QiMing A Pyraminx - Peso aproximado: 82,2 g CONTEÚDO DA EMBALAGEM - 1 QiYi QiMing A Pyraminx', 59.9, 59.9, NULL, 'Hobbies & Collections > Toys & Games > Rubik''s Cubes', 'https://cf.shopee.com.br/file/729e68f8fd34eb553b2402a30e2c9654', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F302271094%2F7060913285', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '20498296112', 'Body Splash Masulino Lattitude Profundo HINODE', 'Mergulhe em uma fragrância que transmite frescor e intensidade. Lattitude Profundo é inspirado na força das águas e na sensação de liberdade que só o mar proporciona. Sua composição aromática une notas cítricas vibrantes a acordes aquáticos refrescantes, revelando uma essência leve, moderna e cheia de energia. Ideal para homens que buscam um perfume marcante, mas ao mesmo tempo fresco, perfeito para o dia a dia e momentos de descontração. Produto 100% original Hinode. Loja oficial com envio seguro e procedência garantida.', 54.9, 43.92, NULL, 'Beauty > Perfumes & Fragrances', 'https://cf.shopee.com.br/file/br-11134207-820l5-mqf0wz8j826b98', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F876865394%2F20498296112', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '29014046678', 'Erborian CC / BB Cream collection', 'Erborian CC / BB Cream collection 1. Erborian CC Red Correct, 15mL / 45mL - Description An illuminating green color corrector, CC Red Correct uses Centella Asiatica and green encapsulated pigments to visibly reduce redness while helping soothe and hydrate the skin. The result is a natural finish on the skin. - Benefits Visibly reduces redness, under eye wrinkles and appearance of blemishes, provides hydration and SPF 25. - Suggested Use Apply a fine layer on clean skin using your fingertips. Use alone or as a color corrector before foundation. 2. Erborian BB Creme Au Ginseng, 15mL / 40mL (SPF20) - Color option : Nude / Clair - Description The Korean Beauty secret is yours with Erborian BB Cream. Enriched with Ginseng, our BB Cream is the combination of Korean skincare and foundation for a ''baby skin'' effect. - Benefits BB Cream evens out your skin tone, conceals imperfections, moisturizes and offers a smooth finish. - Suggested Use Apply a fine layer of Erborian BB Cream on your face either after or in lieu of your regular moisturiser 3. Erborian Super BB, 15mL (SPF25) - Color option : Nude / Clair - Super BB: the BB cream with half complexion and semi-care expertise, which conceals and balances imperfections without applying thick. With this opaque BB cream, you can bring your "baby skin" to life, without mask effect. Non-comedogenic - The complexion: Super BB offers higher coverage and conceals impurities, redness and pigment spots. Thanks to its light, comfortable texture, this corrective product leaves a natural, silky finish - Nourishing effect: This anti-pimple care combines 2 Korean super active ingredients, white ginseng and fermented ginseng flower, in a formula that instantly reveals smoother, moisturized skin. Niacinamide works for clearer skin - Beauty tip: Apply a day cream first, then a make-up base and then apply the opaque BB Cream to the entire face. A hazelnut-sized amount of product is sufficient. The coverage can be adjusted - Cruelty-free products are our priority: none of the products, ingredients or raw materials Erborian uses have ever been tested on animals, even the raw materials of our suppliers are completely free from animal testing', 106.33, 106.33, NULL, 'Beauty > Makeup > Face', 'https://cf.shopee.com.br/file/sg-11134207-7rdxz-m1dnqmlkwged52', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F920292999%2F29014046678', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '23398676959', 'Tapete para Cachorro Higiênico com 50 Unidades DOG MAT Pet 60x60cm, Ultra Absorção e Free Odores', 'Mais limpeza e conforto para seu lar com o Tapete Higiênico para Pets! Perfeito para cães de todos os portes – do pequeno Chihuahua ao grande Golden Retriever – nosso tapete higiênico foi desenvolvido para facilitar o dia a dia dos tutores e manter a casa sempre limpa e livre de odores. ✅ Tamanho ideal: 60cm x 60cm – excelente para pets pequenos, médios e grandes. 🐶 Indicado para raças como Shih Tzu, Poodle, Pug, Spitz Alemão, Labrador, Dachshund, Pinscher, Lhasa Apso, entre outras. 🛡️ 6 camadas de proteção com tecnologia ultra absorção – mais segurança contra vazamentos. 🚫 Adesivo na base que evita que o tapete deslize pelo chão. 🌸 Camuflador de odor, deixando o ambiente mais agradável por muito mais tempo. 📦 Pacote com 50 unidades – economia e praticidade para a sua rotina. Ideal para quem busca praticidade, higiene e bem-estar para o seu pet!', 89.9, 49.9, NULL, 'Pets > Litter & Toilet > Small Pet Bedding & Litter', 'https://cf.shopee.com.br/file/br-11134207-820ld-moa0uusvy03p2d', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1384728500%2F23398676959', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
