INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '23296191346', 'Tubes Morango Azedinho Finibox 1kg - Fini', 'Tubes Morango Azedinho Fini, um clássico da marca. Azedinhos, cumpridinhos e saborosos, possuem formato de tubo. No pacote contém tubes na cor vermelho com sabor de morango e acabamento cítrico. Pote com 1kg de produto, ideal para realização de festas, E perfeito para usar em decorações de mesas de festas e pratos de confeitaria, tornando tudo mais colorido, com um toque único e especial!', 51.07, 43.99, NULL, 'Food & Beverages > Snacks > Sweets & Candy', 'https://cf.shopee.com.br/file/sg-11134201-7qvfn-liucgu46p03l52', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F992995220%2F23296191346', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '21197749071', 'Motivado | 8 Segredos do Sucesso na Criação de Filhos | Dr. Peter e Deonna Tan-Chi', 'Mães e pais de dedicam para deixar uma marca positiva na vida dos filhos, um legado com consequências eternas. Não é uma tarefa fácil, mas com os oito princípios bíblicos de Motivado, é possível. Este não é apenas mais um livro para ajudar você a criar seus filhos, mas o desvendar dos segredos aplicados e comprovados pelos autores na criação dos próprios filhos Formato: 16x23 cm Nº de Páginas: 292 pág Peso: 410 g', 39.9, 32.9, NULL, 'Books & Magazines > Books > Religion & Philosophy', 'https://cf.shopee.com.br/file/sg-11134201-7rd59-lx1wvegnx93c4a', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F373289765%2F21197749071', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '42256312366', 'Cute & Comfy Super Special - Livro de Colorir Adulto - Colorindo com Deus - Acompanha 1 Caneta', 'Fortaleça sua fé enquanto colore com Cute & Comfy Colorindo com Deus Pai!Um livro especial, com mensagens edificantes e ilustrações que acalmam o coração. Perfeito para momentos de paz e conexão espiritual. E ainda acompanha uma caneta de brinde para deixar tudo mais bonito!', 59.9, 13.93, NULL, 'Books & Magazines > Books > Sticker & Colouring Books', 'https://cf.shopee.com.br/file/sg-11134201-7ra25-mbh5m882j6h94d', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F482840775%2F42256312366', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '12032868405', 'Devocional Dia a dia Com Spurgeon Manhã e Noite - Capa Dura', 'O Livro Dia a Dia Com Spurgeon – Capa Dura é mais um devocional incrível que vai lhe ajudar a ter ainda mais intimidade com Deus. Nele há duas meditações para cada dia do ano, uma para a manhã e uma para a noite. Essas meditações foram escritas no século 19 por Charles H. Spurgeon, abordando diversos temas de forma aberta, trazendo reflexão e edificação para o seu cotidiano. Além de utilizar uma linguagem atualizada e conter a biografia do autor, que esclarece o contexto histórico das mensagens. Páginas: 760 Peso: 0,5920 kg Dimensões: 11,2 x 17,8 cm Capa Dura', 99.9, 58.95, NULL, 'Books & Magazines > Books > Religion & Philosophy', 'https://cf.shopee.com.br/file/45d49d9bf18f40473b39922791de4303', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F373289765%2F12032868405', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '22592835229', 'Meu Sol de Primavera | Queren Ane', 'Da coautora de Corajosas Chér vive aos 15 anos uma paixão intensa por um colega de classe. Sonha dar o primeiro beijo, ser pedida em namoro e viver um lindo romance. Quando surge uma oportunidade de fisgar o garoto, Chér não hesita em bolar um plano para conquistar o coração do crush. Será que seus planos darão certo? Ela conseguirá viver o romance tão desejado? "Queren Ane presenteia esta geração de meninas cristãs com um verdadeiro tesouro. Meu sol de primavera é uma narrativa leve, bonita e que ao mesmo tempo traz mensagens profundas sobre o que é o verdadeiro amor e onde encontrá-lo. A jornada de amadurecimento da Chér fará você refletir sobre sua vida e suas escolhas. Terminei a leitura com o coração quentinho após relembrar minha adolescência e como Deus também mudou o curso de minha vida durante aqueles anos. Prepare-se para dar boas risadas e ser tocada por essa história singular!" Arlene Diniz, coautora de Corajosas 14x21cm 304 Páginas', 56.99, 50.9, NULL, 'Books & Magazines > Books > Romance', 'https://cf.shopee.com.br/file/sg-11134201-7rcef-lraq04qdmdlrce', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F373289765%2F22592835229', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '12145592286', 'Ele Está Sempre ao meu Lado - Warren Wiersbe', 'A certeza da presença de Deus em todos os momentos da jornada de quem nele crê é o grande conforto do cristão e o tema central de Ele está sempre ao meu lado. Escrito pelo consagrado pastor, teólogo e conferencista norte-americano Warren Wiersbe, o livro trata das promessas divinas de conforto para hoje e de segurança para amanhã. É isso mesmo: o texto de Wiersbe transita por conhecidos trechos bíblicos, lembrando ao leitor de que o socorro vem do Senhor. Deixando para trás as eventuais dores do passado, Wiersbe nos convida a confiar plenamente naquele que declarou ser o bom pastor e a videira verdadeira. “O meu passado pode me desencorajar e o meu futuro, me assustar; mas, a vida que vivo hoje pode ser enriquecedora e estimulante porque Cristo vive em mim”, frisa o autor. Com base em certezas como esta, Ele está sempre ao meu lado leva o leitor e novos patamares de comunhão plena com o Senhor. Peso: 248gr Autor: Warren W. WiersbeNº de páginas: 160Papel: Polen 70 grFormato: 16x23cmISBN: 978-85-8064-239-1', 25.9, 20.9, NULL, 'Books & Magazines > Books > Religion & Philosophy', 'https://cf.shopee.com.br/file/aa1e96f05db952785fee39e37228c601', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F373289765%2F12145592286', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '22099145208', 'O Professor | Charlotte Brontë', 'William Crimsworth é um jovem inglês, órfão, que decide renunciar a todas as ajudas que poderia ter para subir na vida ou manter-se estável, tentando por si mesmo alcançar os seus objetivos e interesses. Criado pelos tios, que desejam que ele se torne um clérigo, ignorado pelo irmão mais velho, tirano e mesquinho, parte para Bruxelas, para trabalhar como professor. Ali, William descobre o amor e o sentido da vida.288 páginas15,5x22,6 cm', 18.9, 14.9, NULL, 'Books & Magazines > Books > Religion & Philosophy', 'https://cf.shopee.com.br/file/sg-11134201-821fq-mglq5d75ljpmca', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F373289765%2F22099145208', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '20097408623', 'Bíblia Sagrada ARA | Letra Gigante | Sintético Flexível | Pink', 'Esta edição da Bíblia Sagrada é ideal para quem busca conforto na leitura da Palavra de Deus e, ao mesmo tempo, praticidade no uso e transporte diários. Disponível em diversas opções de capa, com ou sem zíper. A linha Ouro apresenta material de acabamento de excelente qualidade, papel importado e valor acessível. Tradução: Almeida Revista e Atualizada Idioma: Português Tamanho da Letra: Gigante Capa: Pink Acabamento: Sintético Flexível Medida: 13,5 X 20,0 cm Formato: Médio Páginas: 1690 páginas Índice: Não Indicado para: Evangelização ISBN: 7899938423165 Recurso Como encontrar ajuda na Bíblia Conteúdo da Bíblia Leituras para dias especiais Mapas O que a Bíblia diz sobre o perdão de Deus Tabela de pesos, moedas e medidas', 79.9, 55.9, NULL, 'Books & Magazines > Books > Religion & Philosophy', 'https://cf.shopee.com.br/file/sg-11134201-7rbl9-lm2n2pe40nkp40', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F373289765%2F20097408623', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
