INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '23392842924', 'Caneca Wolff de Vidro Borossilicato com Canudo e Tampa 400ml', 'Caneca Wolff de Vidro Borossilicato com Canudo e Tampa 400ml Desfrute de suas bebidas favoritas com estilo e praticidade com a Caneca de Vidro Borossilicato da Wolff. Com um design elegante e funcional, esta caneca é uma adição encantadora para sua coleção de utensílios de cozinha. Material PremiumFabricada com vidro borossilicato de alta qualidade, esta caneca é resistente a altas temperaturas e possui uma durabilidade excepcional. Tampa de BambuAcompanhada por uma tampa feita de bambu, esta caneca mantém suas bebidas quentes por mais tempo e evita derramamentos indesejados. Canudo ReutilizávelInclui um canudo de vidro reutilizável, oferecendo uma alternativa sustentável aos canudos de plástico descartáveis. Capacidade IdealCom capacidade para 400ml, esta caneca é perfeita para uma variedade de bebidas, como café, chá, sucos e smoothies. VersatilidadeAlém de ser ideal para uso doméstico, esta caneca é ótima para viagens, passeios ao ar livre e atividades cotidianas. Desfrute de suas bebidas com consciência ambiental e elegância com a Caneca de Vidro Borossilicato com Canudo e Tampa de Bambu 400ml da Wolff. Wolff. A excelência em receber, servir e decorar! Contém: 1 Caneca Lava Louça: Não Microondas: Não Forno: Não Fogão: Não Freezer: Não Medidas Produto: Altura 20,00cm x Largura 6,50cm x Comprimento 9,50cm Peso: 0,13Kg Cor: Incolor Material: Vidro Borossilicato Lavar com detergente neutro, esponja macia e secar imediatamente.', 50.0, 34.99, NULL, 'Home & Living > Dinnerware > Cups, Mugs & Glasses', 'https://cf.shopee.com.br/file/sg-11134201-7rcck-lrrdyujzrb6mf0', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F869809385%2F23392842924', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '48305513220', '4 Guardanapos Lyor Momentos 40cm x 40cm Creme Algodão - Lyor', 'Cansado de guardanapos descartáveis que empobrecem a decoração ou tecidos rígidos que não absorvem? Eleve o nível das suas recepções com a sofisticação e o toque acolhedor do algodão premium da Lyor. O Jogo de Guardanapos Lyor Momentos foi desenvolvido para quem entende que a verdadeira elegância reside nos detalhes. Confeccionados em 100% algodão de alta qualidade, eles oferecem um toque extremamente macio e um acabamento refinado que protege seus convidados com conforto. O tom creme é o curinga indispensável da mesa posta: uma cor neutra e versátil que ilumina o ambiente e harmoniza perfeitamente com louças clássicas, rústicas ou contemporâneas. A Lyor é referência nacional e autoridade absoluta no segmento de decoração de luxo acessível. Como especialistas no mercado de utilidades domésticas, garantimos que investir em guardanapos de tecido não é apenas uma escolha sustentável, mas um upgrade imediato no status do seu jantar. Temos poucas unidades deste lote em estoque com envio imediato. Garanta a peça que transforma uma simples refeição em uma celebração memorável. ESPECIFICAÇÕES TÉCNICAS Marca: LYOR Linha: Momentos Material: 100% Algodão (Fibra natural premium) Cor: Creme (Neutro Sofisticado) Quantidade: Kit com 04 unidades Medidas: 40,00cm x 40,00cm (Tamanho padrão luxo) Peso: 0,04Kg (por unidade) Diferenciais: Tecido lavável, alta absorção e acabamento de alfaiataria. DÚVIDAS FREQUENTES O tecido é transparente? Não. O algodão da linha Momentos possui uma gramatura ideal que garante opacidade e elegância na dobradura. Como devo lavar para manter a cor? Recomendamos seguir as instruções da etiqueta. Por ser algodão, lave com sabão neutro e evite alvejantes para preservar a tonalidade creme original. Posso usar com anéis de guardanapo? Sim, o tamanho 40x40cm é perfeito para diversas dobraduras e comporta todos os tipos de porta-guardanapos. CONTEÚDO DA EMBALAGEM 04 Guardanapos Lyor Momentos 40cm x 40cm em Algodão Creme. Dê à sua mesa o toque de classe que ela merece. Clique no botão de compra agora e finalize seu pedido para garantir a qualidade original Lyor no seu endereço!', 37.0, 37.0, NULL, 'Home & Living > Dinnerware > Cutleries', 'https://cf.shopee.com.br/file/br-11134201-820m1-mqyimxpzln9i5d', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F869809385%2F48305513220', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
