INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '58209497702', 'Copo Térmico To Go Snoopy', 'Depois de um dia cheio de novas descobertas explorando novos lugares, você não conseguiu matar a sua sede e ir para o lado hidratado da força? A gente te ajuda! Com 400ml de capacidade, e uma alça para carregar, é a companhia perfeita para te acompanhar nas suas missões! Não importa onde é, esse copo te acompanha em todas as suas aventuras! O produto é importado, feito em aço inoxidável, possui detalhes incríveis que vão fazer você se apaixonar! Se depois de um dia cansativo explorando novos lugares e descobrindo novas brincadeiras, você não consegue se hidratar direito? A gente te ajuda! Com 400ml de capacidade, é compacto e cabe em qualquer cantinho da sua mochila ou bolsa! Com uma tampa que evita vazamentos, contém bico duplo, com canudo para você beber como quiser, além de contar com parede dupla para ajudar a manter a temperatura da sua bebida por muito tempo! E se precisar carregar o copo por aí, ele possui uma alça para te acompanhar em todos os lugares! Não importa a bebida, esse copo te acompanha em todos os goles! Especificações: Altura: 12cm| Largura: 8,5cm| Comprimento: 8,5cm| Capacidade: 400ml| Material: Aço inoxidável e plástico | Livre de BPA: Sim Cuidados e recomendações de uso: Não colocar o produto na geladeira ou congelador. Choques ou quedas podem danificar o produto. Lavar com água, esponja macia e sabão neutro. Não vai á lava-louças e nem ao micro-ondas. Não utilizar produtos químicos ou abrasivos.', 124.9, 124.9, NULL, 'Home & Living > Dinnerware > Cups, Mugs & Glasses', 'https://cf.shopee.com.br/file/sg-11134201-820mo-mnfpluyx7i0z26', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F404743073%2F58209497702', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
