INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '47206406418', 'Luva Térmica Cozinha Silicone Forno Alta Temperatura Forradas Algodão', 'SOBRE O PRODUTO A luva de cozinha de silicone é ideal para proteger suas mãos durante o preparo de alimentos, oferecendo segurança e conforto no manuseio de panelas, formas e utensílios quentes. Fabricada em silicone resistente ao calor, garante proteção térmica e excelente aderência. Seu tamanho de 30 cm proporciona maior cobertura do pulso e antebraço, ajudando a evitar queimaduras. Flexível, durável e fácil de limpar, é perfeita para o uso diário na cozinha, forno, churrasqueira ou micro-ondas. Essencial para quem busca mais segurança, praticidade e estilo na cozinha. DIFERENCIAIS DO PRODUTO - Material de silicone e forro algodão - Proteção contra altas temperaturas - Antiderrapante e confortável - Fácil de lavar e reutilizável ESPECIFICAÇÕES TÉCNICAS Medidas: Comprimento 30cm x Largura da abertura 13,5cm Material: Silicone e Algodão', 59.9, 24.9, NULL, 'Home & Living > Kitchenware > Aprons & Kitchen Gloves', 'https://cf.shopee.com.br/file/br-11134207-81ztv-ml3lg3g9dxj41c', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F455103761%2F47206406418', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
