INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '20998314638', 'Miniatura Moto 1/18 Ktm 450 Sx-f 2018 #84 - Burago Red Bull Laranja', '🏍️ Bburago 1:18 KTM 450 SX-F #84 2018 — Miniatura de Moto Red Bull (Laranja) A emoção do motocross direto para sua coleção! Reviva as manobras radicais e o espírito competitivo da equipe Red Bull KTM com esta miniatura oficial da KTM 450 SX-F #84 — temporada 2018, pilotada pelo astro do motocross Jeffrey Herlings. ✨ Detalhes que impressionam Escala 1:18 (aprox. 11 cm de comprimento) Produzida em metal fundido (die-cast) com detalhes plásticos de alta qualidade Pintura oficial laranja Red Bull KTM com adesivos fiéis ao modelo real Pneus emborrachados com textura realista e guidão móvel Base expositora inclusa para manter sua moto em destaque 💥 Por que vale a pena Produto oficial e licenciado da Bburago Ideal para colecionadores de esportes radicais e fãs da KTM Perfeita para decorar mesas, estantes e ambientes temáticos Presente criativo e memorável para entusiastas de velocidade Peça de alto valor estético — chama atenção de qualquer visitante 📦 Produto novo e lacrado — envio imediato com rastreamento 🎁 Embalado com todo cuidado para chegar impecável 💳 Compre com segurança e confiança', 116.2, 116.2, NULL, 'Mom & Baby > Toys > Toy Vehicles', 'https://cf.shopee.com.br/file/sg-11134201-82589-meu23yrz3yfbed', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F344434810%2F20998314638', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
