INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '46805755719', 'Conjunto Fitness Feminino Academia Top Costas Abertas Alta Sustentação Calça Legging com Bolso Frame', 'Quando você bate o olho nessa peça logo pensa que é só mais um modelo básico...Mas não! Ela te surpreende com um decote nas costas com um desenho impecável, feito e pensado para valorizar o corpo. Seu tecido conta com uma poliamida de toque geladinho, de alta compressão e mega confortável! Informações adicionais: A modelo veste: P Composição: 82% poliamida / 18% elastano Garantia: Contra defeitos de fabricação Com aquele tecido geladinho, macio e de alta compressão que vocês já conhecem da Lot, a Legging Frame veio pra deixar seus treinos e dia a dia muito mais práticos e estilosos! Com dois bolsos (um em cada lateral), essa é uma peça que traz versatilidade, sem deixar de lado seu design moderno que traz todo o charme para a peça. Informações adicionais: A modelo veste: P Cintura: AltaComposição: 82% poliamida / 18% elastano Garantia: Contra defeitos de fabricação *Cores claras: Opte por usar lingerie de cor nude.', 234.9, 182.9, NULL, 'Sports & Outdoors > Sports & Outdoor Apparels > Sets', 'https://cf.shopee.com.br/file/br-11134207-81ztc-mk8dn9vzf7r429', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F373847201%2F46805755719', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '19197672315', 'Fluxo Para Soldagem Gota Magica - DNI HYB 9999', 'Fluxo Para Soldagem Gota Magica - DNI HYB 9999Descrição do ProdutoO HYB9999 é um fluxo para solda que oferece praticidade e eficiência em suas aplicações. Com a capacidade de facilitar a soldagem de fios com liga de cobre e alumínio, este produto inovador se destaca no mercado. Além disso, o fluxo para solda DNI HYB9999 substitui a tradicional pasta de solda, tornando o processo mais simples e eficaz. Com fácil remoção e solubilidade em água, o HYB9999 garante uma experiência de soldagem mais limpa e eficiente. Sua embalagem em frasco de 10g proporciona praticidade no manuseio e armazenamento do produto. Atributos do ProdutoMarca: DNI Facilita a soldagem de fios com liga de cobre + alumínio Substitui a pasta de solda Fácil remoção, solúvel em água Embalagem: Frasco de 10g Aproveite todos os benefícios e praticidade que o fluxo para solda DNI HYB9999 pode oferecer. Garanta já o seu e simplifique suas operações de soldagem!', 33.77, 33.77, NULL, 'Spare Parts and Accessories for Vehicles > Spare Parts for Automobiles > Electrical System', 'https://cf.shopee.com.br/file/sg-11134201-7rd74-ltzlvwvllbzm03', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F972460632%2F19197672315', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
