INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '23599018584', 'EA Sports 26 - Playstation 5 Midia Fisica', 'EA Sports 26 - Playstation 5 Midia Fisica O Clube é Seu no EA SPORTS FC 26. Jogue ao seu modo com uma experiência de jogabilidade melhorada, impulsionada pelos comentários da comunidade. Características: JOGABILIDADE REFORMULADA, IMPULSIONADA PELOS COMENTÁRIOS DA COMUNIDADE Jogue do seu jeito no EA SPORTS FC 26 com condução mais responsiva, posicionamento de IA mais inteligente e movimentos mais precisos e explosivos com base nos comentários da comunidade. Os goleiros e goleiras agora reagem de forma mais natural com melhor posicionamento, animações mais realistas. JOGUE DO SEU JEITO COM DUAS PREDEFINIÇÕES DE JOGABILIDADE DISTINTAS O FC 26 apresenta duas novas predefinições de jogabilidade, cada uma projetada para uma maneira diferente de jogar. Competitiva é ajustada para ação frente a frente no Ultimate Team e Clubs, com passes mais rápidos, rebotes mais inteligentes. DESCUBRA MAIS MANEIRAS DE COMPETIR NO FOOTBALL ULTIMATE TEAM Participe de novas formas de competição no Football Ultimate Team com torneios e eventos ao vivo, além de uma experiência renovada no Rivals e Champs. Os torneios vão testar suas habilidades com até quatro rodadas eliminatórias, enquanto os Eventos ao Vivo adicionam mais variedade com competições temáticas e conteúdo durante toda a temporada. JOGUE EM EQUIPE DURANTE TODA A TEMPORADA NOS CLUBS Jogue em equipe com grandes novidades nos Clubs no EA SPORTS FC 26. Experimente mais variedade ao longo da temporada ao jogar sozinho ou com colegas de clube em Eventos ao Vivo dinâmicos, com novos desafios e requisitos de entrada variados, jogabilidade Rush modificada e regras alternativas, criando novas oportunidades para ganhar recompensas durante o ano todo. Plataforma: Playstation 5 Publisher: Eletronic Arts Espaço em Disco: Min. 60GB Gênero: Esportes / Simulador Quantidade de Jogadores: 1 a 4 Jogadores offline / 1 a 22 Jogadores onlineIdioma: Áudio em Inglês / Legendas em Inglês Classificação Indicativa: Livre - Sem Inadequações Conteúdo da Embalagem: 1 - Jogo EA Sports 25 - Playstation 5 Midia Fisica Garantia: 12 meses contra defeito de Fabricação. Imagens meramente ilustrativas.', 399.9, 399.9, NULL, 'Gaming & Consoles > Video Games > Playstation', 'https://cf.shopee.com.br/file/sg-11134201-8258j-mfsk3phireha21', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1001665622%2F23599018584', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
