INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '58259711768', 'Fit Food Pasta de Amendoim Cremosa', 'A Pasta de Amendoim Cremosa da Fit Food é perfeita para quem busca energia e um complemento proteico para a alimentação. Feita com amendoim, é naturalmente fonte de proteínas, vitaminas, minerais e gorduras boas. * Vegana * Sem glúten * Zero Sódio * Zero Açúcar Pronta para o consumo, é natural que o óleo se separe da pasta. Basta misturar com uma colher para voltar à consistência normal. Conservar em temperatura ambiente, longe de produtos químicos.', 18.79, 18.79, NULL, 'Food & Beverages > Breakfast Cereals & Spread > Jam & Spread', 'https://cf.shopee.com.br/file/sg-11134201-825at-mqnelmf5c5jfaa', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1676555116%2F58259711768', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
