INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '58206958059', 'Reservatório Partida Frio Volkswagen Fox 2009 a 2015', '5Z0201922C Reservatório Partida Frio Volkswagen Fox, 2009/2015, 1.0 Flex - 76cv Volkswagen Fox, 2009/2014, 1.6 Flex - 104cv Volkswagen SpaceFox, 2009/2014, 1.6 Flex - 104cv Catálogo de Aplicações GoParts Diauto Volkswagen - Concessionária Oficial VW Fabricante: Volkswagen Local: São Caetano do Sul - SP OBSERVAÇÕES: - PREÇOS E CONDIÇÕES ANUNCIADOS VÁLIDOS SOMENTE PARA VENDAS DENTRO DO ESTADO DE SP. - PARA FATURAMENTO EM OUTROS ESTADOS, CONSULTE-NOS ANTES DE FINALIZAR A COMPRA. Envio: Produtos em Estoque - Postagem em 01 (um) dia útil. Compras efetuadas até 15h30 serão postadas no mesmo dia. - Todos os produtos são originais e têm garantia de 3 meses. - Evite transtornos: antes de efetuar a compra use o campo perguntas para retirar eventuais dúvidas. - Caso o parceiro logístico não entregue o produto, o pagamento será estornado. - Em caso de devolução da mercadoria, a mesma deverá estar em perfeito estado, incluindo a embalagem. - A má instalação pode gerar avaria nas peças, impossibilitando a devolução. - Preserve a embalagem original do produto até se certificar da aplicabilidade. SUPORTE E HORÁRIOS DE ATENDIMENTO: - Temos Equipe de Atendimento e Suporte Técnico Especializado a disposição. - Atendimento de Seg. a Sex. das 8h00 às 17h00.', 223.63, 223.63, NULL, 'Spare Parts and Accessories for Vehicles > Spare Parts for Automobiles > Engine', 'https://cf.shopee.com.br/file/sg-11134201-81zup-minyb6yf9ede64', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1731717601%2F58206958059', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
