INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '15121898529', 'Cafeteira Italiana Nuova Moka Express 3 Xícaras – Bialetti', 'A Original, desde 1933 o melhor método de preparo do café espresso italiano. Qualidade duradoura e design. Moka Bialetti celebra 80 anos de elegância, design clássico e simplicidade tecnológica. Do início dos anos 1950 até os dias atuais, a Bialetti fabricou mais de 200 milhões de cafeteiras. Em particular, a Moka se tornou icônica e permitiu que milhões de consumidores apreciassem o café italiano. A Bialetti está desde 1919 construindo a sua história em torno de diversos princípios como tradição, reconhecimento, qualidade, alto nível de inovação, design, uma extensa gama de produtos e responsabilidade social, investindo dia após dia em uma forte filosofia corporativa. A história de Bialetti está em cada um de nossos produtos, que hoje são um símbolo do design Italiano e te acompanham dia após dia.', 359.9, 287.92, NULL, 'Home Appliances > Kitchen Appliances > Coffee Machines & Accessories', 'https://cf.shopee.com.br/file/2418dc57007638be28e610c240090126', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F447801038%2F15121898529', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
