INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '9070262869', 'Livro - Contos de fadas europeus - Capa comum - Principis', '''O rei dos peixes'', ''A tesoura'', ''A linguagem dos animais'', ''Os três soldados'', ''Uma dúzia de uma só tacada'', ''Donzelas-cisne'', ''Mantenha a calma'', ''O visitante do paraíso'', ''O marido invisível'' são algumas das histórias que você encontra neste volume. O autor selecionou 22 contos, alguns completamente desconhecidos, outros mais atuais, todos nascidos na Europa. Um trabalho de ourives dos contos de fadas! Editora: Principis Edição: 1, 2021 Autor: Joseph Jacobs Idioma: Português Páginas: 128 Dimensões: L 15.50 x A 22.60 x E 1.00 ISBN: 9786555523997', 19.9, 19.9, NULL, 'Books & Magazines > Books > Classic Literature', 'https://cf.shopee.com.br/file/4ddb1dbb1c9d5caec8b28d02780c6885', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F458071934%2F9070262869', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
