INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '42510187490', 'Livro The adventures of Huckleberry Finn W.Books', 'When his uncaring father comes back to town, thirteen-year-old Huckleberry Finn decides that it’s time to leave. He begins his journey of adventure and_x000D_ independence on the beautiful Mississippi River. Along the way, he finds Jim, an enslaved man who has run away. Together, they head for Cairo in Illinois,_x000D_ forming an unlikely friendship and working together to overcome the obstacles they meet. Will they both find the freedom they are searching for at the end of their journey? Includes a free audiobook! QR Code Inside._x000D_ _x000D_ Editora: W. Books_x000D_ Edição: 1, 2025_x000D_ Autor: Mark Twain_x000D_ Idioma: Inglês_x000D_ Páginas: 120_x000D_ Dimensões: L 12.80 x A 19.80 x E 0.60_x000D_ ISBN: 9786552941176_x000D_ Coleção: Easy Classics Childrens Collection Series 2_x000D_ Linha Editorial: W. Books - Clássicos_x000D_ Faixa Etária: + 9 anos_x000D_ Assuntos (tags): Literatura estrangeira, Clássicos, Aventura, História_x000D_ BISAC: Ficção / Ficção / Clássicos_x000D_ Linha de Produto: W. Books_x000D_ Encadernação: Brochura_x000D_ Acabamento: Não se aplica_x000D_ Material: Papel', 19.9, 19.9, NULL, 'Books & Magazines > Books > Children''s Books', 'https://cf.shopee.com.br/file/sg-11134201-7rdvd-mcl3x78x923q69', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F458071934%2F42510187490', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '20598263174', 'Sala de Jantar Talita Tampo de Madeira com 4 Cadeiras Madesa', 'Sala de Jantar Talita Mesa Tampo de Madeira com 4 Cadeiras MadesaTransforme sua sala de jantar em um local muito mais funcional e confortável com o Conjunto de Jantar Talita da Madesa. Características do Produto: - A mesa em pedestal é mais confortável e prática no dia a dia e o tampo de madeira é firme e robusto. - É a opção ideal para quem tem pouco espaço e fica perfeita na cozinha ou na sala de jantar. - As cadeiras são fabricadas em MDF e MDP, com estrutura e encosto em pintura combinando com a tonalidade da mesa. - O assento é estofado em tecido Floral Bege Marrom, um material de toque suave e macio. - O acabamento é no padrão amadeirado Rustic, feito em Pintura Poliéster de alta resistência com sete camadas de proteção. - Pintura resistente a álcool, água e calor. Além disso, é ecológica, isenta de vapores que vão para a atmosfera. - O conjunto é composto pela mesa e quatro cadeiras. Especificações Técnicas: - Marca: Madesa - Itens Inclusos: 1 mesa pedestal com tampo de madeira; 4 cadeiras com encosto em madeira e assento estofado - Dimensões da Mesa (LxAxP): 104 cm X 68 cm X 78 cm - Dimensões das Cadeiras (LxAxP): 37 cm X 89 cm X 44 cm - Cor: Amadeirado Rustic - Tecido: Floral Bege Marrom - Material do Tampo: Madeira - Dimensões da Embalagem (LxAxP): 76,5 cm X 30 cm X 110 cm - Peso Bruto: 39,5 kg - Referência: 045677GX4TFBM Garantia: 3 meses', 599.99, 599.99, NULL, 'Home & Living > Furniture > Desks & Tables', 'https://cf.shopee.com.br/file/sg-11134201-7rdwd-mc18ntvweomxf0', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1215229492%2F20598263174', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
