INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '22094239271', 'Primer Iluminador Facial Escuro Nádia Tambasco By Océane - Glow Skin Medium Tan 30ml', 'Para Valorizar Sua Make e Prolongar a Durabilidade do Visual, Aposte No Glow Skin da Linha Nádia Tambasco By Océane. Este Primer Facial com Partículas de Brilho Deixa a Pele Uniforme e com Aspecto Radiante, Afinal, Uma Maquiagem Iluminada É a Marca Registrada da Rainha do Glow e Pode Ser a Sua Também! Com o Glow Skin, Sua Pele Fica Mais Uniforme, com Um Efeito Desfocado, Além de Aumentar a Durabilidade da Make. Tudo Isso sem Marcar As Linhas de Expressão. o Resultado É Um Efeito de Pele Iluminada Que Deixa Seu Rosto com Um Brilho Lindo e Um Aspecto Natural. Disponível em 5 Cores, a Tonalidade Medium Tan É Um Tom Médio com Fundo Rosado Que Combina Muito Bem com Peles Médio com Um Subtom Mais Quente. Entre Os Benefícios Deste Primer, Vale Destacar Que Ele Pode Ser Usado Sozinho, Antes da Make, ou Ainda, Misturado Ao Seu Hidratante ou Base, Trazendo Uma Leve Luminosidade Ao Look. e Como Versatilidade É Nossa Marca Registrada, o Produto Também Pode Ser Usado Depois da Make, Como Um Iluminador. Sua Fórmula Vegana Contém Vitamina E, Ácido Mandélico, Chá Verde, Lecitina de Soja, Extratos de Ginseng, Centella Asiática e Flor de Lótus. Juntos, Eles Contribuem para Que a Textura do Produto Seja Suave e Agradável, com Uma Ação Hidratante e Calmante, para Uma Pele Mais Bonita, Saudável e com Aspecto Naturalmente Iluminado. Você Vai Se Apaixonar Pelo Resultado! Com Glow Skin By Nádia Tambasco, Sua Pele Vai Brilhar Todos Os Dias! Quem Pode Usar o Glow Skin? Todo Mundo Que Gosta de Uma Pele Uniforme e com Um Brilho Natural Pode e Deve Usar Este Primer Na Sua Rotina de Beleza. a Fórmula do Primer Glow Skin É Recomendada para Pessoas com Todos Os Tipos de Pele. O Primer Facial Substitui o Protetor Solar ou o Hidratante? Não. o Primer Faz Parte da Sua Rotina de Maquiagem, Mas Não Substitui o Hidratante Facial Nem o Protetor Solar. o Glow Skin Deve Ser Aplicado Depois do Skincare: Primeiro Você Limpa, Tonifica, Hidrata e Aplica a Proteção Solar. Só Então Entra o Primer — E, Na Sequência, a Maquiagem.', 79.9, 55.9, NULL, 'Beauty > Makeup > Face', 'https://cf.shopee.com.br/file/sg-11134201-8258e-mr25c6loqubl41', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F842559166%2F22094239271', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '48757653207', 'Impermeabilizante Líquido Milagroso Vedatudo 300g Dryko', 'Impermeabilizante Líquido Milagroso Vedatudo 300g Dryko CARACTERÍSTICAS: - Garantia: 3 Meses - Tipo: Impermeabilizante líquido - Peso líquido: 300 g - Cor: Incolor - Acabamento: Brilhante - Composição: Monocomponente (pronto para uso) - Secagem: Rápida - Odor: Sem odor - Aplicação: Pincel, espátula ou rolo - Indicação de uso: Reparos em infiltrações, fissuras e superfícies expostas à umidade - Resistência: Alta resistência à água e intempéries - Aderência: Excelente em superfícies porosas e absorventes - Aplicação: Ambientes internos e externos - Marca: Dryko - Linha / Modelo: Vedatudo - Código de referência: IMPERMIL DETALHES: - O Impermeabilizante Líquido Vedatudo Dryko foi desenvolvido para proporcionar proteção eficiente contra infiltrações, umidade e intempéries em diversas superfícies. - Produto monocomponente pronto para uso, oferecendo praticidade e facilidade na aplicação sem necessidade de mistura. - Possui secagem rápida e não apresenta odor, sendo ideal para uso em ambientes fechados sem causar incômodos. - Sua fórmula proporciona excelente aderência em superfícies porosas e absorventes, garantindo maior eficiência na vedação. - Indicado para reparos em áreas com infiltração, fissuras e microfissuras, além de aplicações em peitoris, frestas de janelas, perímetros de box de banheiro, telhados e calhas de concreto. - Também pode ser utilizado em superfícies de madeira expostas à umidade, oferecendo proteção duradoura. - Apresenta alta resistência à água e às condições climáticas, contribuindo para maior durabilidade da aplicação. - Produto incolor com acabamento brilhante que não altera a aparência original da superfície. - Pode ser aplicado com pincel, rolo ou espátula, facilitando o uso em diferentes tipos de reparos. - Não tóxico e sem cheiro, proporcionando mais segurança durante a aplicação. - Excelente opção para quem busca solução prática, eficiente e com ótimo custo-benefício para reparos pontuais.', 42.9, 34.7, NULL, 'Home & Living > Tools & Home Improvement > Industrial Adhesives & Tapes', 'https://cf.shopee.com.br/file/sg-11134201-82612-mm7teh21u8lg4d', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F844004880%2F48757653207', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
