INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '58203944590', 'Conjunto Curto Listrado Menina Marisol', 'O conjunto curto da Marisol é todo estampado com listras, combinando modernidade e frescor em um único look. A camisa possui mangas levemente bufantes e modelagem mais ampla, proporcionando conforto e um caimento elegante. O shorts, confeccionado em meia malha, conta com cós elástico, garantindo ajuste perfeito e praticidade. Leve e versátil, o conjunto é ideal para os dias quentes, oferecendo estilo e liberdade de movimento em qualquer ocasião.', 139.9, 69.95, NULL, 'Baby & Kids Fashion > Girl Clothes > Suits & Sets', 'https://cf.shopee.com.br/file/sg-11134201-8262o-mju7kv0dw5c1d3', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F980954412%2F58203944590', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '42977036948', 'O Mundo De Anne Frank | Janny van der Molen', 'Livro O Mundo De Anne Frank | Janny van der Molen Lá Fora, a GuerraJanny van der MolenMais do que um diário, a história de Anne Frank é um testemunho universal de esperança, coragem e humanidade em meio ao horror. Em "O Mundo de Anne Frank", Janny van der Molen reconta, com sensibilidade e cuidado, a trajetória da jovem judia que se escondeu com a família durante a Segunda Guerra Mundial. Com apoio da Fundação Anne Frank, a autora combina trechos do diário original, informações históricas, fotografias e ilustrações delicadas para tornar essa narrativa acessível e comovente para leitores jovens e adultos. Esta edição especial, que chega em meio às reflexões sobre os 70 anos do fim da guerra, não apenas preserva a memória de Anne, mas também convida uma nova geração a conhecer sua voz – uma voz que continua a inspirar o mundo com sua força, sonhos e resistência frente à adversidade. O que você vai encontrar neste livro: Recontagem acessível e sensível da história de Anne FrankCombinação de diário, contexto histórico, fotografias e ilustraçõesEdição autorizada com apoio da Fundação Anne FrankIdeal para: Jovens leitores que estão conhecendo a história de Anne Frank pela primeira vezEscolas e educadores que buscam recursos para abordar o Holocausto e a Segunda GuerraFamílias que desejam compartilhar uma narrativa histórica importante com sensibilidadeAdquira já "O Mundo de Anne Frank" e permita-se ser tocado por uma das histórias mais humanas e necessárias do século XX, contada com a delicadeza que sua memória merece.', 70.79, 70.79, NULL, 'Books & Magazines > Books > History & Cultures', 'https://cf.shopee.com.br/file/sg-11134201-822xa-mhwdoah3x5ad98', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F400905650%2F42977036948', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
