INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '42080139185', 'Kit Palheta Limpador Parabrisa Citroen C3 Paleta Limpador do Parabrisa Citroen C3 2003 à 2012', 'A Palheta Limpador Parabrisa Silicone C3 da marca Besser Store é a escolha ideal para quem busca eficiência e durabilidade. Com medidas de 57 cm para a palheta do condutor e 45 cm para a palheta acompanhante, este produto garante uma limpeza eficaz e sem manchas, proporcionando visibilidade em todas as condições climáticas. Desenvolvida para veículos como carros e caminhonetes, a montagem é feita na parte dianteira, assegurando um encaixe perfeito e fácil manuseio. A tecnologia em silicone utilizada na fabricação oferece maior resistência ao desgaste e uma performance superior em comparação com palhetas convencionais. A Palheta Limpador Parabrisa Silicone C3 é perfeita para motoristas que valorizam segurança e conforto ao dirigir. Invista na qualidade e na performance que seu veículo merece, garantindo uma experiência de condução mais segura e tranquila. APLICAÇÃO: C3 2003 à 2012 Especificação Técnica: - Modelo da palheta: Encaixe e gancho - Fabricada em Plástico e Borracha - Maior Durabilidade e Resistência - Encaixe Sob Medida - Haste Maleável que se Ajusta ao Vidro - Não Risca - Melhor Aderência e Limpeza - Design Diferenciado - Evita Riscos - Fácil Instalação por Encaixe com Trava - Modelo de borracha flexível siliconada (SILICONE). A INSTALAÇÃO DEVE SER EFETUADA APENAS POR PROFISSIONAIS CAPACITADOS. ACOMPANHA NOTA FISCAL ENVIO IMEDIATO', 78.99, 34.99, NULL, 'Spare Parts and Accessories for Vehicles > Spare Parts for Automobiles > External Parts', 'https://cf.shopee.com.br/file/br-11134207-820lg-mn5odejexla8d9', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1505013914%2F42080139185', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
