INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '14977099152', '10 Cake Board 35m PRATA Redondo Base Para Bolo Suplat Para Confeitaria de Alta Resistência e Impermeável', 'CAKE BOARD BRANCO (BASES LAMINADAS PARA BOLO), LINHA PREMIUM, 10 unidades PRATA Bases laminadas para bolos, pudins e tortas, produzidas com papelão especial que passa por um processo de dupla laminação. A frente é laminada com filme de poliéster metalizado e o fundo, branco, é laminado com filme transparente, resultando num produto bonito e de melhor qualidade. A dupla laminação proporciona ainda proteção contra umidade, facilidade de higienização e maior resistência à refrigeração. RESISTENTES, COM PROTEÇÃO CONTRA UMIDADE, MAIS HIGIÊNICAS E PODEM SER REFRIGERADAS', 63.15, 63.15, NULL, 'Stationery > Gift & Wrapping > Gift Wrappers', 'https://cf.shopee.com.br/file/eda81117c050e1db263e82bddebc0540', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F455834389%2F14977099152', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
